returns public.app_role[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select array_agg(x::public.app_role)
                     from public.app_settings s, jsonb_array_elements_text(s.value) x
                    where s.key = p_key and jsonb_typeof(s.value) = 'array'), '{}')
$$;

