-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects module framework step 4 (third batch): Built features and
-- Enquiries follow the Access page as well as the role rules. Built features:
-- view = see them all, create = fill them in, set up = the same manager tools
-- the system admin allowed for managers in the Feature builder. Nobody loses
-- access; people with no admin access given skip the extra check straight away.
-- No new SECURITY DEFINER function (four existing ones gain the extra rule).

CREATE OR REPLACE FUNCTION public.can_see_feature(p_feature uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.is_member() and public.custom_feature_live(p_feature)
     and (public.my_role() = 'system_admin'
          or exists (select 1 from public.custom_features where id = p_feature and public.my_role() = any (see_roles))
          -- cmeprojects step 4: or given Built features (view) on the Access page.
          or (exists (select 1 from public.access_grants g where g.user_id = auth.uid() and g.area is null and g.revoked_at is null)
                and public.can('ops.features', 'view')))
$function$;

CREATE OR REPLACE FUNCTION public.can_fill_feature(p_feature uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.is_member() and public.custom_feature_live(p_feature)
     and (public.my_role() = 'system_admin'
          or exists (select 1 from public.custom_features where id = p_feature and public.my_role() = any (fill_roles))
          -- cmeprojects step 4: or given Built features (create) on the Access page.
          or (exists (select 1 from public.access_grants g where g.user_id = auth.uid() and g.area is null and g.revoked_at is null)
                and public.can('ops.features', 'create')))
$function$;

CREATE OR REPLACE FUNCTION public.can_manage_feature(p_feature uuid, p_what text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.can_build_features()
      or (public.is_member() and public.mfa_ok() and (public.my_role() = 'manager'
               -- cmeprojects step 4: or given Built features (set up): the same manager tools.
               or (exists (select 1 from public.access_grants g where g.user_id = auth.uid() and g.area is null and g.revoked_at is null)
                and public.can('ops.features', 'configure')))
          and public.custom_feature_live(p_feature)
          and exists (select 1 from public.custom_features
                       where id = p_feature
                         and case p_what when 'fix' then managers_fix when 'targets' then managers_targets
                                         when 'options' then managers_options else false end))
$function$;

CREATE OR REPLACE FUNCTION public.can_see_enquiries()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.is_member() and (public.is_system_admin()
    or public.my_role()::text in (select jsonb_array_elements_text(coalesce(
         (select value from public.app_settings where key = 'assistant.enquiry_roles'), '[]')))
    -- cmeprojects step 4: or given Enquiries on the Access page.
    or (exists (select 1 from public.access_grants g where g.user_id = auth.uid() and g.area is null and g.revoked_at is null)
                and public.can('engagement.enquiries', 'view')))
$function$;

$m094$;
  insert into public.install_log (name) values ('20270121000001_step4_features_enquiries.sql');
end;
$part$;

-- ====================================================================
-- 20270122000001_step4_contracts.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270122000001_step4_contracts.sql') then
    return;
  end if;
  execute $m095$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects module framework step 4: Contracts follow the Access page, with
-- each ability as its own tick (the owner's decision, 13 Nov 2026):
--   view               see a person's contracts (any tick shows them; each
--                      action below still needs its own tick)
--   create             prepare, send to sign, cancel, delete drafts
--   sign_for_employer  countersign, complete, add the signed copy
--   download           open the signed copy
-- People with Staff details access keep everything they have today. Contracts
-- are sensitive: never included by turning on the whole HR category.
-- No new SECURITY DEFINER function (contract_access is SECURITY INVOKER).

-- The staff-details rule as before, OR the Contracts tick for that action and person.
create or replace function public.contract_access(p_action text, p_person uuid)
returns boolean
language sql
stable
security invoker
set search_path = ''
as $$
  select public.has_access('staff_details', p_person)
      or (exists (select 1 from public.access_grants g
                   where g.user_id = auth.uid() and g.area is null and g.module_id = 'hr.contracts' and g.revoked_at is null)
          and (case when p_action = 'any'
                    then public.can('hr.contracts', 'view', p_person) or public.can('hr.contracts', 'create', p_person)
                      or public.can('hr.contracts', 'sign_for_employer', p_person) or public.can('hr.contracts', 'download', p_person)
                    else public.can('hr.contracts', p_action, p_person) end))
$$;
revoke execute on function public.contract_access(text, uuid) from public, anon;
grant execute on function public.contract_access(text, uuid) to authenticated;

drop policy if exists "sign as yourself, at the right step" on public.contract_signatures;
create policy "sign as yourself, at the right step" on public.contract_signatures
  for insert to authenticated
  with check (((signer_id = ( SELECT auth.uid() AS uid)) AND ( SELECT is_member() AS is_member) AND (EXISTS ( SELECT 1
   FROM contracts c
  WHERE ((c.id = contract_signatures.contract_id) AND (c.content_hash = contract_signatures.content_hash) AND (((contract_signatures.party = 'employee'::text) AND (c.user_id = ( SELECT auth.uid() AS uid)) AND (c.status = 'awaiting_employee'::text) AND ((c.sign_by IS NULL) OR (c.sign_by >= local_today()))) OR ((contract_signatures.party = 'employer'::text) AND (c.user_id <> ( SELECT auth.uid() AS uid)) AND (c.status = 'awaiting_employer'::text) AND public.contract_access('sign_for_employer', c.user_id))))))));

drop policy if exists "contracts: drafts can be deleted" on public.contracts;
create policy "contracts: drafts can be deleted" on public.contracts
  for delete to authenticated
  using (((status = 'draft'::text) AND (user_id <> ( SELECT auth.uid() AS uid)) AND public.contract_access('create', user_id)));

drop policy if exists "contracts: people with access prepare them" on public.contracts;
create policy "contracts: people with access prepare them" on public.contracts
  for insert to authenticated
  with check ((( SELECT is_member() AS is_member) AND (status = 'draft'::text) AND (user_id <> ( SELECT auth.uid() AS uid)) AND public.contract_access('create', user_id)));

drop policy if exists "contracts: people with access, or the employee signing" on public.contracts;
create policy "contracts: people with access, or the employee signing" on public.contracts
  for update to authenticated
  using ((( SELECT is_member() AS is_member) AND (((user_id <> ( SELECT auth.uid() AS uid)) AND (public.contract_access('create', user_id) OR public.contract_access('sign_for_employer', user_id))) OR ((user_id = ( SELECT auth.uid() AS uid)) AND (status = 'awaiting_employee'::text)))))
  with check ((( SELECT is_member() AS is_member) AND (((user_id <> ( SELECT auth.uid() AS uid)) AND (public.contract_access('create', user_id) OR public.contract_access('sign_for_employer', user_id))) OR (user_id = ( SELECT auth.uid() AS uid)))));

drop policy if exists "contracts: the employee and people with access" on public.contracts;
create policy "contracts: the employee and people with access" on public.contracts
  for select to authenticated
  using ((( SELECT is_member() AS is_member) AND (((user_id = ( SELECT auth.uid() AS uid)) AND (status <> 'draft'::text)) OR public.contract_access('any', user_id))));

do $do$
begin
  if to_regclass('storage.objects') is null then
    return;
  end if;
  execute $q$drop policy if exists "contracts: the employee and people with access add files" on storage.objects$q$;
  execute $q$create policy "contracts: the employee and people with access add files" on storage.objects
  for insert to authenticated
  with check (((bucket_id = 'contracts'::text) AND ( SELECT is_member() AS is_member) AND (((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text) OR public.contract_access('sign_for_employer', ((storage.foldername(name))[1])::uuid))))$q$;
  execute $q$drop policy if exists "contracts: the employee and people with access read" on storage.objects$q$;
  execute $q$create policy "contracts: the employee and people with access read" on storage.objects
  for select to authenticated
  using (((bucket_id = 'contracts'::text) AND (((storage.foldername(name))[1] = (( SELECT auth.uid() AS uid))::text) OR (public.contract_access('download', ((storage.foldername(name))[1])::uuid) OR public.contract_access('sign_for_employer', ((storage.foldername(name))[1])::uuid)))))$q$;
end $do$;

-- The contract guard: each step checks its own tick.
CREATE OR REPLACE FUNCTION public.guard_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_by uuid := auth.uid();
  v_prepare boolean; -- prepare, send, cancel (cmeprojects step 4: its own tick)
  v_sign boolean;    -- sign for the employer and complete
begin
  if tg_op = 'INSERT' then
    new.status := 'draft';
    new.created_by := v_by;
    new.content_hash := '';
    new.signed_pdf_path := '';
    new.signed_pdf_hash := '';
    new.sent_at := null;
    new.sent_by := null;
    new.completed_at := null;
    if new.supersedes is not null then
      if not exists (select 1 from public.contracts o where o.id = new.supersedes and o.user_id = new.user_id) then
        raise exception 'A new version must be for the same person.';
      end if;
      new.version := (select max(version) + 1 from public.contracts where id = new.supersedes or supersedes = new.supersedes);
    else
      new.version := 1;
    end if;
    return new;
  end if;

  new.updated_at := now();
  if v_by is null then
    return new; -- the daily job (expiring unsigned contracts)
  end if;
  v_prepare := new.user_id <> v_by and public.contract_access('create', new.user_id);
  v_sign := new.user_id <> v_by and public.contract_access('sign_for_employer', new.user_id);

  -- Once sent, the wording and who it's for never change.
  if old.status <> 'draft' and (new.title is distinct from old.title or new.body is distinct from old.body or new.user_id is distinct from old.user_id
      or new.version is distinct from old.version or new.supersedes is distinct from old.supersedes or new.content_hash is distinct from old.content_hash
      or new.sign_by is distinct from old.sign_by) then
    raise exception 'A sent contract can''t be changed. Make a new version instead.';
  end if;
  if new.signed_pdf_path is distinct from old.signed_pdf_path or new.signed_pdf_hash is distinct from old.signed_pdf_hash then
    if not (old.status = 'awaiting_employer' and new.status = 'fully_signed' and v_sign and old.signed_pdf_path = '') then
      raise exception 'The signed copy can only be added when the contract is fully signed.';
    end if;
  end if;

  if new.status is distinct from old.status then
    if old.status = 'draft' and new.status = 'awaiting_employee' and v_prepare then
      new.content_hash := encode(sha256(convert_to(new.title || E'\n' || new.body, 'UTF8')), 'hex');
      new.sent_at := now();
      new.sent_by := v_by;
    elsif old.status in ('draft', 'awaiting_employee', 'awaiting_employer') and new.status = 'cancelled' and (v_prepare or v_sign) then
      null;
    elsif old.status = 'awaiting_employee' and new.status = 'expired' and (v_prepare or v_sign) and new.sign_by < public.local_today() then
      null;
    elsif old.status = 'awaiting_employee' and new.status = 'awaiting_employer'
          and exists (select 1 from public.contract_signatures s where s.contract_id = new.id and s.party = 'employee' and s.content_hash = new.content_hash) then
      null;
    elsif old.status = 'awaiting_employer' and new.status = 'fully_signed' and v_sign
          and new.signed_pdf_path <> '' and new.signed_pdf_hash ~ '^[0-9a-f]{64}$'
          and exists (select 1 from public.contract_signatures s where s.contract_id = new.id and s.party = 'employer' and s.content_hash = new.content_hash) then
      new.completed_at := now();
    elsif old.status = 'fully_signed' and new.status = 'superseded' and v_sign
          and exists (select 1 from public.contracts n where n.supersedes = new.id and n.status = 'fully_signed') then
      null;
    else
      raise exception 'That step isn''t allowed for this contract right now.';
    end if;
  elsif old.status <> 'draft' and (to_jsonb(new) - 'updated_at') is distinct from (to_jsonb(old) - 'updated_at') then
    raise exception 'A sent contract can''t be changed. Make a new version instead.';
  end if;
  if old.status = 'draft' and not v_prepare then
    raise exception 'You don''t have access to prepare contracts for this person.';
  end if;
  return new;
end;
$function$;

$m095$;
  insert into public.install_log (name) values ('20270122000001_step4_contracts.sql');
end;
$part$;

-- ====================================================================
-- 20270123000001_role_after_clearance.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270123000001_role_after_clearance.sql') then
    return;
  end if;
  execute $m096$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects: a new starter can only be given another role once they're
-- cleared to work (Onboarding → Clear to work). Before that, including when
-- their account isn't set up or onboarding hasn't started, the only way is a
-- conditional role with a deadline. With the Onboarding feature switched off,
-- the earlier rule (onboarding items for the new role finished) still applies.
-- No new SECURITY DEFINER function.

CREATE OR REPLACE FUNCTION public.guard_profile_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := auth.uid();
begin
  if new.id <> old.id or new.email <> old.email or new.org_id <> old.org_id then
    raise exception 'This field cannot be changed here';
  end if;

  -- Names (cmeprojects Phase 2): your own only while it's still blank (account
  -- set-up); someone else's with a Staff details grant covering them, or as the
  -- system admin. System jobs (no signed-in person) aren't affected.
  if actor is not null and new.full_name is distinct from old.full_name then
    if new.id = actor and coalesce(trim(old.full_name), '') <> '' and not public.is_system_admin() then
      raise exception 'Your name is set by the office. Ask your manager or the system admin to change it.';
    end if;
    if new.id <> actor and not public.has_access('staff_details', new.id) then
      raise exception 'You don''t have access to change this person''s name. The system admin can give you access.';
    end if;
    if new.id <> actor and old.role = 'system_admin' and not public.is_system_admin() then
      raise exception 'Only a system admin can rename a system admin';
    end if;
    perform public.write_audit('name_changed', 'profile', new.id::text,
      jsonb_build_object('from', old.full_name, 'to', new.full_name));
  end if;

  if actor is not null then
    if new.role is distinct from old.role
       or new.team_id is distinct from old.team_id
       or new.active is distinct from old.active then

      if not public.can_manage_people() then
        raise exception 'Only managers and admins can change roles, teams or access';
      end if;

      if new.id = actor and (new.role is distinct from old.role or not new.active) then
        raise exception 'You cannot change your own role or deactivate yourself';
      end if;

      if new.id <> actor and (not public.can_manage_role(old.role) or not public.can_manage_role(new.role)) then
        raise exception 'Only a system admin can manage system admins';
      end if;

      -- cmeprojects (update 79): a new starter gets another role only once
      -- cleared to work (with onboarding on); otherwise a conditional role.
      if old.role = 'new_starter' and new.role <> 'new_starter'
         and coalesce(current_setting('app.conditional_role', true), '') <> 'on'
         and public.feature_enabled('compliance') and old.cleared_at is null then
        raise exception 'They aren''t cleared to work yet. Clear them to work first (Onboarding), or give a conditional role with a deadline.';
      end if;
      if old.role = 'new_starter' and new.role <> 'new_starter'
         and coalesce(current_setting('app.conditional_role', true), '') <> 'on'
         and cardinality(public.onboarding_missing(new.id, new.role, null)) > 0 then
        raise exception 'They haven''t finished onboarding yet. Give a conditional role with a deadline instead.';
      end if;

      if new.role is distinct from old.role and public.my_role() = 'staff_admin'
         and public.rule_on('people.staff_admin_role_approval')
         and (old.role <> 'new_starter' or public.rule_on('people.first_role_approval')) then
        raise exception 'Role changes by a staff admin need a manager''s approval. Send it as a request.';
      end if;
      if new.team_id is distinct from old.team_id and public.my_role() = 'staff_admin'
         and public.rule_on('people.staff_admin_team_approval') then
        raise exception 'Team changes by a staff admin need a manager''s approval. Send it as a request.';
      end if;
    end if;
  end if;

  if actor is not null and not public.is_system_admin()
     and old.role = 'manager' and old.active
     and (new.role <> 'manager' or not new.active)
     and not exists (select 1 from public.profiles where role = 'manager' and active and id <> old.id) then
    raise exception 'They''re the only manager left, so they can''t be deactivated or given another role. Add another manager first.';
  end if;

  if old.role = 'system_admin' and old.active
     and (new.role <> 'system_admin' or not new.active)
     and not exists (
       select 1 from public.profiles
        where role = 'system_admin' and active and id <> old.id
     ) then
    raise exception 'There must always be at least one active system admin';
  end if;

  if new.active and not old.active then
    new.deactivated_at := null;
  elsif not new.active and old.active then
    new.deactivated_at := now();
  end if;

  if new.role is distinct from old.role then
    perform public.write_audit('role_changed', 'profile', new.id::text,
      jsonb_build_object('from', old.role, 'to', new.role));
  end if;
  if new.active is distinct from old.active then
    perform public.write_audit(
      case when new.active then 'reactivated' else 'deactivated' end,
      'profile', new.id::text, '{}'::jsonb);
  end if;
  if new.team_id is distinct from old.team_id then
    perform public.write_audit('team_changed', 'profile', new.id::text,
      jsonb_build_object('from', old.team_id, 'to', new.team_id));
  end if;

  return new;
end;
$function$;

$m096$;
  insert into public.install_log (name) values ('20270123000001_role_after_clearance.sql');
end;
$part$;

-- ====================================================================
-- 20270124000001_audit_stage_a.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270124000001_audit_stage_a.sql') then
    return;
  end if;
  execute $m097$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects audit fixes (Stage A):
--   1. Clearing someone who is already cleared to work is refused, so it no
--      longer sends a second "You're cleared to work" notice or overwrites who
--      cleared them and when. Only grant_clearance changes (same permissions,
--      same checks otherwise).
--   2. The help text of one setting (tasks.limited_roles) names the renamed
--      My tasks tab ("Raised by me"). Text only; its value doesn't change.
-- No table, policy or permission changes. No new SECURITY DEFINER function.

CREATE OR REPLACE FUNCTION public.grant_clearance(p_user uuid, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.profiles;
  v_missing text[];
  v_rest text[];
begin
  if not public.can_grant_clearance() then
    raise exception 'Only managers (or staff admins they''ve delegated to) can clear people to work';
  end if;
  select * into p from public.profiles where id = p_user;
  if p.id is null or not p.active then
    raise exception 'Person not found';
  end if;
  if p_user = auth.uid() then
    raise exception 'Someone else needs to clear you to work';
  end if;
  -- cmeprojects (update 80): clearing someone already cleared does nothing
  -- else (no second notice, and who cleared them and when stay as they were).
  if p.cleared_at is not null then
    raise exception 'They''re already cleared to work.';
  end if;
  v_missing := public.before_work_missing(p_user);
  if cardinality(v_missing) > 0 then
    raise exception 'Still needed before working: %. Finish and check these first, or give an override.', array_to_string(v_missing, ', ');
  end if;
  update public.profiles set cleared_at = now(), cleared_by = auth.uid() where id = p_user;
  v_rest := public.onboarding_missing(p_user);
  perform public.finish_onboarding_task(p_user);
  perform public.notify(p_user, 'cleared_to_work', 'You''re cleared to work',
    case when cardinality(v_rest) > 0 then 'Please finish the rest of your onboarding within a week.' else '' end, '/onboarding', true);
  perform public.write_audit('cleared_to_work', 'profile', p_user::text, jsonb_build_object('note', p_note, 'still_to_do', v_rest));
end;
$function$;

update public.app_settings set description = 'They don''t see the other registers in New task. They follow what they raised in My tasks → Raised by me.'
 where key = 'tasks.limited_roles' and description = 'They don''t see the other registers in New task. They follow what they raised in My tasks → My requests and questions.';

$m097$;
  insert into public.install_log (name) values ('20270124000001_audit_stage_a.sql');
end;
$part$;

-- ====================================================================
-- 20270125000001_onboarding_stage_b.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270125000001_onboarding_stage_b.sql') then
    return;
  end if;
  execute $m098$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects audit Stage B: onboarding and clearance (owner's decisions,
-- 15 Nov 2026).
--   * "Onboarding complete" includes bank details, super, right to work and
--     the TFN declaration (with the onboarding checklist).
--   * Checked right to work is needed before someone can be cleared to work.
--     People already cleared stay cleared: nothing is removed automatically.
--   * Bank, super and TFN can be finished after clearance, within 7 days.
--   * work_status shows the three parts: minimum to work, still to finish, and
--     the finish-by date (and the note from the clearance).
-- Two new helper functions (SECURITY INVOKER, read-only). No tables, policies
-- or permissions change. No new SECURITY DEFINER function.

-- Right to work in Australia, checked by someone with access (needed before
-- clearing). Not for system admins or external accounts.
create or replace function public.right_to_work_missing(p_user uuid, p_role public.app_role default null)
returns text[]
language sql
stable
security invoker
set search_path = ''
as $$
  select case
    when not public.feature_enabled('compliance') then '{}'::text[]
    when coalesce(p_role, (select role from public.profiles where id = p_user)) in ('system_admin', 'external') then '{}'::text[]
    when exists (select 1 from public.staff_work_rights w where w.user_id = p_user and w.verified_at is not null) then '{}'::text[]
    else array['Right to work in Australia (checked)']
  end
$$;
revoke execute on function public.right_to_work_missing(uuid, public.app_role) from public, anon;

-- Bank, super, right to work and TFN: part of "onboarding complete".
create or replace function public.pay_onboarding_missing(p_user uuid, p_role public.app_role default null)
returns text[]
language sql
stable
security invoker
set search_path = ''
as $$
  select case
    when not public.feature_enabled('compliance') then '{}'::text[]
    when coalesce(p_role, (select role from public.profiles where id = p_user)) in ('system_admin', 'external') then '{}'::text[]
    else array_remove(array[
      case when not exists (select 1 from public.staff_bank b where b.user_id = p_user and coalesce(b.account_number, '') <> '') then 'Bank account for your pay' end,
      case when not exists (select 1 from public.staff_super s where s.user_id = p_user and coalesce(s.fund_name, '') <> '') then 'Superannuation' end,
      case when not exists (select 1 from public.staff_tax t where t.user_id = p_user and coalesce(t.form_path, '') <> '') then 'Tax file number declaration' end
    ], null) || public.right_to_work_missing(p_user, p_role)
  end
$$;
revoke execute on function public.pay_onboarding_missing(uuid, public.app_role) from public, anon;

CREATE OR REPLACE FUNCTION public.onboarding_missing(p_user uuid, p_role app_role DEFAULT NULL::app_role, p_teams uuid[] DEFAULT NULL::uuid[])
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select (case when public.profile_required(p_user) then array['Complete your profile'] else '{}'::text[] end)
      || coalesce((select array_agg(s.title order by array_position(array['read', 'training', 'upload', 'agreement', 'form'], s.kind), s.sort_order, s.title)
                     from public.compliance_status(p_user, p_role, p_teams) s
                    where s.state not in ('done', 'submitted', 'accepted', 'expiring')), '{}')
      -- cmeprojects (update 81): bank, super, right to work and TFN count too.
      || public.pay_onboarding_missing(p_user, p_role)
$function$;

CREATE OR REPLACE FUNCTION public.grant_clearance(p_user uuid, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.profiles;
  v_missing text[];
  v_rest text[];
begin
  if not public.can_grant_clearance() then
    raise exception 'Only managers (or staff admins they''ve delegated to) can clear people to work';
  end if;
  select * into p from public.profiles where id = p_user;
  if p.id is null or not p.active then
    raise exception 'Person not found';
  end if;
  if p_user = auth.uid() then
    raise exception 'Someone else needs to clear you to work';
  end if;
  -- cmeprojects (update 80): clearing someone already cleared does nothing
  -- else (no second notice, and who cleared them and when stay as they were).
  if p.cleared_at is not null then
    raise exception 'They''re already cleared to work.';
  end if;
  -- cmeprojects (update 81): checked right to work is needed before clearing.
  v_missing := public.before_work_missing(p_user) || public.right_to_work_missing(p_user);
  if cardinality(v_missing) > 0 then
    raise exception 'Still needed before working: %. Finish and check these first, or give an override.', array_to_string(v_missing, ', ');
  end if;
  update public.profiles set cleared_at = now(), cleared_by = auth.uid() where id = p_user;
  v_rest := public.onboarding_missing(p_user);
  perform public.finish_onboarding_task(p_user);
  perform public.notify(p_user, 'cleared_to_work', 'You''re cleared to work',
    case when cardinality(v_rest) > 0
         then format('Please finish the rest of your onboarding by %s (7 days).', to_char(public.local_today() + 7, 'FMDD Mon YYYY'))
         else '' end, '/onboarding', true);
  perform public.write_audit('cleared_to_work', 'profile', p_user::text, jsonb_build_object('note', p_note, 'still_to_do', v_rest));
end;
$function$;

CREATE OR REPLACE FUNCTION public.work_status(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.profiles;
  o public.work_overrides;
begin
  if not (p_user = auth.uid() or public.can_manage_compliance() or public.can_manage_people()
          or public.has_role(array['manager']::public.app_role[]) or public.leads_user(p_user)) then
    return null;
  end if;
  select * into p from public.profiles where id = p_user;
  o := public.active_override(p_user);
  return jsonb_build_object(
    'onboarding_complete', p.onboarded_at is not null and cardinality(public.onboarding_missing(p_user)) = 0,
    'onboarded_at', p.onboarded_at,
    'compliance_verified', public.compliance_is_verified(p_user),
    'cleared', p.cleared_at is not null,
    'cleared_at', p.cleared_at,
    'cleared_by', (select coalesce(nullif(full_name, ''), email) from public.profiles where id = p.cleared_by),
    -- cmeprojects (update 81): minimum to work (before clearing, checked right
    -- to work too), what's still to finish, and the 7-day date for it.
    'before_work_missing', to_jsonb(case when p.cleared_at is null
                                         then public.before_work_missing(p_user) || public.right_to_work_missing(p_user)
                                         else public.before_work_missing(p_user) end),
    'still_to_finish', to_jsonb(public.onboarding_missing(p_user)),
    'finish_by', case when p.cleared_at is not null and cardinality(public.onboarding_missing(p_user)) > 0
                      then ((p.cleared_at at time zone 'Australia/Sydney')::date + 7) end,
    'cleared_note', (select a.details ->> 'note' from public.audit_log a
                      where a.action = 'cleared_to_work' and a.entity_id = p_user::text order by a.id desc limit 1),
    'can_work', public.can_work(p_user),
    'override', case when o.id is null then null else jsonb_build_object('id', o.id, 'reason', o.reason, 'until', o.until_date,
                  'by', (select coalesce(nullif(full_name, ''), email) from public.profiles where id = o.granted_by)) end);
end;
$function$;

$m098$;
  insert into public.install_log (name) values ('20270125000001_onboarding_stage_b.sql');
end;
$part$;

-- ====================================================================
-- 20270126000001_escalation_once.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270126000001_escalation_once.sql') then
    return;
  end if;
  execute $m099$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects: automatic escalation happens once per due date. Before, when a
-- manager dealt with an escalated task (back to In progress) without moving
-- its due date, the next hourly run escalated it again straight away. Only
-- run_due_alerts changes. No tables, policies or permissions change.

CREATE OR REPLACE FUNCTION public.run_due_alerts(p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tz text := coalesce((select value #>> '{}' from public.app_settings where key = 'region.timezone'), 'Australia/Melbourne');
  v_now timestamp := p_now at time zone v_tz;
  v_today date := v_now::date;
  v_weekdays boolean := coalesce((select (value #>> '{}')::boolean from public.app_settings where key = 'tasks.sla_weekdays_only'), false);
  v_remind int := coalesce((select (value #>> '{}')::int from public.app_settings where key = 'tasks.sla_remind_days'), 1);
  v_escalate int := coalesce((select (value #>> '{}')::int from public.app_settings where key = 'tasks.sla_escalate_days'), 3);
  v_summary boolean := coalesce((select (value #>> '{}')::boolean from public.app_settings where key = 'tasks.sla_manager_summary'), true);
  v_summary_hour int := coalesce((select (value #>> '{}')::int from public.app_settings where key = 'tasks.summary_hour'), 7);
  v_weekend boolean := extract(isodow from v_today) >= 6;
  t record;
  v_late int;
  v_person uuid;
  v_leaders uuid[];
  v_escalated int := 0;
  v_summaries int := 0;
  v_list jsonb;
begin
  if not public.feature_enabled('tasks') then
    return jsonb_build_object('skipped', 'tasks are switched off');
  end if;
  -- With "weekdays only", nothing is sent at the weekend; Monday catches up.
  if v_weekdays and v_weekend then
    return jsonb_build_object('skipped', 'weekend');
  end if;

  for t in
    select id, assigned_to, due_date, status, escalated
      from public.tasks
     where due_date is not null
       and status not in ('completed', 'closed')
       and due_date <= v_today + greatest(v_remind, 0) + 7
  loop
    v_late := public.working_days_between(t.due_date, v_today, v_weekdays);

    if t.due_date > v_today then
      if v_remind > 0 and -v_late <= v_remind then
        perform public.send_due_alert(t.id, t.assigned_to, 'reminder', t.due_date);
      end if;
      continue;
    end if;

    if t.due_date = v_today then
      perform public.send_due_alert(t.id, t.assigned_to, 'due_today', t.due_date);
      for v_person in select user_id from public.task_helpers where task_id = t.id loop
        perform public.send_due_alert(t.id, v_person, 'due_today', t.due_date);
      end loop;
      continue;
    end if;

    -- Overdue: the person and their team leaders (managers if there are none).
    perform public.send_due_alert(t.id, t.assigned_to, 'overdue', t.due_date);
    select coalesce(array_agg(distinct tl.user_id), '{}') into v_leaders
      from public.team_members m
      join public.team_leaders tl on tl.team_id = m.team_id
      join public.profiles p on p.id = tl.user_id and p.active
     where m.user_id = t.assigned_to and tl.user_id <> t.assigned_to;
    if cardinality(v_leaders) = 0 then
      select coalesce(array_agg(m), '{}') into v_leaders from public.task_managers(t.id) m;
    end if;
    foreach v_person in array v_leaders loop
      perform public.send_due_alert(t.id, v_person, 'overdue', t.due_date);
    end loop;

    -- Still overdue: managers, and the task is marked escalated.
    if v_escalate > 0 and v_late >= v_escalate and public.feature_enabled('auto_escalation') then
      -- cmeprojects (update 82): once per due date. If it has already been
      -- escalated since it fell due (automatically or by someone) and a
      -- manager dealt with it (back to In progress), don't escalate it again
      -- for the same due date; a new due date starts afresh.
      if t.status <> 'escalated'
         and not exists (select 1 from public.task_events e
                          where e.task_id = t.id and e.to_value = 'escalated'
                            and e.created_at >= t.due_date::timestamptz) then
        update public.tasks set status = 'escalated', escalated = true, updated_at = now() where id = t.id;
        insert into public.task_events (task_id, actor_id, type, from_value, to_value, comment)
        values (t.id, null, 'status_changed', t.status::text, 'escalated',
                format('Escalated automatically: %s days overdue', v_late));
        v_escalated := v_escalated + 1;
      end if;
      for v_person in select m from public.task_managers(t.id) m loop
        perform public.send_due_alert(t.id, v_person, 'escalated', t.due_date);
      end loop;
    end if;
  end loop;

  -- The morning summary, once each weekday from 7am.
  if v_summary and not v_weekend and extract(hour from v_now) >= v_summary_hour and public.feature_enabled('email_notifications') then
    insert into public.daily_runs (job, day) values ('manager_summary', v_today) on conflict do nothing;
    if found then
      select jsonb_agg(jsonb_build_object(
               'id', t2.id,
               'ref', coalesce(r.prefix, 'T') || '-' || lpad(t2.ref_number::text, 4, '0'),
               'title', t2.title,
               'registry', r.name,
               'assignee', case when p.role = 'system_admin' then 'Admin' else coalesce(nullif(p.full_name, ''), p.email) end,
               'due_date', t2.due_date,
               'days_late', public.working_days_between(t2.due_date, v_today, v_weekdays),
               'escalated', t2.status = 'escalated')
             order by t2.due_date, t2.ref_number)
        into v_list
        from public.tasks t2
        join public.registries r on r.id = t2.registry_id
        join public.profiles p on p.id = t2.assigned_to
       where t2.due_date < v_today and t2.status not in ('completed', 'closed');
      if v_list is not null then
        insert into public.email_outbox (to_user, template, data)
        select id, 'overdue_summary', jsonb_build_object('tasks', v_list, 'day', v_today)
          from public.profiles where active and role = 'manager';
        get diagnostics v_summaries = row_count;
      end if;
    end if;
  end if;

  return jsonb_build_object('today', v_today, 'escalated', v_escalated, 'summaries', v_summaries);
end;
$function$;

$m099$;
  insert into public.install_log (name) values ('20270126000001_escalation_once.sql');
end;
$part$;

-- ====================================================================
-- 20270127000001_leader_private_view.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270127000001_leader_private_view.sql') then
    return;
  end if;
  execute $m100$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects (update 84): team leaders get only what they need from private
-- details. Before, the read rule on staff_private let a team leader read the
-- whole row for their team (address, emergency contact, employee ID,
-- employment type, start date). Now:
--   * the read rule keeps the person, people managers and the system admin,
--     exactly as before, and drops the team leader part (same Stage 1 form);
--   * team_private() gives a team leader, for their own teams only:
--     availability and start date (for work anniversaries), and the emergency
--     contact only when the system admin turns on "Team leaders see emergency
--     contacts" (off by default);
--   * nothing else changes: writes, other tables and other roles are untouched.
-- team_private() is SECURITY DEFINER (approved by the owner, 15 Nov 2026) so it
-- can read past the narrowed rule; it returns fixed columns for the caller's
-- own teams only.

insert into public.features (key, label, description, enabled, sort_order, premium, included, parent)
values ('hr_leader_emergency', 'Team leaders see emergency contacts',
        'Team leaders can see the emergency contact of people in their teams. When off, they see availability and work anniversaries only.',
        false, 335, false, true, 'hr_profiles')
on conflict (key) do nothing;

alter policy "the person and people managers see private details" on public.staff_private
  using (((select public.feature_enabled('hr_profiles'::text)) AND ((user_id = (select auth.uid())) OR (select public.can_manage_people()) OR (select public.is_system_admin()))));

create or replace function public.team_private()
returns table (user_id uuid, availability jsonb, start_date date, emergency_name text, emergency_phone text)
language sql
stable
security definer
set search_path = ''
as $$
  select sp.user_id, sp.availability, sp.start_date,
         case when e.on_ then coalesce(sp.emergency_name, '') end,
         case when e.on_ then coalesce(sp.emergency_phone, '') end
    from public.staff_private sp
   cross join (select public.feature_live('hr_leader_emergency') as on_) e
   where auth.uid() is not null
     and public.is_member()
     and public.feature_enabled('hr_profiles')
     and sp.user_id <> auth.uid()
     and exists (select 1
                   from public.team_leaders tl
                   join public.team_members tm on tm.team_id = tl.team_id
                  where tl.user_id = auth.uid() and tm.user_id = sp.user_id)
$$;

revoke execute on function public.team_private() from public, anon;
grant execute on function public.team_private() to authenticated;

$m100$;
  insert into public.install_log (name) values ('20270127000001_leader_private_view.sql');
end;
$part$;

-- ====================================================================
-- 20270128000001_managers_unmanaged_registers.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270128000001_managers_unmanaged_registers.sql') then
    return;
  end if;
  execute $m101$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects: managers can act on tasks in registers that have no named
-- managers (for example General tasks), matching who is told about their
-- escalations. Before, every manager was told but none could press
-- "Escalation dealt with". Registers with named managers are unchanged.
-- Only can_edit_task changes. No tables, policies or other permissions.

CREATE OR REPLACE FUNCTION public.can_edit_task(p_task_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.is_member() and exists (
    select 1 from public.tasks t
     where t.id = p_task_id
       and (
         t.assigned_to = auth.uid()
         or t.created_by = auth.uid()
         or public.leads_user(t.assigned_to)
         or (public.has_role(array['manager', 'system_admin']::public.app_role[])
             and exists (select 1 from public.registry_managers rm
                          where rm.registry_id = t.registry_id and rm.user_id = auth.uid()))
         -- cmeprojects (update 83): a register with no named managers is
         -- looked after by every manager (they're the ones told about its
         -- escalations, see task_managers), so they can act on its tasks.
         or (public.has_role(array['manager']::public.app_role[])
             and not exists (select 1 from public.registry_managers rm where rm.registry_id = t.registry_id))
         or public.is_system_admin()
       )
  )
$function$;

$m101$;
  insert into public.install_log (name) values ('20270128000001_managers_unmanaged_registers.sql');
end;
$part$;

-- ====================================================================
-- 20270129000001_client_record.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270129000001_client_record.sql') then
    return;
  end if;
  execute $m102$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects (update 85): Clients & Care step 1: the client record, its
-- permanent reference, status, and the programs list. Builds on the existing
-- client list (car_clients), used by Cars, built features, tasks and teams;
-- no second client table.
--
--   * Every client gets a reference CL-00001, CL-00002 ... made by the
--     database (a sequence): unique, permanent, never reused, never edited.
--     Existing clients get theirs in alphabetical order of name.
--   * Status: pending, active, suspended or discharged. Existing clients start
--     as pending, to be checked before they're made active (owner decision).
--     Only people managers and the system admin change status; each change
--     is in the change log.
--   * Preferred name.
--   * Programs (NDIS, Support at Home, Private, Other to start): the system
--     admin adds, renames or deactivates them; nobody deletes them. "Needs
--     date of birth" marks the programs where date of birth is required
--     (used from step 3).
--   * Staff and team leaders see the basic record (name, preferred name,
--     reference, status) of clients linked to their own teams.
-- Nothing else changes: existing policies, the "shown/hidden" switch and
-- every module using clients keep working as before.

-- Programs -----------------------------------------------------------------
create table if not exists public.client_programs (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  name text not null check (length(trim(name)) between 1 and 80),
  needs_dob boolean not null default false,
  active boolean not null default true,
  sort_order integer not null default 0,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now()
);
create unique index if not exists client_programs_name on public.client_programs (org_id, lower(trim(name)));
alter table public.client_programs enable row level security;

drop policy if exists "members read programs" on public.client_programs;
create policy "members read programs" on public.client_programs
  for select to authenticated using ((select public.is_member()));
drop policy if exists "the system admin adds programs" on public.client_programs;
create policy "the system admin adds programs" on public.client_programs
  for insert to authenticated with check ((select public.is_system_admin()));
drop policy if exists "the system admin changes programs" on public.client_programs;
create policy "the system admin changes programs" on public.client_programs
  for update to authenticated using ((select public.is_system_admin())) with check ((select public.is_system_admin()));
-- No delete rule: programs are deactivated, never deleted.
grant select, insert, update on public.client_programs to authenticated;

insert into public.client_programs (name, needs_dob, sort_order)
select v.name, v.needs_dob, v.sort_order
  from (values ('NDIS', true, 10), ('Support at Home', true, 20), ('Private', false, 30), ('Other', false, 40)) v(name, needs_dob, sort_order)
 where not exists (select 1 from public.client_programs p where lower(p.name) = lower(v.name));

-- Client record ------------------------------------------------------------
alter table public.car_clients
  add column if not exists client_ref text,
  add column if not exists status text not null default 'pending',
  add column if not exists preferred_name text not null default '',
  add column if not exists status_changed_at timestamptz,
  add column if not exists status_changed_by uuid references public.profiles (id) on delete set null;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'car_clients_status_check') then
    alter table public.car_clients add constraint car_clients_status_check
      check (status in ('pending', 'active', 'suspended', 'discharged'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'car_clients_preferred_name_check') then
    alter table public.car_clients add constraint car_clients_preferred_name_check
      check (length(preferred_name) <= 80);
  end if;
end;
$$;

create sequence if not exists public.client_ref_seq;
grant usage on sequence public.client_ref_seq to authenticated;

create or replace function public.next_client_ref()
returns text
language sql
volatile
set search_path = ''
as $$
  select 'CL-' || case when n < 100000 then lpad(n::text, 5, '0') else n::text end
    from (select nextval('public.client_ref_seq') as n) s
$$;
revoke execute on function public.next_client_ref() from public, anon;
grant execute on function public.next_client_ref() to authenticated;

-- Existing clients, in alphabetical order (only those without a reference).
do $$
declare
  c record;
begin
  for c in select id from public.car_clients where client_ref is null order by lower(name), created_at, id loop
    update public.car_clients set client_ref = public.next_client_ref() where id = c.id;
  end loop;
end;
$$;

alter table public.car_clients alter column client_ref set not null;
create unique index if not exists car_clients_client_ref on public.car_clients (client_ref);

-- SECURITY DEFINER so it can write the change log (owner approval needed; a
-- trigger function can't be called directly, and nobody can execute it).
create or replace function public.guard_client_record()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.client_ref := public.next_client_ref(); -- always made here, never chosen
    if new.status <> 'pending' and auth.uid() is not null and not public.can_manage_people() then
      raise exception 'Only people managers can set a client''s status.';
    end if;
    return new;
  end if;
  if new.client_ref is distinct from old.client_ref then
    raise exception 'A client''s reference never changes.';
  end if;
  if new.status is distinct from old.status then
    if auth.uid() is not null and not public.can_manage_people() then
      raise exception 'Only people managers can change a client''s status.';
    end if;
    new.status_changed_at := now();
    new.status_changed_by := auth.uid();
    perform public.write_audit('client_status', 'client', new.id::text,
      jsonb_build_object('client', new.client_ref, 'from', old.status, 'to', new.status));
  end if;
  return new;
end;
$$;
revoke execute on function public.guard_client_record() from public, anon, authenticated;

drop trigger if exists guard_client_record on public.car_clients;
create trigger guard_client_record before insert or update on public.car_clients
  for each row execute function public.guard_client_record();

-- Staff and team leaders: the clients of their own teams (basic record).
drop policy if exists "staff see their teams' clients" on public.car_clients;
create policy "staff see their teams' clients" on public.car_clients
  for select to authenticated
  using ((select public.is_member()) and exists (
    select 1 from public.client_teams ct
     where ct.client_id = car_clients.id
       and (exists (select 1 from public.team_members tm where tm.team_id = ct.team_id and tm.user_id = (select auth.uid()))
            or exists (select 1 from public.team_leaders tl where tl.team_id = ct.team_id and tl.user_id = (select auth.uid())))));

$m102$;
  insert into public.install_log (name) values ('20270129000001_client_record.sql');
end;
$part$;

-- ====================================================================
-- 20270130000001_team_clients.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270130000001_team_clients.sql') then
    return;
  end if;
  execute $m103$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects (update 86): staff see only the basic record of their teams'
-- clients. Update 85's read rule gave team members and team leaders the
-- whole client row, including the free-text reference (where some
-- organisations keep an NDIS number). No screen showed it, but it could be
-- read from the database. Now:
--   * that read rule is removed (people managers, car managers and the system
--     admin are unchanged);
--   * team_clients() gives staff and team leaders, for clients linked to their
--     own teams only: id, reference (CL-), name, preferred name and status.
--     Never the free-text reference, the shown/hidden flag or who added it.
-- team_clients() is SECURITY DEFINER (owner approval needed), like
-- team_private() in update 84: fixed columns, own teams only.

drop policy if exists "staff see their teams' clients" on public.car_clients;

create or replace function public.team_clients()
returns table (id uuid, client_ref text, name text, preferred_name text, status text)
language sql
stable
security definer
set search_path = ''
as $$
  select c.id, c.client_ref, c.name, c.preferred_name, c.status
    from public.car_clients c
   where auth.uid() is not null
     and public.is_member()
     and exists (
       select 1 from public.client_teams ct
        where ct.client_id = c.id
          and (exists (select 1 from public.team_members tm where tm.team_id = ct.team_id and tm.user_id = auth.uid())
               or exists (select 1 from public.team_leaders tl where tl.team_id = ct.team_id and tl.user_id = auth.uid())))
   order by c.name
$$;

revoke execute on function public.team_clients() from public, anon;
grant execute on function public.team_clients() to authenticated;

$m103$;
  insert into public.install_log (name) values ('20270130000001_team_clients.sql');
end;
$part$;

-- ====================================================================
-- 20270131000001_client_locations.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270131000001_client_locations.sql') then
    return;
  end if;
  execute $m104$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects (update 87): Clients & Care step 2: service locations. A client
-- can have several places where support happens (home, day program, a
-- relative's house). Each has an address, access instructions for workers,
-- optional from and to dates, and must be approved by a people manager
-- before it counts (rostering will only use approved, current locations).
--
--   * People managers and the system admin add, change and approve them.
--   * Locations are never deleted: give an end date instead (history kept).
--   * Changing the address of an approved location makes it unapproved again
--     (a manager approves the new address).
--   * Every change is in the change log.
--   * Staff and team leaders see the approved, current locations of their own
--     teams' clients (address and access instructions), and nothing else.
-- Nothing existing changes.

create table if not exists public.client_locations (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  client_id uuid not null references public.car_clients (id) on delete restrict,
  label text not null default 'Home' check (length(trim(label)) between 1 and 60),
  address text not null check (length(trim(address)) between 3 and 200),
  suburb text not null default '' check (length(suburb) <= 60),
  state text not null default '' check (state in ('', 'NSW', 'VIC', 'QLD', 'WA', 'SA', 'TAS', 'ACT', 'NT')),
  postcode text not null default '' check (postcode = '' or postcode ~ '^[0-9]{4}$'),
  access_notes text not null default '' check (length(access_notes) <= 1000),
  from_date date,
  to_date date,
  approved boolean not null default false,
  approved_at timestamptz,
  approved_by uuid references public.profiles (id) on delete set null,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  constraint client_locations_dates check (to_date is null or from_date is null or to_date >= from_date)
);
create index if not exists client_locations_client on public.client_locations (client_id);
alter table public.client_locations enable row level security;

drop policy if exists "people managers see client locations" on public.client_locations;
create policy "people managers see client locations" on public.client_locations
  for select to authenticated using ((select public.can_manage_people()));
drop policy if exists "people managers add client locations" on public.client_locations;
create policy "people managers add client locations" on public.client_locations
  for insert to authenticated with check ((select public.can_manage_people()));
drop policy if exists "people managers change client locations" on public.client_locations;
create policy "people managers change client locations" on public.client_locations
  for update to authenticated using ((select public.can_manage_people())) with check ((select public.can_manage_people()));
-- No delete rule: end a location with a "to" date instead.

-- Staff and team leaders: approved, current locations of their teams' clients.
drop policy if exists "staff see their teams' approved client locations" on public.client_locations;
create policy "staff see their teams' approved client locations" on public.client_locations
  for select to authenticated
  using (approved
     and (from_date is null or from_date <= (select public.local_today()))
     and (to_date is null or to_date >= (select public.local_today()))
     and (select public.is_member())
     and exists (
       select 1 from public.client_teams ct
        where ct.client_id = client_locations.client_id
          and (exists (select 1 from public.team_members tm where tm.team_id = ct.team_id and tm.user_id = (select auth.uid()))
               or exists (select 1 from public.team_leaders tl where tl.team_id = ct.team_id and tl.user_id = (select auth.uid())))));

grant select, insert, update on public.client_locations to authenticated;

-- SECURITY DEFINER so it can write the change log (owner approval needed; a
-- trigger function can't be called directly, and nobody can execute it).
create or replace function public.guard_client_location()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ref text := (select client_ref from public.car_clients where id = new.client_id);
  v_moved boolean;
begin
  if tg_op = 'UPDATE' and new.client_id is distinct from old.client_id then
    raise exception 'A location stays with its client. Add a new one for another client.';
  end if;
  new.updated_at := now();
  new.updated_by := auth.uid();
  v_moved := tg_op = 'UPDATE' and (new.address, new.suburb, new.state, new.postcode)
                                is distinct from (old.address, old.suburb, old.state, old.postcode);
  if v_moved and old.approved then
    new.approved := false; -- a new address always needs approving again
  end if;
  if new.approved and tg_op = 'UPDATE' and old.approved then
    new.approved_at := old.approved_at; -- who approved it can't be rewritten
    new.approved_by := old.approved_by;
  elsif new.approved then
    new.approved_at := now();
    new.approved_by := auth.uid();
  else
    new.approved_at := null;
    new.approved_by := null;
  end if;
  perform public.write_audit(
    case when tg_op = 'INSERT' then 'client_location_added'
         when new.approved and not old.approved then 'client_location_approved'
         when v_moved and old.approved then 'client_location_needs_approval'
         else 'client_location_changed' end,
    'client', new.client_id::text,
    jsonb_build_object('client', v_ref, 'location', new.label, 'approved', new.approved,
                       'from', new.from_date, 'to', new.to_date));
  return new;
end;
$$;
revoke execute on function public.guard_client_location() from public, anon, authenticated;

drop trigger if exists guard_client_location on public.client_locations;
create trigger guard_client_location before insert or update on public.client_locations
  for each row execute function public.guard_client_location();

$m104$;
  insert into public.install_log (name) values ('20270131000001_client_locations.sql');
end;
$part$;

