-- ====================================================================
-- 20270205000001_odometer_uploads_follow_setting.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270205000001_odometer_uploads_follow_setting.sql') then
    return;
  end if;
  execute $m109$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects (QA-008 B, update 91; decisions D-009, D-042): drivers can upload
-- an odometer photo only while "Odometer photo when returning" isn't Off.
--   Off: refused by the database. Optional, Required: allowed (own folder).
-- Only the one storage policy changes. Reading existing photos and car
-- managers' uploads (cars/ folder) are unchanged. No files are touched.
do $storage$
begin
  if to_regclass('storage.objects') is null then
    return; -- databases without file storage (the test database)
  end if;
  drop policy if exists "drivers upload odometer photos" on storage.objects;
  create policy "drivers upload odometer photos" on storage.objects
    for insert to authenticated
    with check (bucket_id = 'car-files' and public.cars_on() and (storage.foldername(name))[1] = auth.uid()::text
                and public.car_setting('vehicles.odo_photo', 'optional') <> 'off');
end;
$storage$;

$m109$;
  insert into public.install_log (name) values ('20270205000001_odometer_uploads_follow_setting.sql');
end;
$part$;

-- ====================================================================
-- 20270206000001_function_groups.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270206000001_function_groups.sql') then
    return;
  end if;
  execute $m110$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects (update 92; function-based access, Stage 1; decisions D-045,
-- D-046): the Function Groups list. A business function (for example Care &
-- Coordination) that job titles will belong to in Stage 2. This stage only
-- adds the list: it links nothing and gives nobody any access.
--   * Members read the list. People who look after Roles (the "roles"
--     settings area, as for job titles) add, rename, describe or deactivate.
--   * Never deleted (no delete rule); the key can't change once made.
--   * Changes are written to the change log by the server action (no new
--     SECURITY DEFINER function).

create table if not exists public.function_groups (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  key text not null unique check (key ~ '^[a-z][a-z0-9_]{1,40}$'),
  name text not null check (length(trim(name)) between 1 and 80),
  description text not null default '' check (length(description) <= 500),
  active boolean not null default true,
  sort_order integer not null default 0,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now()
);
create unique index if not exists function_groups_name on public.function_groups (org_id, lower(trim(name)));
alter table public.function_groups enable row level security;

drop policy if exists "members read function groups" on public.function_groups;
create policy "members read function groups" on public.function_groups
  for select to authenticated using ((select public.is_member()));
drop policy if exists "roles admins add function groups" on public.function_groups;
create policy "roles admins add function groups" on public.function_groups
  for insert to authenticated with check ((select public.can_admin_area('roles')));
drop policy if exists "roles admins change function groups" on public.function_groups;
create policy "roles admins change function groups" on public.function_groups
  for update to authenticated using ((select public.can_admin_area('roles'))) with check ((select public.can_admin_area('roles')));
-- No delete rule: deactivate instead.
grant select, insert, update on public.function_groups to authenticated;

create or replace function public.guard_function_group()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' and new.key is distinct from old.key then
    raise exception 'A function group''s key never changes. Rename it instead.';
  end if;
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end;
$$;
revoke execute on function public.guard_function_group() from public, anon, authenticated;

drop trigger if exists guard_function_group on public.function_groups;
create trigger guard_function_group before insert or update on public.function_groups
  for each row execute function public.guard_function_group();

insert into public.function_groups (key, name, description, sort_order)
select v.key, v.name, v.description, v.sort_order
  from (values
    ('management_admin', 'Management & Administration', 'Running the organisation: centre and operations managers, administration.', 10),
    ('hr_workforce', 'HR & Workforce', 'Staff records, onboarding, rostering and payroll.', 20),
    ('care_coordination', 'Care & Coordination', 'Intake and assessment, care management and coordination.', 30),
    ('service_delivery', 'Service Delivery', 'Team leaders and support workers delivering services.', 40),
    ('finance_accounts', 'Finance & Accounts', 'Finance and accounts administration.', 50),
    ('allied_health', 'Allied Health', 'Allied health practitioners (each discipline is its own role).', 60)
  ) v(key, name, description, sort_order)
 where not exists (select 1 from public.function_groups g where g.key = v.key);

$m110$;
  insert into public.install_log (name) values ('20270206000001_function_groups.sql');
end;
$part$;

-- ====================================================================
-- 20270207000001_job_title_functions.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270207000001_job_title_functions.sql') then
    return;
  end if;
  execute $m111$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects (update 93; function-based access, Stage 2; D-045, D-046 and
-- the owner's approval of 17 Nov 2026): each job title belongs to one or more
-- function groups. This only records the link: it gives nobody any access and
-- changes no permission check.
--   * Members read the links; people who look after Roles add and remove them.
--   * Only active groups can be linked.
--   * A group can't be deactivated while an active role uses it.
--   * Existing roles are linked once by their access level (support worker and
--     team leader: Service Delivery; manager: Management & Administration; staff
--     admin: HR & Workforce; external: Allied Health). Changeable on the Roles page.
--   * "At least one group" for new and edited roles is checked by the Roles page.
--   * Changes are logged by the server action (no new SECURITY DEFINER).

create table if not exists public.job_title_functions (
  job_title_id uuid not null references public.job_titles (id) on delete restrict,
  function_group_id uuid not null references public.function_groups (id) on delete restrict,
  org_id uuid not null default public.default_org_id(),
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  primary key (job_title_id, function_group_id)
);
create index if not exists job_title_functions_group on public.job_title_functions (function_group_id);
alter table public.job_title_functions enable row level security;

drop policy if exists "members read role function groups" on public.job_title_functions;
create policy "members read role function groups" on public.job_title_functions
  for select to authenticated using ((select public.is_member()));
drop policy if exists "roles admins link role function groups" on public.job_title_functions;
create policy "roles admins link role function groups" on public.job_title_functions
  for insert to authenticated with check ((select public.can_admin_area('roles')));
drop policy if exists "roles admins unlink role function groups" on public.job_title_functions;
create policy "roles admins unlink role function groups" on public.job_title_functions
  for delete to authenticated using ((select public.can_admin_area('roles')));
grant select, insert, delete on public.job_title_functions to authenticated;

-- Only active groups can be linked.
create or replace function public.guard_job_title_function()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if not exists (select 1 from public.function_groups where id = new.function_group_id and active) then
    raise exception 'That function group isn''t in use. Choose another.';
  end if;
  return new;
end;
$$;
revoke execute on function public.guard_job_title_function() from public, anon, authenticated;
drop trigger if exists guard_job_title_function on public.job_title_functions;
create trigger guard_job_title_function before insert on public.job_title_functions
  for each row execute function public.guard_job_title_function();

-- Function groups: key never changes (Stage 1), and now: can't be deactivated
-- while an active role uses it.
create or replace function public.guard_function_group()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' and new.key is distinct from old.key then
    raise exception 'A function group''s key never changes. Rename it instead.';
  end if;
  if tg_op = 'UPDATE' and old.active and not new.active and exists (
       select 1 from public.job_title_functions l join public.job_titles t on t.id = l.job_title_id
        where l.function_group_id = new.id and t.active) then
    raise exception 'Roles in use belong to this group. Move them to another group first.';
  end if;
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end;
$$;

-- Link existing roles once, by access level (only roles with no group yet).
insert into public.job_title_functions (job_title_id, function_group_id)
select t.id, g.id
  from public.job_titles t
  join public.function_groups g on g.key = case t.access_level::text
         when 'support_worker' then 'service_delivery'
         when 'team_leader' then 'service_delivery'
         when 'manager' then 'management_admin'
         when 'staff_admin' then 'hr_workforce'
         when 'external' then 'allied_health'
       end
 where g.active
   and not exists (select 1 from public.job_title_functions l where l.job_title_id = t.id)
on conflict do nothing;

$m111$;
  insert into public.install_log (name) values ('20270207000001_job_title_functions.sql');
end;
$part$;

-- ====================================================================
-- 20270208000001_access_baselines.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270208000001_access_baselines.sql') then
    return;
  end if;
  execute $m112$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects (update 94; function-based access, Stage 3; decisions D-045,
-- D-046, D-047): grants held by a job title, a function group or an access
-- level, in the one permission check `can()`.
--
--   * Person grants (`access_grants`) are unchanged and still decide first.
--   * Then, in order: the person's job title, their function groups, their
--     access level (the default for everyone at that level). The first tier
--     with an applicable grant decides; within a tier the nearest module level
--     decides and a restriction beats an allow. A person's restriction is
--     never overridden.
--   * Ceiling: protected modules stay system admin only; new starters and
--     external accounts get nothing inherited; sensitive modules are never
--     given through a function group; settings areas and staff records keep
--     their own rules.
--   * Only modules marked `grant_ready` (switched over to `can()` alone,
--     Stage 3b onwards) can be given this way. None are yet, so nobody's
--     access changes in this update.
--   * The system admin sets any of these. A Manager Administrator sets job
--     title and function group grants only within their own authority: parts
--     they hold with "may pass on", never wider actions, never access-level
--     defaults; their grants stop counting if they stop being a Manager
--     Administrator. Revoked, never deleted.

alter table public.app_modules add column if not exists grant_ready boolean not null default false;

create table if not exists public.access_baselines (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  job_title_id uuid references public.job_titles (id) on delete restrict,
  function_group_id uuid references public.function_groups (id) on delete restrict,
  access_level public.app_role,
  module_id text not null references public.app_modules (id) on delete restrict,
  actions text[] not null default '{}',
  effect text not null default 'allow' check (effect in ('allow', 'restrict')),
  scope text not null default 'all' check (scope in ('all', 'own_teams')),
  note text not null default '' check (length(note) <= 300),
  granted_by uuid default auth.uid() references public.profiles (id),
  -- Given by the system admin (set on saving; system admins are hidden from staff).
  by_system_admin boolean not null default false,
  created_at timestamptz not null default now(),
  revoked_at timestamptz,
  revoked_by uuid references public.profiles (id),
  constraint access_baselines_one_holder check (num_nonnulls(job_title_id, function_group_id, access_level) = 1)
);
-- One live grant per holder and module.
create unique index if not exists access_baselines_live_title on public.access_baselines (job_title_id, module_id) where revoked_at is null and job_title_id is not null;
create unique index if not exists access_baselines_live_group on public.access_baselines (function_group_id, module_id) where revoked_at is null and function_group_id is not null;
create unique index if not exists access_baselines_live_level on public.access_baselines (access_level, module_id) where revoked_at is null and access_level is not null;
create index if not exists access_baselines_module on public.access_baselines (module_id) where revoked_at is null;
alter table public.access_baselines enable row level security;

drop policy if exists "the system admin, manager administrators and holders read baselines" on public.access_baselines;
create policy "the system admin, manager administrators and holders read baselines" on public.access_baselines
  for select to authenticated
  using ((select public.is_system_admin()) or (select public.is_manager_admin())
         or job_title_id = (select p.job_title_id from public.profiles p where p.id = (select auth.uid()))
         or function_group_id in (select jf.function_group_id from public.job_title_functions jf
                                    join public.profiles p on p.job_title_id = jf.job_title_id
                                   where p.id = (select auth.uid()))
         or access_level = (select p.role from public.profiles p where p.id = (select auth.uid())));
-- A Manager Administrator may give a job title or function group only what
-- they hold themselves with "may pass on" (same module, or a parent or
-- category that includes it), never wider actions.
create or replace function public.baseline_grant_allowed(p_module text, p_actions text[])
returns boolean
language sql
stable
security invoker
set search_path = ''
as $$
  with recursive up(id) as (
    select p_module
    union all
    select m.parent_id from public.app_modules m join up on m.id = up.id where m.parent_id is not null
  )
  select public.is_manager_admin() and public.mfa_ok() and exists (
    select 1
      from public.access_grants g, public.app_modules target
     where target.id = p_module
       and g.user_id = auth.uid() and g.area is null and g.parent_id is null
       and g.can_pass_on and g.effect = 'allow' and g.revoked_at is null
       and (g.expires_at is null or g.expires_at > now()) and (g.starts_at is null or g.starts_at <= now())
       and (g.module_id = p_module
            or (target.sensitivity = 'normal' and g.include_children
                and (g.module_id in (select id from up) or g.module_id = 'cat_' || target.category)))
       and (cardinality(g.actions) = 0 or (cardinality(p_actions) > 0 and p_actions <@ g.actions)))
$$;
revoke execute on function public.baseline_grant_allowed(text, text[]) from public, anon;
grant execute on function public.baseline_grant_allowed(text, text[]) to authenticated;

drop policy if exists "the system admin and manager administrators add baselines" on public.access_baselines;
create policy "the system admin and manager administrators add baselines" on public.access_baselines
  for insert to authenticated
  with check ((select public.is_system_admin())
              or (access_level is null and public.baseline_grant_allowed(module_id, actions)));
drop policy if exists "the system admin and the giver revoke baselines" on public.access_baselines;
create policy "the system admin and the giver revoke baselines" on public.access_baselines
  for update to authenticated
  using ((select public.is_system_admin()) or granted_by = (select auth.uid()))
  with check ((select public.is_system_admin()) or granted_by = (select auth.uid()));
-- No delete rule: revoked, never deleted.
grant select, insert, update on public.access_baselines to authenticated;

create or replace function public.guard_access_baseline()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  m record;
begin
  if tg_op = 'UPDATE' then
    if (to_jsonb(new) - 'revoked_at' - 'revoked_by') is distinct from (to_jsonb(old) - 'revoked_at' - 'revoked_by') or old.revoked_at is not null then
      raise exception 'A grant isn''t changed: revoke it and add a new one.';
    end if;
    new.revoked_by := auth.uid();
    return new;
  end if;
  select * into m from public.app_modules where id = new.module_id;
  if not found or m.status <> 'active' or m.sensitivity = 'protected' or m.legacy_kind is not null or not m.grant_ready then
    raise exception 'That part can''t be given to a role, group or access level (yet).';
  end if;
  if new.function_group_id is not null and m.sensitivity <> 'normal' then
    raise exception 'Sensitive parts are given to a job title or a person, never to a whole function group.';
  end if;
  if new.access_level in ('system_admin', 'new_starter', 'external') then
    raise exception 'That access level can''t hold grants.';
  end if;
  new.granted_by := auth.uid();
  new.by_system_admin := public.is_system_admin();
  new.created_at := now();
  return new;
end;
$$;
revoke execute on function public.guard_access_baseline() from public, anon, authenticated;
drop trigger if exists guard_access_baseline on public.access_baselines;
create trigger guard_access_baseline before insert or update on public.access_baselines
  for each row execute function public.guard_access_baseline();

-- The one permission check, with the inherited tiers after person grants.
create or replace function public.can(p_module text, p_action text default 'view', p_person uuid default null)
returns boolean
language plpgsql
stable
set search_path = ''
as $function$
declare
  m record;
  v_me record;
  v_effect text;
  v_groups uuid[];
begin
  select * into m from public.app_modules where id = p_module;
  if not found or m.status <> 'active' then
    return false;
  end if;
  if public.is_system_admin() and public.mfa_ok() then
    return true;
  end if;
  if m.sensitivity = 'protected' or not public.mfa_ok() then
    return false;
  end if;
  -- Today's rules, unchanged.
  if m.legacy_kind = 'settings' then
    return public.can_admin_area(m.legacy_area);
  end if;
  if m.legacy_kind = 'record' then
    if p_action = 'reveal_tfn' then
      return p_person is not null and public.has_tfn_access(p_person);
    end if;
    return case when p_person is null then public.holds_area(m.legacy_area) else public.has_access(m.legacy_area, p_person) end;
  end if;
  -- 1. Person grants (unchanged): the nearest level (this module, then its
  -- parents, then its category) decides.
  with recursive chain(id, depth) as (
    select m.id, 0
    union all
    select a.parent_id, c.depth + 1 from public.app_modules a join chain c on a.id = c.id where a.parent_id is not null
  ), levels as (
    select id, depth from chain
    union all
    select 'cat_' || m.category, 99
  )
  , applicable as (
    select g.effect, g.actions, l.depth
      from public.access_grants g
      join levels l on l.id = g.module_id
      join public.profiles me on me.id = g.user_id
      left join public.profiles gb on gb.id = g.granted_by
     where g.user_id = auth.uid() and g.area is null and g.revoked_at is null
       and (g.expires_at is null or g.expires_at > now())
       and (g.starts_at is null or g.starts_at <= now())
       and me.active and me.role in ('manager', 'staff_admin')
       and (case when g.parent_id is null then public.is_manager_admin(g.user_id) else (gb.active and gb.role = 'manager' and public.is_manager_admin(g.granted_by)) end)
       and (l.depth = 0 or (g.include_children and m.sensitivity = 'normal' and m.added_at <= g.created_at))
       and (p_person is null or g.scope = 'all'
            or (g.scope = 'people' and p_person = any (g.scope_ids))
            or (g.scope = 'teams' and exists (select 1 from public.team_members tm where tm.user_id = p_person and tm.team_id = any (g.scope_ids))))
  )
  select case
           when bool_or(a.effect = 'restrict' and (cardinality(a.actions) = 0 or p_action = any (a.actions))) then 'restrict'
           when bool_or(a.effect = 'allow' and (cardinality(a.actions) = 0 or p_action = any (a.actions))) then 'allow'
         end into v_effect
    from applicable a
   where a.depth = (select min(depth) from applicable);
  if v_effect is not null then
    return v_effect = 'allow';
  end if;

  -- 2 to 4. Inherited (cmeprojects Stage 3, D-047): job title, then function
  -- groups, then access level. Only for modules switched over to can().
  if not m.grant_ready then
    return false;
  end if;
  select p.role, p.active, p.job_title_id, coalesce(t.active, false) as title_active
    into v_me
    from public.profiles p left join public.job_titles t on t.id = p.job_title_id
   where p.id = auth.uid();
  if not found or not v_me.active or v_me.role in ('new_starter', 'external') then
    return false;
  end if;
  select coalesce(array_agg(jf.function_group_id), '{}') into v_groups
    from public.job_title_functions jf join public.function_groups fg on fg.id = jf.function_group_id
   where jf.job_title_id = v_me.job_title_id and fg.active and v_me.title_active;

  with recursive chain(id, depth) as (
    select m.id, 0
    union all
    select a.parent_id, c.depth + 1 from public.app_modules a join chain c on a.id = c.id where a.parent_id is not null
  ), levels as (
    select id, depth from chain
    union all
    select 'cat_' || m.category, 99
  ), applicable as (
    select case when b.job_title_id is not null then 1 when b.function_group_id is not null then 2 else 3 end as tier,
           l.depth, b.effect, b.actions
      from public.access_baselines b
      join levels l on l.id = b.module_id
     where b.revoked_at is null
       -- Given by the system admin, or by someone who is still an active Manager Administrator.
       and (b.by_system_admin or public.is_manager_admin(b.granted_by))
       and ((b.job_title_id is not null and b.job_title_id = v_me.job_title_id and v_me.title_active)
            or (b.function_group_id is not null and b.function_group_id = any (v_groups) and m.sensitivity = 'normal')
            or (b.access_level is not null and b.access_level = v_me.role))
       and (l.depth = 0 or (m.sensitivity = 'normal' and m.added_at <= b.created_at))
       and (p_person is null or b.scope = 'all'
            or (b.scope = 'own_teams' and exists (
                  select 1 from public.team_members t2
                   where t2.user_id = p_person
                     and t2.team_id in (select tm.team_id from public.team_members tm where tm.user_id = auth.uid()
                                        union select tl.team_id from public.team_leaders tl where tl.user_id = auth.uid()))))
  ), best as (
    select * from applicable where tier = (select min(tier) from applicable)
  )
  select case
           when bool_or(a.effect = 'restrict' and (cardinality(a.actions) = 0 or p_action = any (a.actions))) then 'restrict'
           when bool_or(a.effect = 'allow' and (cardinality(a.actions) = 0 or p_action = any (a.actions))) then 'allow'
         end into v_effect
    from best a
   where a.depth = (select min(depth) from best);
  return coalesce(v_effect = 'allow', false);
end;
$function$;

$m112$;
  insert into public.install_log (name) values ('20270208000001_access_baselines.sql');
end;
$part$;

-- ====================================================================
-- 20270209000001_onboarding_switch_over.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270209000001_onboarding_switch_over.sql') then
    return;
  end if;
  execute $m113$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 95; function-based access, Stage 3b; decisions D-047,
-- D-049): Onboarding is the first part switched over to the one permission
-- check `can()`.
--
--   * Who manages onboarding (approve uploads, set up items, the document
--     library) and who sees onboarding progress and the expiry list now come
--     only from `can('hr.onboarding', ...)`: person grants, then job title,
--     function groups, access level.
--   * Today's rules are copied once into access-level defaults, so nobody's
--     access changes on the day (D-049, option A):
--       - each role ticked in System settings "Who manages Compliance" gets
--         full onboarding access;
--       - managers too, if there's no active staff admin when this runs (the
--         old built-in fallback, settled once; a fresh install starts with
--         staff admins only);
--       - managers see progress for everyone, team leaders for their own
--         teams (as today).
--     After this, it's changed on the Access page; the old setting is kept but
--     no longer used.
--   * Grants added by a database update (no signed-in person) count as the
--     system admin's.

-- An insert with no signed-in person (a database update run by the owner)
-- counts as the system admin's. Signed-in people always have an id.
create or replace function public.guard_access_baseline()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  m record;
begin
  if tg_op = 'UPDATE' then
    if (to_jsonb(new) - 'revoked_at' - 'revoked_by') is distinct from (to_jsonb(old) - 'revoked_at' - 'revoked_by') or old.revoked_at is not null then
      raise exception 'A grant isn''t changed: revoke it and add a new one.';
    end if;
    new.revoked_by := auth.uid();
    return new;
  end if;
  select * into m from public.app_modules where id = new.module_id;
  if not found or m.status <> 'active' or m.sensitivity = 'protected' or m.legacy_kind is not null or not m.grant_ready then
    raise exception 'That part can''t be given to a role, group or access level (yet).';
  end if;
  if new.function_group_id is not null and m.sensitivity <> 'normal' then
    raise exception 'Sensitive parts are given to a job title or a person, never to a whole function group.';
  end if;
  if new.access_level in ('system_admin', 'new_starter', 'external') then
    raise exception 'That access level can''t hold grants.';
  end if;
  new.granted_by := auth.uid();
  new.by_system_admin := public.is_system_admin() or auth.uid() is null;
  new.created_at := now();
  return new;
end;
$$;

-- Switch Onboarding over.
update public.app_modules set grant_ready = true
 where id in ('hr.onboarding', 'hr.onboarding.overview', 'hr.onboarding.expiry') and not grant_ready;

-- Copy today's rules into access-level defaults, once (skipped while any live
-- access-level default for Onboarding exists, so running again changes nothing).
do $$
declare
  v_full public.app_role[];
begin
  if exists (select 1 from public.access_baselines
              where module_id like 'hr.onboarding%' and access_level is not null and revoked_at is null) then
    return;
  end if;
  v_full := public.setting_roles('compliance.manager_roles');
  -- The old fallback (managers while there's no staff admin), settled once.
  -- A fresh install (nobody signed up yet) starts with staff admins only.
  if exists (select 1 from public.profiles where role <> 'system_admin')
     and not exists (select 1 from public.profiles where role = 'staff_admin' and active) then
    v_full := v_full || 'manager'::public.app_role;
  end if;
  insert into public.access_baselines (access_level, module_id, actions, scope, note)
  select distinct r, 'hr.onboarding', '{}'::text[], 'all', 'Set at switch-over from "Who manages Compliance"'
    from unnest(v_full) r
   where r not in ('system_admin', 'new_starter', 'external');
  if not ('manager' = any (v_full)) then
    insert into public.access_baselines (access_level, module_id, actions, scope, note)
    values ('manager', 'hr.onboarding', '{view}', 'all', 'Set at switch-over: managers see onboarding progress');
  end if;
  if not ('team_leader' = any (v_full)) then
    insert into public.access_baselines (access_level, module_id, actions, scope, note)
    values ('team_leader', 'hr.onboarding', '{view}', 'own_teams', 'Set at switch-over: team leaders see their teams'' progress');
  end if;
end $$;

