--     teams. Nobody's access changes.
--   * Unchanged: staff admins send changes to who's in a team to a manager for
--     approval while "Staff admins' team changes need approval" is on (a
--     workflow rule in People rules), and staff admins don't write team
--     members directly; everyone reads teams; the core team is automatic.

update public.app_modules set grant_ready = true where id = 'people.teams' and not grant_ready;

do $$
begin
  if exists (select 1 from public.access_baselines
              where module_id = 'people.teams' and access_level is not null and revoked_at is null) then
    return;
  end if;
  insert into public.access_baselines (access_level, module_id, actions, scope, note) values
    ('manager', 'people.teams', '{}', 'all', 'Set at switch-over: managers managed teams'),
    ('staff_admin', 'people.teams', '{}', 'all', 'Set at switch-over: staff admins managed teams');
end $$;

drop policy if exists "managers and admins manage teams" on public.teams;
create policy "managers and admins manage teams" on public.teams for ALL to authenticated using (( SELECT public.can('people.teams'::text, 'edit'::text) AS can)) with check (( SELECT public.can('people.teams'::text, 'edit'::text) AS can));
drop policy if exists "managers set team leaders" on public.team_leaders;
create policy "managers set team leaders" on public.team_leaders for ALL to authenticated using ((( SELECT public.can('people.teams'::text, 'edit'::text) AS can) AND NOT ( SELECT public.has_role(ARRAY['staff_admin'::public.app_role]) AS has_role))) with check ((( SELECT public.can('people.teams'::text, 'edit'::text) AS can) AND NOT ( SELECT public.has_role(ARRAY['staff_admin'::public.app_role]) AS has_role)));
drop policy if exists "managers change team members" on public.team_members;
create policy "managers change team members" on public.team_members for ALL to authenticated using ((( SELECT public.can('people.teams'::text, 'edit'::text) AS can) AND NOT ( SELECT public.has_role(ARRAY['staff_admin'::public.app_role]) AS has_role))) with check ((( SELECT public.can('people.teams'::text, 'edit'::text) AS can) AND NOT ( SELECT public.has_role(ARRAY['staff_admin'::public.app_role]) AS has_role)));

CREATE OR REPLACE FUNCTION public.set_team(p_team_id uuid, p_members uuid[], p_leader uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_members uuid[] := coalesce(p_members, '{}');
  v_old jsonb;
begin
  -- cmeprojects (update 100): who may change teams is the Access page (Teams,
  -- edit); staff admins still send it for approval while that rule is on.
  if not (public.can('people.teams', 'edit')
          and not (public.has_role(array['staff_admin']::public.app_role[])
                   and public.rule_on('people.staff_admin_team_approval'))) then
    raise exception 'Only managers change who is in a team. Send it as a request.';
  end if;
  if (select is_core from public.teams where id = p_team_id) then
    raise exception 'The core team is managers and staff admins, automatically';
  end if;
  if p_leader is not null and not (p_leader = any (v_members)) then
    v_members := v_members || p_leader;
  end if;
  select jsonb_build_object(
           'members', coalesce((select jsonb_agg(user_id order by user_id) from public.team_members where team_id = p_team_id), '[]'),
           'leader', (select to_jsonb(user_id) from public.team_leaders where team_id = p_team_id limit 1))
    into v_old;

  delete from public.team_leaders where team_id = p_team_id and user_id is distinct from p_leader;
  delete from public.team_members where team_id = p_team_id and not (user_id = any (v_members));
  insert into public.team_members (team_id, user_id)
  select p_team_id, m from unnest(v_members) m on conflict do nothing;
  if p_leader is not null then
    insert into public.team_leaders (team_id, user_id) values (p_team_id, p_leader) on conflict do nothing;
  end if;

  perform public.write_audit('team_changed', 'team', p_team_id::text,
    jsonb_build_object('from', v_old, 'to', jsonb_build_object('members', to_jsonb(v_members), 'leader', p_leader)));
end;
$function$;

$m118$;
  insert into public.install_log (name) values ('20270214000001_teams_switch_over.sql');
end;
$part$;

-- ====================================================================
-- 20270215000001_staff_switch_over.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270215000001_staff_switch_over.sql') then
    return;
  end if;
  execute $m119$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 101; function-based access, Stage 3b; D-047, D-049):
-- Staff switched over to the one permission check `can()`.
--
--   * Who sees and manages staff (Staff page, invitations, private details,
--     changing people's details and roles within their own limits, giving
--     conditional roles, removing photos, role and team change requests) now
--     comes from `can('people.staff', 'view' / 'edit')` instead of the
--     built-in "managers, staff admins and the system admin" rule.
--   * Defaults reproduce today's rule: managers and staff admins, all actions.
--     Nobody's access changes.
--   * Onboarding progress (`compliance_status`, `work_status`): "managers see
--     everyone's" now follows Onboarding (view) for that person, finishing
--     update 95; team leaders still see their team's.
--   * Unchanged: which roles someone may give (`can_manage_role`), the People
--     rules that send staff admins' changes for approval, who may invite
--     ("Who can invite"), staff records (Access page, own rules), Clients and
--     car clients (still the built-in rule, they switch with Stage 5).

update public.app_modules set grant_ready = true where id = 'people.staff' and not grant_ready;

do $$
begin
  if exists (select 1 from public.access_baselines
              where module_id = 'people.staff' and access_level is not null and revoked_at is null) then
    return;
  end if;
  insert into public.access_baselines (access_level, module_id, actions, scope, note) values
    ('manager', 'people.staff', '{}', 'all', 'Set at switch-over: managers managed staff'),
    ('staff_admin', 'people.staff', '{}', 'all', 'Set at switch-over: staff admins managed staff');
end $$;

drop policy if exists "the person and people managers see private details" on public.staff_private;
create policy "the person and people managers see private details" on public.staff_private as PERMISSIVE for SELECT to authenticated using ((( SELECT feature_enabled('hr_profiles'::text) AS feature_enabled) AND ((user_id = ( SELECT auth.uid() AS uid)) OR ( SELECT public.can('people.staff'::text, 'view'::text) AS can) OR ( SELECT is_system_admin() AS is_system_admin))));
drop policy if exists "managers and admins create invitations" on public.invitations;
create policy "managers and admins create invitations" on public.invitations as PERMISSIVE for INSERT to authenticated with check (( SELECT public.can('people.staff'::text, 'edit'::text) AS can));
drop policy if exists "managers and admins read invitations" on public.invitations;
create policy "managers and admins read invitations" on public.invitations as PERMISSIVE for SELECT to authenticated using (( SELECT public.can('people.staff'::text, 'view'::text) AS can));
drop policy if exists "managers and admins remove pending invitations" on public.invitations;
create policy "managers and admins remove pending invitations" on public.invitations as PERMISSIVE for DELETE to authenticated using ((( SELECT public.can('people.staff'::text, 'edit'::text) AS can) AND (accepted_at IS NULL)));
drop policy if exists "managers and admins update invitations" on public.invitations;
create policy "managers and admins update invitations" on public.invitations as PERMISSIVE for UPDATE to authenticated using (( SELECT public.can('people.staff'::text, 'edit'::text) AS can)) with check (( SELECT public.can('people.staff'::text, 'edit'::text) AS can));
drop policy if exists "managers and admins see change requests" on public.people_change_requests;
create policy "managers and admins see change requests" on public.people_change_requests as PERMISSIVE for SELECT to authenticated using (( SELECT public.can('people.staff'::text, 'view'::text) AS can));
drop policy if exists "managers and admins update people" on public.profiles;
create policy "managers and admins update people" on public.profiles as PERMISSIVE for UPDATE to authenticated using (( SELECT public.can('people.staff'::text, 'edit'::text) AS can)) with check (( SELECT public.can('people.staff'::text, 'edit'::text) AS can));
drop policy if exists "the person and people who manage staff see overrides" on public.work_overrides;
create policy "the person and people who manage staff see overrides" on public.work_overrides as PERMISSIVE for SELECT to authenticated using (((user_id = ( SELECT auth.uid() AS uid)) OR ( SELECT can_manage_compliance() AS can_manage_compliance) OR ( SELECT public.can('people.staff'::text, 'view'::text) AS can) OR has_role(ARRAY['manager'::app_role]) OR leads_user(user_id)));

CREATE OR REPLACE FUNCTION public.log_admin_action(p_action text, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_action in ('mfa_reset', 'password_reset_sent', 'pin_cleared') then
    if not public.can_help_sign_in(p_user_id) then
      raise exception 'You can''t do this for them. Ask the system admin.';
    end if;
  elsif p_action <> 'invite_resent' or not public.can('people.staff', 'edit') then
    raise exception 'Not allowed';
  end if;
  perform public.write_audit(p_action, 'profile', p_user_id::text, '{}'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION public.give_conditional_role(p_user_id uuid, p_role app_role, p_title_id uuid, p_teams uuid[], p_reason text, p_deadline date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me public.profiles;
  v_role public.app_role := p_role;
  v_teams uuid[] := coalesce(p_teams, '{}');
  v_missing text[];
  v_id uuid;
  v_name text;
  v_manager uuid;
  v_to jsonb;
begin
  select * into me from public.profiles where id = auth.uid();
  if not public.can('people.staff', 'edit') then
    raise exception 'Only managers and staff admins give roles';
  end if;
  if p_user_id = auth.uid() then
    raise exception 'You cannot change your own role';
  end if;
  if (select role from public.profiles where id = p_user_id and active) is distinct from 'new_starter' then
    raise exception 'Conditional roles are for new starters';
  end if;
  if p_title_id is not null then
    select access_level into v_role from public.job_titles where id = p_title_id and active;
    if v_role is null then raise exception 'Choose a role that is in use'; end if;
  end if;
  if v_role in ('new_starter', 'system_admin') or not public.can_manage_role(v_role) then
    raise exception 'Choose a role you''re allowed to give';
  end if;
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'Give a reason for the conditional role';
  end if;
  if p_deadline is null or p_deadline < public.local_today() or p_deadline > public.local_today() + 180 then
    raise exception 'Choose a deadline in the next six months';
  end if;
  if v_role not in ('support_worker', 'team_leader') then
    v_teams := '{}';
  elsif v_role = 'team_leader' and cardinality(v_teams) > 1 then
    raise exception 'A team leader can be in one team only';
  end if;
  if exists (select 1 from unnest(v_teams) t where not exists (select 1 from public.teams where id = t and active and not is_core)) then
    raise exception 'Choose teams that are in use';
  end if;

  -- What's missing for the chosen role. Items only for new starters (or other
  -- roles) don't count, so this can be nothing even when the Staff page shows
  -- items still to do.
  v_missing := public.onboarding_missing(p_user_id, v_role, v_teams);

  v_to := jsonb_build_object('role', v_role, 'title', p_title_id, 'teams', to_jsonb(v_teams),
                             'deadline', p_deadline, 'missing', to_jsonb(v_missing));

  -- Managers give it straight away; a staff admin's always goes to a manager.
  if me.role in ('manager', 'system_admin') then
    insert into public.people_change_requests (kind, user_id, from_value, to_value, reason, requested_by,
                                               status, decided_by, decided_at, requester_seen_at)
    values ('conditional', p_user_id, jsonb_build_object('role', 'new_starter'), v_to, trim(p_reason), auth.uid(),
            'approved', auth.uid(), now(), now())
    returning id into v_id;
    perform public.apply_conditional_role(v_id);
    perform public.write_audit('conditional_role_given', 'profile', p_user_id::text, v_to);
    return v_id;
  end if;

  v_id := public.add_change_request('conditional', p_user_id, null, jsonb_build_object('role', 'new_starter'), v_to, p_reason);
  select coalesce(nullif(full_name, ''), email) into v_name from public.profiles where id = p_user_id;
  for v_manager in select id from public.profiles where active and role = 'manager' loop
    perform public.notify(v_manager, 'approval_needed',
      format('Conditional role for %s needs your approval', v_name),
      format('%s asks to give them a role before onboarding is finished (deadline %s).',
             coalesce(nullif(me.full_name, ''), me.email), to_char(p_deadline, 'FMDD Mon YYYY')),
      '/settings/staff', true);
  end loop;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_invitation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is not null and not public.can_invite() then
    raise exception 'You''re not set up to send invites. Ask a staff admin.';
  end if;
  -- People who can invite but don't manage staff send general invites only.
  if auth.uid() is not null and not public.can('people.staff', 'edit') and (new.role <> 'new_starter' or new.team_id is not null) then
    raise exception 'Invite them as a new starter; a staff admin sets their role later';
  end if;
  if auth.uid() is not null and public.can('people.staff', 'edit') and not public.can_manage_role(new.role) then
    raise exception 'Only a system admin can invite a system admin';
  end if;
  if auth.uid() is not null and public.rule_on('people.general_invites_only')
     and new.role <> 'new_starter' and public.my_role() <> 'system_admin' then
    raise exception 'Invites are general: they join as a new starter and you set their role afterwards';
  end if;
  if auth.uid() is not null and new.team_id is not null and public.my_role() = 'staff_admin'
     and public.rule_on('people.staff_admin_team_approval') then
    raise exception 'Add them to a team once they''ve joined; a manager approves team changes';
  end if;
  new.email := lower(trim(new.email));
  if tg_op = 'INSERT' then
    new.invited_by := coalesce(new.invited_by, auth.uid());
    perform public.write_audit('invited', 'invitation', new.email,
      jsonb_build_object('role', new.role));
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.remove_avatar(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_user is distinct from auth.uid() and not (public.can('people.staff', 'edit') or public.is_system_admin()) then
    raise exception 'Only you, or people who manage staff, can remove this photo.';
  end if;
  perform set_config('portal.avatar_ok', 'on', true);
  update public.profiles set avatar_ref = null where id = p_user;
  perform public.write_audit('photo_removed', 'profile', p_user::text, '{}'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_profile_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := auth.uid();
begin
  if new.id <> old.id or new.email <> old.email or new.org_id <> old.org_id then
    raise exception 'This field cannot be changed here';
  end if;

  -- Names (cmeprojects Phase 2): your own only while it's still blank (account
  -- set-up); someone else's with a Staff details grant covering them, or as the
  -- system admin. System jobs (no signed-in person) aren't affected.
  if actor is not null and new.full_name is distinct from old.full_name then
    if new.id = actor and coalesce(trim(old.full_name), '') <> '' and not public.is_system_admin() then
      raise exception 'Your name is set by the office. Ask your manager or the system admin to change it.';
    end if;
    if new.id <> actor and not public.has_access('staff_details', new.id) then
      raise exception 'You don''t have access to change this person''s name. The system admin can give you access.';
    end if;
    if new.id <> actor and old.role = 'system_admin' and not public.is_system_admin() then
      raise exception 'Only a system admin can rename a system admin';
    end if;
    perform public.write_audit('name_changed', 'profile', new.id::text,
      jsonb_build_object('from', old.full_name, 'to', new.full_name));
  end if;

  if actor is not null then
    if new.role is distinct from old.role
       or new.team_id is distinct from old.team_id
       or new.active is distinct from old.active then

      if not public.can('people.staff', 'edit') then
        raise exception 'Only managers and admins can change roles, teams or access';
      end if;

      if new.id = actor and (new.role is distinct from old.role or not new.active) then
        raise exception 'You cannot change your own role or deactivate yourself';
      end if;

      if new.id <> actor and (not public.can_manage_role(old.role) or not public.can_manage_role(new.role)) then
        raise exception 'Only a system admin can manage system admins';
      end if;

      -- cmeprojects (update 79): a new starter gets another role only once
      -- cleared to work (with onboarding on); otherwise a conditional role.
      if old.role = 'new_starter' and new.role <> 'new_starter'
         and coalesce(current_setting('app.conditional_role', true), '') <> 'on'
         and public.feature_enabled('compliance') and old.cleared_at is null then
        raise exception 'They aren''t cleared to work yet. Clear them to work first (Onboarding), or give a conditional role with a deadline.';
      end if;
      if old.role = 'new_starter' and new.role <> 'new_starter'
         and coalesce(current_setting('app.conditional_role', true), '') <> 'on'
         and cardinality(public.onboarding_missing(new.id, new.role, null)) > 0 then
        raise exception 'They haven''t finished onboarding yet. Give a conditional role with a deadline instead.';
      end if;

      if new.role is distinct from old.role and public.my_role() = 'staff_admin'
         and public.rule_on('people.staff_admin_role_approval')
         and (old.role <> 'new_starter' or public.rule_on('people.first_role_approval')) then
        raise exception 'Role changes by a staff admin need a manager''s approval. Send it as a request.';
      end if;
      if new.team_id is distinct from old.team_id and public.my_role() = 'staff_admin'
         and public.rule_on('people.staff_admin_team_approval') then
        raise exception 'Team changes by a staff admin need a manager''s approval. Send it as a request.';
      end if;
    end if;
  end if;

  if actor is not null and not public.is_system_admin()
     and old.role = 'manager' and old.active
     and (new.role <> 'manager' or not new.active)
     and not exists (select 1 from public.profiles where role = 'manager' and active and id <> old.id) then
    raise exception 'They''re the only manager left, so they can''t be deactivated or given another role. Add another manager first.';
  end if;

  if old.role = 'system_admin' and old.active
     and (new.role <> 'system_admin' or not new.active)
     and not exists (
       select 1 from public.profiles
        where role = 'system_admin' and active and id <> old.id
     ) then
    raise exception 'There must always be at least one active system admin';
  end if;

  if new.active and not old.active then
    new.deactivated_at := null;
  elsif not new.active and old.active then
    new.deactivated_at := now();
  end if;

  if new.role is distinct from old.role then
    perform public.write_audit('role_changed', 'profile', new.id::text,
      jsonb_build_object('from', old.role, 'to', new.role));
  end if;
  if new.active is distinct from old.active then
    perform public.write_audit(
      case when new.active then 'reactivated' else 'deactivated' end,
      'profile', new.id::text, '{}'::jsonb);
  end if;
  if new.team_id is distinct from old.team_id then
    perform public.write_audit('team_changed', 'profile', new.id::text,
      jsonb_build_object('from', old.team_id, 'to', new.team_id));
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.compliance_status(p_user uuid, p_role app_role DEFAULT NULL::app_role, p_teams uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(item_id uuid, kind text, title text, state text, record_id bigint, expires_on date, note text, sort_order integer, before_work boolean, category text, needs_check boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not (p_user = auth.uid() or public.can_manage_compliance() or public.can('people.staff', 'view')
          or public.can('hr.onboarding', 'view', p_user) or public.leads_user(p_user)
          or auth.uid() is null) then
    return;
  end if;
  return query select * from public.compliance_status_all(p_user, p_role, p_teams);
end;
$function$;

CREATE OR REPLACE FUNCTION public.work_status(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.profiles;
  o public.work_overrides;
begin
  if not (p_user = auth.uid() or public.can_manage_compliance() or public.can('people.staff', 'view')
          or public.can('hr.onboarding', 'view', p_user) or public.leads_user(p_user)) then
    return null;
  end if;
  select * into p from public.profiles where id = p_user;
  o := public.active_override(p_user);
  return jsonb_build_object(
    'onboarding_complete', p.onboarded_at is not null and cardinality(public.onboarding_missing(p_user)) = 0,
    'onboarded_at', p.onboarded_at,
    'compliance_verified', public.compliance_is_verified(p_user),
    'cleared', p.cleared_at is not null,
    'cleared_at', p.cleared_at,
    'cleared_by', (select coalesce(nullif(full_name, ''), email) from public.profiles where id = p.cleared_by),
    -- cmeprojects (update 81): minimum to work (before clearing, checked right
    -- to work too), what's still to finish, and the 7-day date for it.
    'before_work_missing', to_jsonb(case when p.cleared_at is null
                                         then public.before_work_missing(p_user) || public.right_to_work_missing(p_user)
                                         else public.before_work_missing(p_user) end),
    'still_to_finish', to_jsonb(public.onboarding_missing(p_user)),
    'finish_by', case when p.cleared_at is not null and cardinality(public.onboarding_missing(p_user)) > 0
                      then ((p.cleared_at at time zone 'Australia/Sydney')::date + 7) end,
    'cleared_note', (select a.details ->> 'note' from public.audit_log a
                      where a.action = 'cleared_to_work' and a.entity_id = p_user::text order by a.id desc limit 1),
    'can_work', public.can_work(p_user),
    'override', case when o.id is null then null else jsonb_build_object('id', o.id, 'reason', o.reason, 'until', o.until_date,
                  'by', (select coalesce(nullif(full_name, ''), email) from public.profiles where id = o.granted_by)) end);
end;
$function$;

$m119$;
  insert into public.install_log (name) values ('20270215000001_staff_switch_over.sql');
end;
$part$;

-- ====================================================================
-- 20270216000001_sla_request_rules_switch_over.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270216000001_sla_request_rules_switch_over.sql') then
    return;
  end if;
  execute $m120$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 102; function-based access, Stage 3b; D-047, D-049):
-- Due dates (SLA settings) and Request approvals follow the one permission
-- check `can()`.
--
--   * Request approvals: already decided by the HR settings area everywhere
--     (page and database). It's now catalogued as part of that settings area,
--     so `can('workflows.request_rules', ...)` gives the same answer and it's
--     given with the HR settings area on the Access page. No access changes.
--   * Due dates (SLA): "managers always" becomes a grant,
--     `can('workflows.sla', 'configure')`, with a default for managers (today's
--     rule). Whoever looks after the Tasks settings area still can, as before.
--     Nobody's access changes.

update public.app_modules set legacy_kind = 'settings', legacy_area = 'hr'
 where id = 'workflows.request_rules' and legacy_kind is null;

update public.app_modules set grant_ready = true where id = 'workflows.sla' and not grant_ready;

do $$
begin
  if exists (select 1 from public.access_baselines
              where module_id = 'workflows.sla' and access_level is not null and revoked_at is null) then
    return;
  end if;
  insert into public.access_baselines (access_level, module_id, actions, scope, note)
  values ('manager', 'workflows.sla', '{}', 'all', 'Set at switch-over: managers set the due dates');
end $$;

drop policy if exists "managers change the SLA" on public.app_settings;
create policy "managers change the SLA" on public.app_settings
  for update to authenticated
  using (key like 'tasks.sla%' and (select public.can('workflows.sla', 'configure')))
  with check (key like 'tasks.sla%' and (select public.can('workflows.sla', 'configure')));

$m120$;
  insert into public.install_log (name) values ('20270216000001_sla_request_rules_switch_over.sql');
end;
$part$;

-- ====================================================================
-- 20270217000001_tasks_switch_over.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270217000001_tasks_switch_over.sql') then
    return;
  end if;
  execute $m121$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 103; function-based access, Stage 3b; D-047, D-049;
-- owner chose option A): Tasks switched over to the one permission check
-- `can()`, together with a faster task check.
--
--   * "Sees every task" (managers and the system admin today) now comes from
--     `can('ops.tasks', 'view')`, default managers. Nobody's access changes.
--   * Unchanged: everyone sees tasks they're given, made, or help on; team
--     leaders see their team's tasks; who may change a task (assignee, maker,
--     team leader, the register's managers).
--   * Faster: the task list no longer runs a check for every task. The
--     permission check runs once per query, and "mine / I help / my team's"
--     is worked out in one go. Timeline and files follow the task (whoever
--     can see the task sees them).

update public.app_modules set grant_ready = true where id = 'ops.tasks' and not grant_ready;

do $$
begin
  if exists (select 1 from public.access_baselines
              where module_id = 'ops.tasks' and access_level is not null and revoked_at is null) then
    return;
  end if;
  insert into public.access_baselines (access_level, module_id, actions, scope, note)
  values ('manager', 'ops.tasks', '{view}', 'all', 'Set at switch-over: managers saw every task');
end $$;

-- One task (used by the task functions).
CREATE OR REPLACE FUNCTION public.can_see_task(p_task_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select public.is_member() and (
    public.can('ops.tasks', 'view') or public.is_system_admin()
    or exists (
      select 1
        from public.tasks t
       where t.id = p_task_id
         and (
           t.assigned_to = auth.uid()
           or t.created_by = auth.uid()
           or exists (select 1 from public.task_helpers h where h.task_id = t.id and h.user_id = auth.uid())
           or public.leads_user(t.assigned_to)
           or public.leads_user(t.created_by)
         )
    )
  )
$function$;

drop policy if exists "see tasks you have access to" on public.tasks;
create policy "see tasks you have access to" on public.tasks
  for select to authenticated
  using ((select public.is_member()) and (
    (select public.can('ops.tasks', 'view')) or (select public.is_system_admin())
    or assigned_to = (select auth.uid()) or created_by = (select auth.uid())
    or id in (select h.task_id from public.task_helpers h where h.user_id = (select auth.uid()))
    or ((select public.feature_live('teams') and public.has_role(array['team_leader', 'manager', 'system_admin']::public.app_role[]))
        and (assigned_to in (select m.user_id from public.team_leaders tl join public.team_members m on m.team_id = tl.team_id where tl.user_id = (select auth.uid())) or created_by in (select m.user_id from public.team_leaders tl join public.team_members m on m.team_id = tl.team_id where tl.user_id = (select auth.uid()))))));

drop policy if exists "see helpers on tasks you have access to" on public.task_helpers;
create policy "see helpers on tasks you have access to" on public.task_helpers
  for select to authenticated
  using (user_id = (select auth.uid()) or (select public.can('ops.tasks', 'view')) or public.can_see_task(task_id));

drop policy if exists "see the timeline of tasks you have access to" on public.task_events;
create policy "see the timeline of tasks you have access to" on public.task_events
  for select to authenticated
  using (exists (select 1 from public.tasks t where t.id = task_events.task_id));

drop policy if exists "people who see the task see its files" on public.task_attachments;
create policy "people who see the task see its files" on public.task_attachments
  for select to authenticated
  using (exists (select 1 from public.tasks t where t.id = task_attachments.task_id));

$m121$;
  insert into public.install_log (name) values ('20270217000001_tasks_switch_over.sql');
end;
$part$;

-- ====================================================================
-- 20270218000001_function_group_modules.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270218000001_function_group_modules.sql') then
    return;
  end if;
  execute $m122$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 104; function-based access, Stage 4; D-045, D-047):
-- which parts of the portal belong to each function group.
--
--   * A mapping only decides which parts a function group's screens offer
--     first (Access page, Roles page). It gives nobody access: access is
--     always an explicit grant (person, role, group or access level).
--   * A part can belong to more than one group (for example Tasks belongs to
--     Management, Care & Coordination and Service Delivery).
--   * Everyone's own pages (My workspace) belong to no group. Protected parts
--     (System settings, Access) stay with the system admin.
--   * Starting mapping below; the system admin (or whoever looks after
--     Roles) changes it on the Roles page.

create table if not exists public.function_group_modules (
  function_group_id uuid not null references public.function_groups (id) on delete restrict,
  module_id text not null references public.app_modules (id) on delete restrict,
  org_id uuid not null default public.default_org_id(),
  created_by uuid default auth.uid() references public.profiles (id),
  created_at timestamptz not null default now(),
  primary key (function_group_id, module_id)
);
create index if not exists function_group_modules_module on public.function_group_modules (module_id);
alter table public.function_group_modules enable row level security;

drop policy if exists "members read function group parts" on public.function_group_modules;
create policy "members read function group parts" on public.function_group_modules
  for select to authenticated using ((select public.is_member()));
drop policy if exists "roles admins map function group parts" on public.function_group_modules;
create policy "roles admins map function group parts" on public.function_group_modules
  for insert to authenticated with check ((select public.can_admin_area('roles')));
drop policy if exists "roles admins unmap function group parts" on public.function_group_modules;
create policy "roles admins unmap function group parts" on public.function_group_modules
  for delete to authenticated using ((select public.can_admin_area('roles')));
grant select, insert, delete on public.function_group_modules to authenticated;

-- Only active groups, and only top-level parts that aren't protected or
-- everyone's own (sub-parts follow their part).
create or replace function public.guard_function_group_module()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  m record;
begin
  if not exists (select 1 from public.function_groups where id = new.function_group_id and active) then
    raise exception 'That function group isn''t in use. Choose another.';
  end if;
  select * into m from public.app_modules where id = new.module_id;
  if not found or m.status <> 'active' or m.parent_id is not null or m.id like 'cat\_%' or m.category = 'workspace' or m.sensitivity = 'protected' then
    raise exception 'That part can''t belong to a function group.';
  end if;
  new.created_by := auth.uid();
  new.created_at := now();
  return new;
end;
$$;
revoke execute on function public.guard_function_group_module() from public, anon, authenticated;
drop trigger if exists guard_function_group_module on public.function_group_modules;
create trigger guard_function_group_module before insert on public.function_group_modules
  for each row execute function public.guard_function_group_module();

-- Starting mapping (only parts that exist; running again adds nothing).
insert into public.function_group_modules (function_group_id, module_id)
select g.id, x.module_id
  from (values
    ('management_admin', 'ops.tasks'), ('management_admin', 'ops.registers'), ('management_admin', 'ops.scoreboard'),
    ('management_admin', 'workflows.forms'), ('management_admin', 'ops.cars'), ('management_admin', 'ops.features'),
    ('management_admin', 'ops.apps'), ('management_admin', 'people.staff'), ('management_admin', 'people.invite'),
    ('management_admin', 'people.teams'), ('management_admin', 'people.roles'), ('management_admin', 'insights.reports'),
    ('management_admin', 'engagement.assistant'), ('management_admin', 'engagement.enquiries'), ('management_admin', 'engagement.website'),
    ('management_admin', 'hr.requests'),
    ('hr_workforce', 'hr.onboarding'), ('hr_workforce', 'hr.contracts'), ('hr_workforce', 'hr.requests'), ('hr_workforce', 'hr.records'),
    ('hr_workforce', 'people.staff'), ('hr_workforce', 'people.invite'), ('hr_workforce', 'people.teams'), ('hr_workforce', 'people.roles'),
    ('care_coordination', 'clients.list'), ('care_coordination', 'ops.tasks'), ('care_coordination', 'workflows.forms'),
    ('service_delivery', 'ops.tasks'), ('service_delivery', 'ops.cars'), ('service_delivery', 'ops.apps'), ('service_delivery', 'workflows.forms'),
    ('finance_accounts', 'insights.reports'), ('finance_accounts', 'hr.records'),
    ('allied_health', 'clients.list'), ('allied_health', 'workflows.forms')
  ) x(group_key, module_id)
  join public.function_groups g on g.key = x.group_key and g.active
  join public.app_modules m on m.id = x.module_id and m.status = 'active'
on conflict do nothing;

$m122$;
  insert into public.install_log (name) values ('20270218000001_function_group_modules.sql');
end;
$part$;

-- ====================================================================
-- 20270219000001_client_parts_and_roles.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270219000001_client_parts_and_roles.sql') then
    return;
  end if;
  execute $m123$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 105; function-based access, Stage 5a; D-045, D-047,
-- D-050, owner approved the Stage 5 recommendations 17 Nov 2026):
-- the parts of Clients, and three new roles.
--
--   * Clients is split into parts so each can be given on its own:
--     details, contacts, risk notes and services are sensitive (a role or a
--     person only, never a whole function group); locations, alerts and
--     assigning staff are normal. Nobody's access changes in this update
--     (Clients still uses the built-in rule until update 107).
--   * New roles (job titles), all at the support worker access level; their
--     extra access comes from grants on the role (update 107):
--       - Case Manager and Intake & Assessment Officer (Care & Coordination);
--       - Payroll & Rostering (HR & Workforce, Finance & Accounts).
--     Existing roles with the same name are left as they are.

insert into public.app_modules (id, parent_id, category, label, sensitivity, delegable, sort_order, actions) values
  ('clients.details', 'clients.list', 'clients', 'Client details', 'sensitive', true, 251, '{view,edit}'),
  ('clients.people', 'clients.list', 'clients', 'Contacts and support people', 'sensitive', true, 252, '{view,edit}'),
  ('clients.locations', 'clients.list', 'clients', 'Locations', 'normal', true, 253, '{view,edit}'),
  ('clients.alerts', 'clients.list', 'clients', 'Alerts', 'normal', true, 254, '{view,edit}'),
  ('clients.notes', 'clients.list', 'clients', 'Risk notes', 'sensitive', true, 255, '{view,edit}'),
  ('clients.services', 'clients.list', 'clients', 'Services', 'sensitive', true, 256, '{view,edit}'),
  ('clients.assign', 'clients.list', 'clients', 'Assigning staff', 'normal', true, 257, '{view,edit}')
on conflict (id) do nothing;

insert into public.job_titles (name, access_level, description)
select x.name, 'support_worker', x.description
  from (values
    ('Case Manager', 'Manages the clients assigned to them. Not a centre manager.'),
    ('Intake & Assessment Officer', 'Takes new clients and referrals, and assigns clients to staff.'),
    ('Payroll & Rostering', 'Payroll and rosters.')
  ) x(name, description)
 where not exists (select 1 from public.job_titles t where lower(t.name) = lower(x.name));

insert into public.job_title_functions (job_title_id, function_group_id)
select t.id, g.id
  from (values
    ('Case Manager', 'care_coordination'),
    ('Intake & Assessment Officer', 'care_coordination'),
    ('Payroll & Rostering', 'hr_workforce'),
    ('Payroll & Rostering', 'finance_accounts')
  ) x(title, group_key)
  join public.job_titles t on t.name = x.title
  join public.function_groups g on g.key = x.group_key and g.active
on conflict do nothing;

$m123$;
  insert into public.install_log (name) values ('20270219000001_client_parts_and_roles.sql');
end;
