-- ====================================================================
-- 20270303000001_new_role_defaults.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270303000001_new_role_defaults.sql') then
    return;
  end if;
  execute $m135$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 117; owner chose these on 17 Nov 2026): more default
-- access for the Case Manager, Intake & Assessment Officer and Payroll &
-- Rostering job titles. Everything stays changeable on the Access page.
--
--   * Case Manager (their assigned clients): change funding (update what's
--     been used) and service agreements; view the compliance report.
--   * Intake & Assessment Officer (every client): view and add funding, view
--     reviews and re-assessments, change services.
--   * Payroll & Rostering (every client, view only): the client list,
--     approved locations, services, safety alerts and funding. (The staff
--     onboarding expiry list waits for a decision: today only people who
--     manage onboarding can read other staff's check records.)
--   * Nobody else changes. Staff admins still get nothing for clients (D-052).

do $$
declare
  v_cm uuid := (select id from public.job_titles where name = 'Case Manager' and active limit 1);
  v_io uuid := (select id from public.job_titles where name = 'Intake & Assessment Officer' and active limit 1);
  v_pr uuid := (select id from public.job_titles where name = 'Payroll & Rostering' and active limit 1);
  g record;
begin
  for g in
    select * from (values
      (v_cm, 'clients.funding', '{view,edit}'::text[], 'assigned'),
      (v_cm, 'clients.agreements', '{view,edit}'::text[], 'assigned'),
      (v_cm, 'insights.reports.compliance', '{view}'::text[], 'all'),
      (v_io, 'clients.funding', '{view,edit}'::text[], 'all'),
      (v_io, 'clients.reviews', '{view}'::text[], 'all'),
      (v_io, 'clients.services', '{view,edit}'::text[], 'all'),
      (v_pr, 'clients.list', '{view}'::text[], 'all'),
      (v_pr, 'clients.locations', '{view}'::text[], 'all'),
      (v_pr, 'clients.services', '{view}'::text[], 'all'),
      (v_pr, 'clients.alerts', '{view}'::text[], 'all'),
      (v_pr, 'clients.funding', '{view}'::text[], 'all')
    ) as t(title_id, module_id, actions, scope)
  loop
    continue when g.title_id is null;
    -- Already given exactly this (for example on a second run): nothing to do.
    continue when exists (select 1 from public.access_baselines b
                           where b.job_title_id = g.title_id and b.module_id = g.module_id and b.revoked_at is null
                             and b.actions @> g.actions and b.actions <@ g.actions and b.scope = g.scope);
    -- Replace the narrower default (kept for history, marked revoked).
    update public.access_baselines set revoked_at = now()
     where job_title_id = g.title_id and module_id = g.module_id and revoked_at is null;
    insert into public.access_baselines (job_title_id, module_id, actions, scope, note)
    values (g.title_id, g.module_id, g.actions, g.scope, 'Update 117: owner chose more default access for this role');
  end loop;
end $$;

$m135$;
  insert into public.install_log (name) values ('20270303000001_new_role_defaults.sql');
end;
$part$;

-- ====================================================================
-- 20270304000001_client_fields_and_archive.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270304000001_client_fields_and_archive.sql') then
    return;
  end if;
  execute $m136$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 118; owner chose the fields on 17 Nov 2026): more client
-- details, required by scheme, and archiving with a reason.
--
--   * Names: title, first, middle and last name. When first and last are
--     filled in, the client's name is made from them (first and last).
--   * Optional details (sensitive part "Client details": managers and the
--     client's care manager only): gender, state, time zone (Sydney unless
--     changed), living situation, about them, religion, marital status,
--     Aboriginal and/or Torres Strait Islander status, country of birth,
--     nationality, tags. Religion, marital status and cultural identity are
--     sensitive information: collected only with consent, each has
--     "Prefer not to say".
--   * Required by scheme (readiness, before a service can start): NDIS
--     services need the NDIS number; Support at Home services need the My
--     Aged Care ID (date of birth for both, as before).
--   * Archiving: a client is archived (status Discharged) with a reason
--     (transferred, moved away, no longer needs support, funding ended, passed
--     away, their choice, or other with a note); who and when are recorded.
--     They're hidden from Cars and features. Nothing is deleted; they can be
--     made active again.
--   * Not added (owner): cost calculation, day/evening/night times and SMS
--     opt-in wait for rostering and client messaging.

alter table public.car_clients add column if not exists title text not null default ''
  check (title in ('', 'mr', 'mrs', 'ms', 'miss', 'mx', 'dr'));
alter table public.car_clients add column if not exists given_name text not null default '' check (length(given_name) <= 40);
alter table public.car_clients add column if not exists middle_name text not null default '' check (length(middle_name) <= 40);
alter table public.car_clients add column if not exists family_name text not null default '' check (length(family_name) <= 40);
alter table public.car_clients add column if not exists archive_reason text
  check (archive_reason in ('transferred', 'moved_away', 'no_longer_needed', 'funding_ended', 'passed_away', 'client_choice', 'other'));
alter table public.car_clients add column if not exists archive_note text not null default '' check (length(archive_note) <= 500);
alter table public.car_clients add column if not exists archived_at timestamptz;
alter table public.car_clients add column if not exists archived_by uuid references public.profiles (id);

alter table public.client_details add column if not exists gender text not null default ''
  check (gender in ('', 'female', 'male', 'non_binary', 'different_term', 'prefer_not_to_say'));
alter table public.client_details add column if not exists state text not null default ''
  check (state in ('', 'NSW', 'VIC', 'QLD', 'SA', 'WA', 'TAS', 'NT', 'ACT'));
alter table public.client_details add column if not exists time_zone text not null default 'Australia/Sydney'
  check (time_zone in ('Australia/Sydney', 'Australia/Melbourne', 'Australia/Brisbane', 'Australia/Adelaide', 'Australia/Darwin', 'Australia/Perth', 'Australia/Hobart', 'Australia/Lord_Howe'));
alter table public.client_details add column if not exists living_situation text not null default ''
  check (living_situation in ('', 'own_home', 'with_family', 'supported_accommodation', 'residential_care', 'other'));
alter table public.client_details add column if not exists about text not null default '' check (length(about) <= 2000);
alter table public.client_details add column if not exists religion text not null default '' check (length(religion) <= 60);
alter table public.client_details add column if not exists marital_status text not null default ''
  check (marital_status in ('', 'single', 'partnered', 'married', 'separated', 'divorced', 'widowed', 'prefer_not_to_say'));
alter table public.client_details add column if not exists atsi_status text not null default ''
  check (atsi_status in ('', 'aboriginal', 'torres_strait_islander', 'both', 'neither', 'prefer_not_to_say'));
alter table public.client_details add column if not exists country_of_birth text not null default '' check (length(country_of_birth) <= 60);
alter table public.client_details add column if not exists nationality text not null default '' check (length(nationality) <= 60);
alter table public.client_details add column if not exists tags text[] not null default '{}'
  check (cardinality(tags) <= 10 and array_to_string(tags, '') !~ '[<>]');

-- Names and archiving (alongside the existing client record guard).
create or replace function public.guard_client_names_and_archive()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.given_name := trim(new.given_name);
  new.middle_name := trim(new.middle_name);
  new.family_name := trim(new.family_name);
  if (new.given_name = '') <> (new.family_name = '') then
    raise exception 'Fill in both the first and last name.';
  end if;
  if new.given_name <> '' and (tg_op = 'INSERT' or (new.given_name, new.family_name) is distinct from (old.given_name, old.family_name)) then
    new.name := left(new.given_name || ' ' || new.family_name, 80);
  end if;
  if new.status = 'discharged' and (tg_op = 'INSERT' or old.status is distinct from 'discharged') then
    if new.archive_reason is null then
      raise exception 'Choose why this client is being archived.';
    end if;
    if new.archive_reason = 'other' and length(trim(new.archive_note)) = 0 then
      raise exception 'Say why this client is being archived.';
    end if;
    new.archived_at := now();
    new.archived_by := auth.uid();
    new.active := false;
  elsif tg_op = 'UPDATE' and old.status = 'discharged' and new.status <> 'discharged' then
    -- Made active again: shown again; the last archive reason stays on record.
    new.active := true;
  elsif tg_op = 'UPDATE' then
    new.archive_reason := old.archive_reason;
    new.archive_note := old.archive_note;
    new.archived_at := old.archived_at;
    new.archived_by := old.archived_by;
  end if;
  return new;
end;
$$;
revoke execute on function public.guard_client_names_and_archive() from public, anon, authenticated;
drop trigger if exists guard_client_names_and_archive on public.car_clients;
create trigger guard_client_names_and_archive before insert or update on public.car_clients
  for each row execute function public.guard_client_names_and_archive();

-- Readiness: each scheme's own identifier (never mixed).
create or replace function public.client_gaps(p_client uuid, p_program uuid, p_location uuid, p_consent_required boolean, p_consent_given date)
returns text[]
language sql
stable
set search_path = ''
as $$
  select array_remove(array[
    case when (select status from public.car_clients where id = p_client) is distinct from 'active'
         then 'The client isn''t active yet.' end,
    case when not exists (select 1 from public.client_locations l
                           where l.id = p_location and l.client_id = p_client and l.approved
                             and (l.from_date is null or l.from_date <= public.local_today())
                             and (l.to_date is null or l.to_date >= public.local_today()))
         then 'The service location isn''t approved and current.' end,
    case when not exists (select 1 from public.client_people where client_id = p_client and kind = 'emergency' and active)
         then 'No emergency contact.' end,
    case when not exists (select 1 from public.client_alerts where client_id = p_client and active)
         then 'Safety isn''t answered (add an alert, or record "No known safety alerts").' end,
    case when coalesce((select needs_dob from public.client_programs where id = p_program), false)
              and (select date_of_birth from public.client_details where client_id = p_client) is null
         then 'Date of birth is needed for this program.' end,
    case when (select scheme from public.client_programs where id = p_program) = 'ndis'
              and coalesce((select ndis_number from public.client_details where client_id = p_client), '') = ''
         then 'The NDIS number is needed for an NDIS service.' end,
    case when (select scheme from public.client_programs where id = p_program) = 'support_at_home'
              and coalesce((select aged_care_id from public.client_details where client_id = p_client), '') = ''
         then 'The My Aged Care ID is needed for a Support at Home service.' end,
    case when p_consent_required and p_consent_given is null
         then 'Consent is needed and hasn''t been recorded.' end
  ], null)
$$;

$m136$;
  insert into public.install_log (name) values ('20270304000001_client_fields_and_archive.sql');
end;
$part$;

-- ====================================================================
-- 20270305000001_offboarding.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270305000001_offboarding.sql') then
    return;
  end if;
  execute $m137$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 119; HR block step 1, owner's order): offboarding.
--
--   * New part "Offboarding" (HR). Managers and staff admins by default (the
--     same people who manage staff); changeable on the Access page.
--   * Starting offboarding records why they're leaving and their last day,
--     and makes a checklist: car keys and fuel card, equipment and ID badge,
--     client keys and key safe codes, exit interview, final pay to payroll,
--     deactivate the portal account, and reassign their open tasks and
--     clients. Steps are ticked (or marked not needed); who and when are kept.
--   * The "deactivate" step ticks itself when their account is deactivated.
--   * Exit interview notes stay with the people who manage offboarding (the
--     person leaving doesn't see the record). Nothing is deleted.

insert into public.app_modules (id, parent_id, category, label, sensitivity, delegable, sort_order, actions) values
  ('hr.offboarding', null, 'hr', 'Offboarding', 'normal', true, 245, '{view,edit}')
on conflict (id) do nothing;

create table if not exists public.offboardings (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  user_id uuid not null references public.profiles (id) on delete restrict,
  reason text not null check (reason in ('resigned', 'contract_ended', 'dismissed', 'retired', 'redundancy', 'other')),
  last_day date not null,
  note text not null default '' check (length(note) <= 1000),
  exit_notes text not null default '' check (length(exit_notes) <= 3000),
  status text not null default 'open' check (status in ('open', 'completed', 'cancelled')),
  started_by uuid default auth.uid() references public.profiles (id),
  started_at timestamptz not null default now(),
  closed_by uuid references public.profiles (id),
  closed_at timestamptz,
  updated_at timestamptz not null default now()
);
create unique index if not exists offboardings_one_open on public.offboardings (user_id) where status = 'open';

create table if not exists public.offboarding_steps (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  offboarding_id uuid not null references public.offboardings (id) on delete restrict,
  step text not null,
  title text not null check (length(title) between 1 and 120),
  sort_order int not null default 0,
  state text not null default 'todo' check (state in ('todo', 'done', 'not_needed')),
  done_by uuid references public.profiles (id),
  done_at timestamptz,
  unique (offboarding_id, step)
);

alter table public.offboardings enable row level security;
alter table public.offboarding_steps enable row level security;

drop policy if exists "see offboarding" on public.offboardings;
create policy "see offboarding" on public.offboardings
  for select to authenticated using (user_id <> (select auth.uid()) and public.can('hr.offboarding', 'view', user_id));
drop policy if exists "start offboarding" on public.offboardings;
create policy "start offboarding" on public.offboardings
  for insert to authenticated with check (user_id <> (select auth.uid()) and public.can('hr.offboarding', 'edit', user_id));
drop policy if exists "change offboarding" on public.offboardings;
create policy "change offboarding" on public.offboardings
  for update to authenticated
  using (user_id <> (select auth.uid()) and public.can('hr.offboarding', 'edit', user_id))
  with check (user_id <> (select auth.uid()) and public.can('hr.offboarding', 'edit', user_id));

drop policy if exists "see offboarding steps" on public.offboarding_steps;
create policy "see offboarding steps" on public.offboarding_steps
  for select to authenticated using (offboarding_id in (select o.id from public.offboardings o));
drop policy if exists "tick offboarding steps" on public.offboarding_steps;
create policy "tick offboarding steps" on public.offboarding_steps
  for update to authenticated
  using (offboarding_id in (select o.id from public.offboardings o where o.status = 'open' and public.can('hr.offboarding', 'edit', o.user_id)))
  with check (offboarding_id in (select o.id from public.offboardings o where o.status = 'open' and public.can('hr.offboarding', 'edit', o.user_id)));
drop policy if exists "add offboarding steps" on public.offboarding_steps;
create policy "add offboarding steps" on public.offboarding_steps
  for insert to authenticated
  with check (offboarding_id in (select o.id from public.offboardings o where o.status = 'open' and public.can('hr.offboarding', 'edit', o.user_id)));
-- No delete rules.
grant select, insert, update on public.offboardings, public.offboarding_steps to authenticated;

-- Offboarding: who started and closed it; a closed one stays as it was; the
-- standard checklist is added when it starts.
create or replace function public.guard_offboarding()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.status := 'open';
    new.started_by := auth.uid();
    new.started_at := now();
    new.closed_by := null;
    new.closed_at := null;
    return new;
  end if;
  if (new.user_id, new.started_by, new.started_at) is distinct from (old.user_id, old.started_by, old.started_at) then
    raise exception 'Who is leaving, and who started it, stay as they were.';
  end if;
  if old.status <> 'open' and new is distinct from old then
    raise exception 'This offboarding is closed. Start a new one if needed.';
  end if;
  if new.status <> 'open' and old.status = 'open' then
    new.closed_by := auth.uid();
    new.closed_at := now();
  end if;
  new.updated_at := now();
  return new;
end;
$$;
revoke execute on function public.guard_offboarding() from public, anon, authenticated;
drop trigger if exists guard_offboarding on public.offboardings;
create trigger guard_offboarding before insert or update on public.offboardings
  for each row execute function public.guard_offboarding();

create or replace function public.add_offboarding_steps()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  insert into public.offboarding_steps (offboarding_id, step, title, sort_order) values
    (new.id, 'car', 'Car keys and fuel card returned', 10),
    (new.id, 'equipment', 'Phone, laptop, ID badge and uniform returned', 20),
    (new.id, 'client_keys', 'Client keys returned; key safe codes changed', 30),
    (new.id, 'reassign', 'Open tasks and clients handed to someone else', 40),
    (new.id, 'exit_interview', 'Exit interview done', 50),
    (new.id, 'final_pay', 'Final pay and leave payout sent to payroll', 60),
    (new.id, 'deactivate', 'Portal account deactivated', 70)
  on conflict (offboarding_id, step) do nothing;
  return null;
end;
$$;
revoke execute on function public.add_offboarding_steps() from public, anon, authenticated;
drop trigger if exists add_offboarding_steps on public.offboardings;
create trigger add_offboarding_steps after insert on public.offboardings
  for each row execute function public.add_offboarding_steps();

-- A step: who ticked it and when; added steps are "other" ones.
create or replace function public.guard_offboarding_step()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' and (new.offboarding_id, new.step, new.title) is distinct from (old.offboarding_id, old.step, old.title) then
    raise exception 'A step''s wording stays as it was.';
  end if;
  -- Steps added by hand (not the standard checklist) are kept as "other" ones.
  if tg_op = 'INSERT' and pg_trigger_depth() <= 1 then
    new.step := 'other_' || substr(md5(random()::text), 1, 8);
  end if;
  if new.state <> 'todo' and (tg_op = 'INSERT' or old.state is distinct from new.state) then
    new.done_by := auth.uid();
    new.done_at := now();
  elsif new.state = 'todo' then
    new.done_by := null;
    new.done_at := null;
  end if;
  return new;
end;
$$;
revoke execute on function public.guard_offboarding_step() from public, anon, authenticated;
drop trigger if exists guard_offboarding_step on public.offboarding_steps;
create trigger guard_offboarding_step before insert or update on public.offboarding_steps
  for each row execute function public.guard_offboarding_step();

-- "Portal account deactivated" ticks itself when they're deactivated.
create or replace function public.offboarding_on_deactivate()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if old.active and not new.active then
    update public.offboarding_steps s set state = 'done'
     where s.step = 'deactivate' and s.state = 'todo'
       and s.offboarding_id in (select o.id from public.offboardings o where o.user_id = new.id and o.status = 'open');
  end if;
  return null;
end;
$$;
revoke execute on function public.offboarding_on_deactivate() from public, anon, authenticated;
drop trigger if exists offboarding_on_deactivate on public.profiles;
create trigger offboarding_on_deactivate after update of active on public.profiles
  for each row execute function public.offboarding_on_deactivate();

