-- ====================================================================
-- 20270318000001_reassign_wording.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270318000001_reassign_wording.sql') then
    return;
  end if;
  execute $m150$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects (update 132): plain wording in the shift log (owner): "assigned" and
-- "re-assigned", "published this shift", "<name>'s clock-in signature", dates
-- like "Tue 8 Jun", and no finish-time line when only the day moves. Past
-- lines stay as written (the roster rewords the old ones when it shows them).
-- Safe to run again.
create or replace function public.au_day(p timestamptz)
returns text
language sql
stable
set search_path = ''
as $$
  select to_char(p at time zone 'Australia/Sydney', 'Dy FMDD Mon')
$$;

create or replace function public.log_shift()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_src text := public.shift_source(new);
  nm text;
begin
  if tg_op = 'INSERT' then
    insert into public.shift_events (shift_id, actor, kind, summary, source)
    values (new.id, auth.uid(), 'event',
            case when new.status = 'published' then 'added and published this shift' else 'added this shift as a draft' end
            || case when new.series_id is not null then ' (repeating)' else '' end, v_src);
    if new.worker_id is not null then
      select coalesce(nullif(full_name, ''), email) into nm from public.profiles where id = new.worker_id;
      insert into public.shift_events (shift_id, actor, kind, summary, source) values (new.id, auth.uid(), 'event', 'assigned this shift to ' || coalesce(nm, 'a worker'), v_src);
    end if;
    return null;
  end if;

  -- Events (what happened).
  if new.status <> old.status then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'event',
            case new.status when 'published' then 'published this shift' when 'cancelled' then 'cancelled this shift' else 'moved this shift back to draft' end,
            'Status', initcap(old.status), initcap(new.status), v_src);
  end if;
  if new.worker_id is distinct from old.worker_id then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'event',
            case when new.worker_id is null then 'made this an open shift, so staff can put their hand up'
                 when old.worker_id is null then 'assigned this shift to ' || coalesce((select coalesce(nullif(full_name, ''), email) from public.profiles where id = new.worker_id), 'a worker')
                 else 're-assigned this shift from ' || coalesce((select coalesce(nullif(full_name, ''), email) from public.profiles where id = old.worker_id), 'a worker')
                      || ' to ' || coalesce((select coalesce(nullif(full_name, ''), email) from public.profiles where id = new.worker_id), 'a worker') end,
            'Worker',
            coalesce((select coalesce(nullif(full_name, ''), email) from public.profiles where id = old.worker_id), 'Vacant'),
            coalesce((select coalesce(nullif(full_name, ''), email) from public.profiles where id = new.worker_id), 'Vacant'), v_src);
  end if;
  if new.notified_at is distinct from old.notified_at and new.notified_at is not null then
    insert into public.shift_events (shift_id, actor, kind, summary, source) values (new.id, auth.uid(), 'event', 'told the worker', 'system');
  end if;

  -- Field changes (before and after).
  if (new.starts_at at time zone 'Australia/Sydney')::date <> (old.starts_at at time zone 'Australia/Sydney')::date then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'moved this shift from ' || public.au_day(old.starts_at) || ' to ' || public.au_day(new.starts_at), 'Date', public.au_day(old.starts_at), public.au_day(new.starts_at), v_src);
  end if;
  if public.au_time(new.starts_at) <> public.au_time(old.starts_at) then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'changed the start time from ' || public.au_time(old.starts_at) || ' to ' || public.au_time(new.starts_at), 'Start time', public.au_time(old.starts_at), public.au_time(new.starts_at), v_src);
  end if;
  if public.au_time(new.ends_at) <> public.au_time(old.ends_at) then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'changed the finish time from ' || public.au_time(old.ends_at) || ' to ' || public.au_time(new.ends_at), 'Finish time', public.au_time(old.ends_at), public.au_time(new.ends_at), v_src);
  end if;
  if new.break_minutes <> old.break_minutes then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'changed the break from ' || old.break_minutes || ' to ' || new.break_minutes || ' minutes', 'Break', old.break_minutes || ' min', new.break_minutes || ' min', v_src);
  end if;
  if new.client_id is distinct from old.client_id then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'changed the client', 'Client',
            coalesce((select name from public.car_clients where id = old.client_id), 'No client'), coalesce((select name from public.car_clients where id = new.client_id), 'No client'), v_src);
  end if;
  if new.location_id is distinct from old.location_id then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'changed the location', 'Location',
            coalesce((select address from public.client_locations where id = old.location_id), 'Not set'), coalesce((select address from public.client_locations where id = new.location_id), 'Not set'), v_src);
  end if;
  if new.service_id is distinct from old.service_id then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'changed the service', 'Service',
            coalesce((select label from public.client_services where id = old.service_id), 'Not set'), coalesce((select label from public.client_services where id = new.service_id), 'Not set'), v_src);
  end if;
  if new.notes is distinct from old.notes then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'updated the worker instructions', 'Worker instructions', left(coalesce(old.notes, ''), 300), left(coalesce(new.notes, ''), 300), v_src);
  end if;
  if new.shift_type is distinct from old.shift_type then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'changed the shift type', 'Shift type', replace(initcap(old.shift_type), '_', ' '), replace(initcap(new.shift_type), '_', ' '), v_src);
  end if;
  if new.vehicle_id is distinct from old.vehicle_id then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'changed the car', 'Vehicle',
            coalesce((select name || ' (' || rego || ')' from public.cars where id = old.vehicle_id), 'None'), coalesce((select name || ' (' || rego || ')' from public.cars where id = new.vehicle_id), 'None'), v_src);
  end if;
  if new.pay_group is distinct from old.pay_group then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'changed the pay group', 'Pay group', nullif(old.pay_group, ''), nullif(new.pay_group, ''), v_src);
  end if;
  if new.allowances is distinct from old.allowances then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'changed the allowances', 'Allowances', coalesce(nullif(array_to_string(old.allowances, ', '), ''), 'None'), coalesce(nullif(array_to_string(new.allowances, ', '), ''), 'None'), v_src);
  end if;
  if new.series_id is distinct from old.series_id then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', case when new.series_id is null then 'took this shift out of its repeating series' else 'made this shift part of a repeating series' end,
            'Repeats', case when old.series_id is null then 'No' else 'Yes' end, case when new.series_id is null then 'No' else 'Yes' end, v_src);
  end if;
  if (new.needs_worker_signature, new.needs_client_signature) is distinct from (old.needs_worker_signature, old.needs_client_signature) then
    insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, new_value, source)
    values (new.id, auth.uid(), 'change', 'changed the signatures needed', 'Signatures needed',
            concat_ws(', ', case when old.needs_worker_signature then 'worker' end, case when old.needs_client_signature then 'client' end),
            concat_ws(', ', case when new.needs_worker_signature then 'worker' end, case when new.needs_client_signature then 'client' end), v_src);
  end if;
  return null;
end;
$$;
create or replace function public.guard_shift_signature()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.captured_by := auth.uid();
    new.signed_at := now();
    new.voided_at := null;
    new.voided_by := null;
    new.void_reason := null;
    insert into public.shift_events (shift_id, actor, kind, summary, field, new_value, source)
    values (new.shift_id, auth.uid(), 'event', 'recorded ' || new.signer_name || case new.kind when 'worker_in' then '''s clock-in signature' when 'worker_out' then '''s clock-out signature' when 'client' then '''s signature (client)' else '''s signature (client''s representative)' end, 'Signature', new.signer_name,
            case when exists (select 1 from public.shifts s where s.id = new.shift_id and s.worker_id = auth.uid()) then 'worker' else 'portal' end);
    return new;
  end if;
  if (to_jsonb(new) - 'voided_at' - 'voided_by' - 'void_reason') <> (to_jsonb(old) - 'voided_at' - 'voided_by' - 'void_reason') then
    raise exception 'A signature can''t be changed. Void it with a reason and record a new one.';
  end if;
  if old.voided_at is not null then
    raise exception 'That signature is already voided.';
  end if;
  if new.voided_at is null or length(trim(coalesce(new.void_reason, ''))) = 0 then
    raise exception 'Give a reason to void a signature.';
  end if;
  new.voided_at := now();
  new.voided_by := auth.uid();
  insert into public.shift_events (shift_id, actor, kind, summary, field, old_value, reason, source)
  values (new.shift_id, auth.uid(), 'event', 'voided ' || old.signer_name || case new.kind when 'worker_in' then '''s clock-in signature' when 'worker_out' then '''s clock-out signature' else '''s signature' end, 'Signature', old.signer_name, new.void_reason, 'portal');
  return new;
end;
$$;
revoke execute on function public.log_shift() from public, anon, authenticated;
revoke execute on function public.guard_shift_signature() from public, anon, authenticated;

$m150$;
  insert into public.install_log (name) values ('20270318000001_reassign_wording.sql');
end;
$part$;

-- ====================================================================
-- 20270319000001_workers_see_shift_clients.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270319000001_workers_see_shift_clients.sql') then
    return;
  end if;
  execute $m151$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects (update 133, AUD-016 §12): a worker sees what they need for
-- their own published shifts (from two weeks ago on): the client's name and
-- status, the shift's location and service, and the client's active alerts
-- and support instructions. Nothing else about the client, and nothing about
-- clients they aren't rostered with. Safe to run again.

drop policy if exists "workers see clients of their shifts" on public.car_clients;
create policy "workers see clients of their shifts" on public.car_clients
  for select to authenticated
  using (id in (select s.client_id from public.shifts s where s.worker_id = (select auth.uid()) and s.status = 'published' and s.ends_at > now() - interval '14 days' and s.client_id is not null));
drop policy if exists "workers see their shift locations" on public.client_locations;
create policy "workers see their shift locations" on public.client_locations
  for select to authenticated
  using (id in (select s.location_id from public.shifts s where s.worker_id = (select auth.uid()) and s.status = 'published' and s.ends_at > now() - interval '14 days' and s.location_id is not null));
drop policy if exists "workers see their shift services" on public.client_services;
create policy "workers see their shift services" on public.client_services
  for select to authenticated
  using (id in (select s.service_id from public.shifts s where s.worker_id = (select auth.uid()) and s.status = 'published' and s.ends_at > now() - interval '14 days' and s.service_id is not null));
drop policy if exists "workers see alerts for their shift clients" on public.client_alerts;
create policy "workers see alerts for their shift clients" on public.client_alerts
  for select to authenticated
  using (active and client_id in (select s.client_id from public.shifts s where s.worker_id = (select auth.uid()) and s.status = 'published' and s.ends_at > now() - interval '14 days' and s.client_id is not null));
drop policy if exists "workers see instructions for their shift clients" on public.client_worker_instructions;
create policy "workers see instructions for their shift clients" on public.client_worker_instructions
  for select to authenticated
  using (active and client_id in (select s.client_id from public.shifts s where s.worker_id = (select auth.uid()) and s.status = 'published' and s.ends_at > now() - interval '14 days' and s.client_id is not null));

$m151$;
  insert into public.install_log (name) values ('20270319000001_workers_see_shift_clients.sql');
end;
$part$;

-- ====================================================================
-- 20270320000001_shift_service_records.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270320000001_shift_service_records.sql') then
    return;
  end if;
  execute $m152$
-- Staff Portal · © cmeproject. All rights reserved.
-- cmeprojects (update 134, rostering brief §7): a service record for each
-- shift: what was delivered, as the worker records it after the shift. Kept
-- apart from the timesheet (hours) and the roster (the plan).
--   * The rostered worker writes it once the shift has started, and can change
--     it for 24 hours; then it's kept as written.
--   * People who roster and people who see the client's care plans read it.
--   * An incident or issue flagged tells the managers and the client's case
--     manager straight away (and the hourly reminders catch any missed).
-- Safe to run again.

create table if not exists public.shift_service_records (
  shift_id uuid primary key references public.shifts (id) on delete restrict,
  worker_id uuid not null references public.profiles (id) on delete restrict default auth.uid(),
  delivered text not null check (length(trim(delivered)) between 1 and 4000),
  client_wellbeing text not null default 'settled' check (client_wellbeing in ('settled', 'some_concerns', 'unwell_or_distressed')),
  concern boolean not null default false,
  concern_note text not null default '' check (length(concern_note) <= 2000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  told_at timestamptz
);
alter table public.shift_service_records enable row level security;

drop policy if exists "see service records" on public.shift_service_records;
create policy "see service records" on public.shift_service_records
  for select to authenticated
  using (worker_id = (select auth.uid())
         or (select public.can('ops.roster', 'view'))
         or exists (select 1 from public.shifts s where s.id = shift_id and s.client_id is not null and public.can('clients.care_plans', 'view', s.client_id)));
drop policy if exists "workers write their service record" on public.shift_service_records;
create policy "workers write their service record" on public.shift_service_records
  for insert to authenticated
  with check (worker_id = (select auth.uid())
              and shift_id in (select s.id from public.shifts s where s.worker_id = (select auth.uid()) and s.status = 'published' and s.starts_at <= now() + interval '1 hour'));
drop policy if exists "workers change their service record" on public.shift_service_records;
create policy "workers change their service record" on public.shift_service_records
  for update to authenticated
  using (worker_id = (select auth.uid()))
  with check (worker_id = (select auth.uid()));
-- No delete rule.
grant select, insert, update on public.shift_service_records to authenticated;

create or replace function public.guard_service_record()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' and new.told_at is distinct from old.told_at
     and (to_jsonb(new) - 'told_at') = (to_jsonb(old) - 'told_at') then
    return new; -- the server marking a reminder as sent
  end if;
  if tg_op = 'INSERT' then
    new.worker_id := auth.uid();
    new.created_at := now();
    new.told_at := null;
  else
    if new.worker_id is distinct from old.worker_id or new.shift_id is distinct from old.shift_id or new.created_at is distinct from old.created_at then
      raise exception 'A service record stays with its shift and worker.';
    end if;
    if old.created_at < now() - interval '24 hours' then
      raise exception 'A service record can only be changed within 24 hours. Tell the roster team if something needs correcting.';
    end if;
    -- A concern added later is told again.
    if new.concern and not old.concern then new.told_at := null; else new.told_at := old.told_at; end if;
  end if;
  new.updated_at := now();
  if not new.concern then new.concern_note := ''; end if;
  insert into public.shift_events (shift_id, actor, kind, summary, source)
  values (new.shift_id, auth.uid(), 'event',
          case when tg_op = 'INSERT' then 'recorded the service delivered' else 'updated the service record' end
          || case when new.concern then ' and flagged a concern' else '' end, 'worker');
  return new;
end;
$$;
revoke execute on function public.guard_service_record() from public, anon, authenticated;
drop trigger if exists guard_service_record on public.shift_service_records;
create trigger guard_service_record before insert or update on public.shift_service_records
  for each row execute function public.guard_service_record();

-- Concerns: the client's case manager (or the managers) are told, once.
create or replace function public.run_service_record_alerts()
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  r record;
  v int := 0;
begin
  for r in
    select q.shift_id, s.client_id, c.name, c.client_ref, coalesce(nullif(p.full_name, ''), p.email) as who, q.concern_note
      from public.shift_service_records q
      join public.shifts s on s.id = q.shift_id
      join public.profiles p on p.id = q.worker_id
      left join public.car_clients c on c.id = s.client_id
     where q.concern and q.told_at is null
  loop
    -- The managers, and the client's case manager (once each).
    perform public.notify(u, 'service_concern', r.who || ' reported an incident or issue after a shift', coalesce(r.name || ' (' || r.client_ref || '): ', '') || left(r.concern_note, 200),
                          '/roster?shift=' || r.shift_id || '&tab=service', true)
      from (select p.id as u from public.profiles p where p.active and p.role = 'manager'
            union
            select c.u from public.client_care_contacts(r.client_id) c(u) where r.client_id is not null) x;
    update public.shift_service_records set told_at = now() where shift_id = r.shift_id;
    v := v + 1;
  end loop;
  return jsonb_build_object('service_concerns', v);
end;
$$;
revoke execute on function public.run_service_record_alerts() from public, anon, authenticated;
grant execute on function public.run_service_record_alerts() to service_role;

$m152$;
  insert into public.install_log (name) values ('20270320000001_shift_service_records.sql');
end;
$part$;

-- ====================================================================
-- 20270321000001_trips_link_to_shifts.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270321000001_trips_link_to_shifts.sql') then
    return;
  end if;
  execute $m153$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 135): a car trip links itself to the driver's shift.
-- When a worker takes a company car during (or up to an hour either side of)
-- one of their published shifts, the trip is attached to that shift, so it
-- shows on the shift's Trips tab. A shift for the same client wins.
-- Not a security definer: it only reads the driver's own shifts.

create or replace function public.link_trip_to_shift() returns trigger
language plpgsql set search_path = '' as $$
begin
  if new.shift_id is null and new.driver_id is not null then
    select s.id into new.shift_id
    from public.shifts s
    where s.worker_id = new.driver_id
      and s.status = 'published'
      and coalesce(new.started_at, now()) between s.starts_at - interval '1 hour' and s.ends_at + interval '1 hour'
    order by (s.client_id is not distinct from new.client_id) desc, abs(extract(epoch from (s.starts_at - coalesce(new.started_at, now()))))
    limit 1;
  end if;
  return new;
end;
$$;
revoke execute on function public.link_trip_to_shift() from public, anon, authenticated;

drop trigger if exists link_trip_to_shift on public.car_trips;
create trigger link_trip_to_shift before insert on public.car_trips
  for each row execute function public.link_trip_to_shift();

$m153$;
  insert into public.install_log (name) values ('20270321000001_trips_link_to_shifts.sql');
end;
$part$;

