do $part$
begin
  if exists (select 1 from public.install_log where name = '20270412000001_client_views_once.sql') then
    return;
  end if;
  execute $m175$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 157): an opening is recorded once. Opening a client's
-- page, or their activity and audit trail, is recorded at most once an hour
-- for each person (the owner's rule since update 140). The page checked that
-- itself, so requests arriving together (a double click, a refresh while
-- loading) could each be recorded. The database now makes the check, one
-- request at a time, and skips a repeat within the hour. Genuine openings
-- after that are still recorded. Runs as the person (no security definer).
-- Nothing is deleted. Safe to run again.

create or replace function public.client_view_once() returns trigger
language plpgsql set search_path = '' as $$
begin
  -- One at a time for this person, client and kind of opening.
  perform pg_advisory_xact_lock(hashtextextended(new.client_id::text || '/' || new.user_id::text || '/' || new.area, 157));
  if exists (select 1 from public.client_staff_views v
              where v.client_id = new.client_id and v.user_id = new.user_id and v.area = new.area
                and v.viewed_at > now() - interval '1 hour') then
    return null; -- already recorded within the hour
  end if;
  return new;
end;
$$;
revoke execute on function public.client_view_once() from public, anon, authenticated;
drop trigger if exists client_view_once on public.client_staff_views;
create trigger client_view_once before insert on public.client_staff_views
  for each row execute function public.client_view_once();

$m175$;
  insert into public.install_log (name) values ('20270412000001_client_views_once.sql');
end;
$part$;

-- ====================================================================
-- 20270413000001_client_enrolments.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270413000001_client_enrolments.sql') then
    return;
  end if;
  execute $m176$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 158): program enrolments (Phase 1 of the programs,
-- assessments and billing plan, approved 21 Nov 2026).
--   * A client can be in more than one named program (NDIS, Support at Home,
--     CHSP, Private, Other, or a program set up under them). Each enrolment has
--     its own status (active, paused, ended), dates and history.
--   * "Funded by" (car_clients.scheme) is kept as the main program's scheme and
--     follows the main enrolment by itself. When the main one ends, another open
--     one (active first, then paused) becomes main; none open = no "Funded by".
--   * A new service needs an active enrolment in its program. A paused or ended
--     program blocks new services and new client shifts on those dates. Client
--     shifts can't skip the check by leaving out the service. Shifts with no
--     client (internal work) aren't checked. Nothing existing is re-checked.
--   * Ending a program is refused while it still has open services, agreements
--     or budgets. Nothing is ended or deleted for you.
--   * Each organisation chooses which schemes it offers (client_schemes.offered).
--     Turning one off only stops new use; existing records stay as they are.
--   * Existing clients get enrolments from their services and "Funded by"
--     (see preview-158.sql). Safe to run again: nothing is added twice.
-- No new security definer function; checks run as the person. Changes are in
-- the client audit trail. Nothing is deleted.

-- 1. Which schemes this organisation offers; scheme and program changes recorded.
alter table public.client_schemes add column if not exists offered boolean not null default true;
alter table public.client_schemes add column if not exists id uuid not null default gen_random_uuid();
drop trigger if exists client_schemes_log on public.client_schemes;
create trigger client_schemes_log after insert or update on public.client_schemes
  for each row execute function public.log_car_setup('client_scheme');
drop trigger if exists client_programs_log on public.client_programs;
create trigger client_programs_log after insert or update on public.client_programs
  for each row execute function public.log_car_setup('client_program');

-- 2. Enrolments.
create table if not exists public.client_enrolments (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  client_id uuid not null references public.car_clients (id),
  program_id uuid not null references public.client_programs (id),
  scheme text not null references public.client_schemes (key),
  status text not null default 'active' check (status in ('active', 'paused', 'ended')),
  starts_on date not null default ((now() at time zone 'Australia/Sydney')::date),
  paused_from date,
  paused_until date,
  pause_reason text not null default '' check (length(pause_reason) <= 300),
  ends_on date,
  end_reason text not null default '' check (length(end_reason) <= 300),
  is_main boolean not null default false,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  constraint client_enrolments_end_after_start check (ends_on is null or ends_on >= starts_on),
  constraint client_enrolments_ended_has_date check (status <> 'ended' or ends_on is not null),
  constraint client_enrolments_paused_has_date check (status <> 'paused' or paused_from is not null),
  constraint client_enrolments_pause_order check (paused_until is null or paused_from is null or paused_until >= paused_from),
  constraint client_enrolments_main_is_open check (not is_main or status <> 'ended')
);
create unique index if not exists client_enrolments_one_open on public.client_enrolments (client_id, program_id) where status <> 'ended';
create unique index if not exists client_enrolments_one_main on public.client_enrolments (client_id) where is_main;
create index if not exists client_enrolments_client on public.client_enrolments (client_id);

alter table public.client_enrolments enable row level security;
drop policy if exists "see enrolments of clients you can see" on public.client_enrolments;
create policy "see enrolments of clients you can see" on public.client_enrolments
  for select to authenticated using (exists (select 1 from public.car_clients c where c.id = client_id));
drop policy if exists "add enrolments" on public.client_enrolments;
create policy "add enrolments" on public.client_enrolments
  for insert to authenticated with check (public.can('clients.list', 'edit', client_id));
drop policy if exists "change enrolments" on public.client_enrolments;
create policy "change enrolments" on public.client_enrolments
  for update to authenticated using (public.can('clients.list', 'edit', client_id)) with check (public.can('clients.list', 'edit', client_id));
-- No delete: an enrolment is ended, never removed.
grant select, insert, update on public.client_enrolments to authenticated;
revoke all on public.client_enrolments from anon;

-- Requests from the portal (people) are checked; set-up scripts aren't.
create or replace function public.from_portal() returns boolean
language sql stable set search_path = '' as $$
  select session_user::text = 'authenticator' or current_user::text in ('authenticated', 'anon')
$$;

create or replace function public.guard_client_enrolment() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_api boolean := public.from_portal();
  v_prog public.client_programs;
  v_today date := (now() at time zone 'Australia/Sydney')::date;
  v_open text;
begin
  if tg_op = 'INSERT' then
    select * into v_prog from public.client_programs where id = new.program_id;
    if v_prog.id is null then
      raise exception 'Choose a program.';
    end if;
    new.scheme := v_prog.scheme;
    if v_api then
      if not v_prog.active then
        raise exception '% is switched off. Choose another program.', v_prog.name;
      end if;
      if not coalesce((select s.offered from public.client_schemes s where s.key = v_prog.scheme), false) then
        raise exception 'Your organisation doesn''t offer % at the moment.', (select s.label from public.client_schemes s where s.key = v_prog.scheme);
      end if;
      new.status := 'active';
      new.paused_from := null;
      new.paused_until := null;
      new.pause_reason := '';
      new.ends_on := null;
      new.end_reason := '';
      new.created_by := auth.uid();
      new.created_at := now();
    end if;
    if new.status <> 'ended' and exists (select 1 from public.client_enrolments e
                where e.client_id = new.client_id and e.program_id = new.program_id and e.status <> 'ended') then
      raise exception 'They''re already in %. Resume or end it instead.', v_prog.name;
    end if;
    if new.status = 'ended' then
      new.is_main := false;
    elsif new.is_main then
      update public.client_enrolments set is_main = false where client_id = new.client_id and is_main;
    elsif not exists (select 1 from public.client_enrolments e where e.client_id = new.client_id and e.is_main) then
      new.is_main := true; -- their first open program is the main one
    end if;
    return new;
  end if;

  -- Changes.
  if (new.client_id, new.program_id, new.scheme, new.created_by, new.created_at)
     is distinct from (old.client_id, old.program_id, old.scheme, old.created_by, old.created_at) then
    raise exception 'An enrolment stays with its client and program. End it and add a new one.';
  end if;
  if old.status = 'ended' then
    raise exception 'This program has ended. Add it again as a new enrolment instead.';
  end if;
  if new.starts_on is distinct from old.starts_on and exists (
       select 1 from public.client_services s
        where s.client_id = new.client_id and s.program_id = new.program_id and s.status <> 'ended' and s.start_date < new.starts_on) then
    raise exception 'Some of their services in this program start earlier. Choose a start date on or before %.',
      to_char((select min(s.start_date) from public.client_services s
                where s.client_id = new.client_id and s.program_id = new.program_id and s.status <> 'ended'), 'DD/MM/YYYY');
  end if;

  if new.status = 'paused' then
    if new.paused_from is null then
      raise exception 'Choose when the pause starts.';
    end if;
    if new.paused_from < new.starts_on then
      raise exception 'A pause can''t start before the program does (%).', to_char(new.starts_on, 'DD/MM/YYYY');
    end if;
    if new.paused_until is not null and new.paused_until < new.paused_from then
      raise exception 'The expected return can''t be before the pause starts.';
    end if;
  elsif new.status = 'active' then
    if old.status = 'paused' then -- resumed
      new.paused_from := null;
      new.paused_until := null;
      new.pause_reason := '';
    end if;
  elsif new.status = 'ended' then
    new.ends_on := coalesce(new.ends_on, v_today);
    if new.ends_on < new.starts_on then
      raise exception 'The end date can''t be before the program started (%).', to_char(new.starts_on, 'DD/MM/YYYY');
    end if;
    if v_api and length(trim(new.end_reason)) = 0 then
      raise exception 'Say why this program is ending.';
    end if;
    -- The person must be able to see everything that could still be open.
    if v_api and not (public.can('clients.services', 'view', new.client_id)
                      and public.can('clients.agreements', 'view', new.client_id)
                      and public.can('clients.funding', 'view', new.client_id)) then
      raise exception 'To end a program you need to see this client''s services, agreements and budgets. Ask a manager.';
    end if;
    select string_agg(x, '; ' order by x) into v_open from (
      select 'service "' || s.label || '"' as x
        from public.client_services s
       where s.client_id = new.client_id and s.program_id = new.program_id
         and s.status <> 'ended' and (s.end_date is null or s.end_date > new.ends_on)
      union all
      select 'agreement for "' || s.label || '"'
        from public.client_agreements a join public.client_services s on s.id = a.service_id
       where a.client_id = new.client_id and s.program_id = new.program_id and a.status <> 'ended'
      union all
      select 'budget for "' || s.label || '"'
        from public.client_funding f join public.client_services s on s.id = f.service_id
       where f.client_id = new.client_id and s.program_id = new.program_id
         and f.status = 'active' and (f.period_end is null or f.period_end > new.ends_on)
    ) b;
    if v_open is not null then
      raise exception 'Close or end these first: %.', v_open;
    end if;
    new.is_main := false;
  end if;

  if new.is_main and not old.is_main then
    update public.client_enrolments set is_main = false where client_id = new.client_id and is_main and id <> new.id;
  elsif old.is_main and not new.is_main and new.status <> 'ended' and pg_trigger_depth() = 1 then
    raise exception 'Choose another program as the main one instead.';
  end if;
  return new;
end;
$$;
revoke execute on function public.guard_client_enrolment() from public, anon, authenticated;

-- After a change: keep a main program, and "Funded by" in step with it.
create or replace function public.sync_client_main() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_next uuid;
  v_scheme text;
begin
  if pg_trigger_depth() > 1 then
    return null;
  end if;
  if not exists (select 1 from public.client_enrolments e where e.client_id = new.client_id and e.is_main) then
    select e.id into v_next from public.client_enrolments e
     where e.client_id = new.client_id and e.status <> 'ended'
     order by (e.status = 'active') desc, e.starts_on, e.created_at
     limit 1;
    if v_next is not null then
      update public.client_enrolments set is_main = true where id = v_next;
    end if;
  end if;
  select e.scheme into v_scheme from public.client_enrolments e where e.client_id = new.client_id and e.is_main;
  perform set_config('portal.enrolment_sync', 'on', true);
  update public.car_clients set scheme = v_scheme where id = new.client_id and scheme is distinct from v_scheme;
  perform set_config('portal.enrolment_sync', '', true);
  return null;
end;
$$;
revoke execute on function public.sync_client_main() from public, anon, authenticated;

drop trigger if exists guard_client_enrolment on public.client_enrolments;
create trigger guard_client_enrolment before insert or update on public.client_enrolments
  for each row execute function public.guard_client_enrolment();
drop trigger if exists log_client_change on public.client_enrolments;
create trigger log_client_change before insert or update on public.client_enrolments
  for each row execute function public.log_client_change();
drop trigger if exists log_client_audit on public.client_enrolments;
create trigger log_client_audit after insert or update or delete on public.client_enrolments
  for each row execute function public.log_client_change();
drop trigger if exists sync_client_main on public.client_enrolments;
create trigger sync_client_main after insert or update on public.client_enrolments
  for each row execute function public.sync_client_main();

-- 3. "Funded by" follows the main program (not changed directly from the portal).
create or replace function public.guard_funded_by() returns trigger
language plpgsql set search_path = '' as $$
begin
  if not public.from_portal() or coalesce(current_setting('portal.enrolment_sync', true), '') = 'on' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    new.scheme := null; -- set from their programs
  elsif new.scheme is distinct from old.scheme then
    raise exception 'Who funds a client follows their main program. Change it on their Programs card.';
  end if;
  return new;
end;
$$;
revoke execute on function public.guard_funded_by() from public, anon, authenticated;
drop trigger if exists guard_funded_by on public.car_clients;
create trigger guard_funded_by before insert or update on public.car_clients
  for each row execute function public.guard_funded_by();

-- 4. A new service needs an active enrolment in its program.
create or replace function public.guard_service_enrolment() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_e public.client_enrolments;
  v_name text;
begin
  if not public.from_portal() then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.program_id is not distinct from old.program_id and new.start_date is not distinct from old.start_date then
    return new;
  end if;
  select p.name into v_name from public.client_programs p where p.id = new.program_id;
  select * into v_e from public.client_enrolments e
   where e.client_id = new.client_id and e.program_id = new.program_id and e.status <> 'ended';
  if v_e.id is null then
    raise exception 'Add % to their programs first (Profile, Programs).', coalesce(v_name, 'the program');
  end if;
  if v_e.status = 'paused' then
    raise exception '% is paused for this client. Resume it to add services.', v_name;
  end if;
  if new.start_date < v_e.starts_on then
    raise exception 'They''re in % from %. Choose that date or later.', v_name, to_char(v_e.starts_on, 'DD/MM/YYYY');
  end if;
  return new;
end;
$$;
revoke execute on function public.guard_service_enrolment() from public, anon, authenticated;
drop trigger if exists guard_service_enrolment on public.client_services;
create trigger guard_service_enrolment before insert or update on public.client_services
  for each row execute function public.guard_service_enrolment();

-- 5. Client shifts: the program must be active (not paused or ended) on the shift date.
create or replace function public.guard_shift_enrolment() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_day date;
  v_prog uuid;
  v_name text;
  v_e public.client_enrolments;
begin
  if not public.from_portal() or new.client_id is null or new.status = 'cancelled' then
    return new; -- internal shifts (no client) and set-up scripts aren't checked
  end if;
  if tg_op = 'UPDATE' and (new.starts_at, new.client_id, new.service_id) is not distinct from (old.starts_at, old.client_id, old.service_id) then
    return new; -- other changes to an existing shift
  end if;
  v_day := (new.starts_at at time zone 'Australia/Sydney')::date;
  if new.service_id is not null then
    select s.program_id, p.name into v_prog, v_name
      from public.client_services s join public.client_programs p on p.id = s.program_id where s.id = new.service_id;
    select * into v_e from public.client_enrolments e
     where e.client_id = new.client_id and e.program_id = v_prog and e.starts_on <= v_day and (e.ends_on is null or e.ends_on >= v_day)
     order by e.starts_on desc limit 1;
    if v_e.id is null then
      raise exception '% isn''t one of this client''s programs on %.', v_name, to_char(v_day, 'DD/MM/YYYY');
    end if;
    if v_e.status = 'paused' and v_day >= v_e.paused_from and (v_e.paused_until is null or v_day <= v_e.paused_until) then
      raise exception '%', v_name || ' is paused for this client from ' || to_char(v_e.paused_from, 'DD/MM/YYYY')
        || coalesce(' until ' || to_char(v_e.paused_until, 'DD/MM/YYYY'), '') || '.';
    end if;
  elsif not exists (select 1 from public.client_enrolments e
                     where e.client_id = new.client_id and e.starts_on <= v_day and (e.ends_on is null or e.ends_on >= v_day)
                       and not (e.status = 'paused' and v_day >= e.paused_from and (e.paused_until is null or v_day <= e.paused_until))) then
    raise exception 'This client has no active program on %. Choose one of their approved services, or add a program first.', to_char(v_day, 'DD/MM/YYYY');
  end if;
  return new;
end;
$$;
revoke execute on function public.guard_shift_enrolment() from public, anon, authenticated;
drop trigger if exists guard_shift_enrolment on public.shifts;
create trigger guard_shift_enrolment before insert or update on public.shifts
  for each row execute function public.guard_shift_enrolment();

-- 6. Readiness: "No active program", and a service whose program isn't active.
create or replace function public.client_gaps(p_client uuid, p_program uuid, p_location uuid, p_consent_required boolean, p_consent_given date)
 returns text[] language sql stable set search_path = '' as $$
  select array_remove(array[
    case when (select status from public.car_clients where id = p_client) is distinct from 'active'
         then 'The client isn''t active yet.' end,
    case when p_program is null and not exists (select 1 from public.client_enrolments e where e.client_id = p_client and e.status <> 'ended')
         then 'No active program.' end,
    case when p_program is not null and not exists (select 1 from public.client_enrolments e where e.client_id = p_client and e.program_id = p_program and e.status = 'active')
         then 'This service''s program isn''t active for them (not added, paused or ended).' end,
    case when not exists (select 1 from public.client_locations l
                           where l.id = p_location and l.client_id = p_client and l.approved
                             and (l.from_date is null or l.from_date <= public.local_today())
                             and (l.to_date is null or l.to_date >= public.local_today()))
         then 'The service location isn''t approved and current.' end,
    case when not exists (select 1 from public.client_people where client_id = p_client and kind = 'emergency' and active)
         then 'No emergency contact.' end,
    case when not exists (select 1 from public.client_alerts where client_id = p_client and active)
         then 'Safety isn''t answered (add an alert, or record "No known safety alerts").' end,
    case when coalesce((select needs_dob from public.client_programs where id = p_program), false)
              and (select date_of_birth from public.client_details where client_id = p_client) is null
         then 'Date of birth is needed for this program.' end,
    case when (select scheme from public.client_programs where id = p_program) = 'ndis'
              and coalesce((select ndis_number from public.client_details where client_id = p_client), '') = ''
         then 'The NDIS number is needed for an NDIS service.' end,
    case when (select scheme from public.client_programs where id = p_program) in ('support_at_home', 'chsp')
              and coalesce((select aged_care_id from public.client_details where client_id = p_client), '') = ''
         then 'The My Aged Care ID is needed for a Support at Home or CHSP service.' end,
    case when p_consent_required and p_consent_given is null
         then 'Consent is needed and hasn''t been recorded.' end
  ], null)
$$;

-- 7. Adding a client: their programs (one or more) are saved with them.
drop function if exists public.create_client_full(jsonb, jsonb, uuid, text);
create or replace function public.create_client_full(p_client jsonb, p_details jsonb, p_manager uuid default null, p_as text default 'case_manager',
                                                     p_programs uuid[] default '{}', p_main uuid default null, p_starts date default null)
 returns uuid language plpgsql set search_path = '' as $$
declare
  v_id uuid;
  v_main uuid := coalesce(p_main, p_programs[1]);
  v_p uuid;
begin
  if coalesce(cardinality(p_programs), 0) = 0 then
    raise exception 'Choose at least one program.';
  end if;
  if not (v_main = any (p_programs)) then
    raise exception 'The main program must be one of the programs chosen.';
  end if;
  insert into public.car_clients (name, title, given_name, middle_name, family_name, preferred_name, reference)
  values (p_client ->> 'name', coalesce(p_client ->> 'title', ''), p_client ->> 'given_name', coalesce(p_client ->> 'middle_name', ''), p_client ->> 'family_name',
          coalesce(p_client ->> 'preferred_name', ''), coalesce(p_client ->> 'reference', ''))
  returning id into v_id;
  insert into public.client_details (client_id, date_of_birth, gender, phone, email, home_address, state, ndis_number, aged_care_id)
  values (v_id, nullif(p_details ->> 'date_of_birth', '')::date, coalesce(p_details ->> 'gender', ''), coalesce(p_details ->> 'phone', ''), coalesce(p_details ->> 'email', ''),
          coalesce(p_details ->> 'home_address', ''), coalesce(p_details ->> 'state', ''), coalesce(p_details ->> 'ndis_number', ''), coalesce(p_details ->> 'aged_care_id', ''));
  -- The main program first, so it's the main one.
  insert into public.client_enrolments (client_id, program_id, starts_on, is_main)
  values (v_id, v_main, coalesce(p_starts, (now() at time zone 'Australia/Sydney')::date), true);
  foreach v_p in array p_programs loop
    if v_p <> v_main then
      insert into public.client_enrolments (client_id, program_id, starts_on)
      values (v_id, v_p, coalesce(p_starts, (now() at time zone 'Australia/Sydney')::date));
    end if;
  end loop;
  if p_manager is not null then
    insert into public.client_assignments (client_id, user_id, assigned_as) values (v_id, p_manager, coalesce(p_as, 'case_manager'));
  end if;
  return v_id;
end;
$$;
revoke execute on function public.create_client_full(jsonb, jsonb, uuid, text, uuid[], uuid, date) from public, anon;
grant execute on function public.create_client_full(jsonb, jsonb, uuid, text, uuid[], uuid, date) to authenticated;

-- 8. Existing clients: enrolments from their services and "Funded by" (as in
-- preview-158.sql; owner's decisions of 21 Nov 2026). Only what's missing is added.
do $backfill$
begin
  create temporary table backfill_158 on commit drop as
  with today as (select (now() at time zone 'Australia/Sydney')::date as d),
  svc as (
    select s.client_id, s.program_id, p.scheme, min(s.start_date) as first_start,
           count(*) filter (where s.status <> 'ended' and (s.end_date is null or s.end_date >= (select d from today))) as open_services,
           max(coalesce(s.end_date, (s.updated_at at time zone 'Australia/Sydney')::date)) as last_end
      from public.client_services s join public.client_programs p on p.id = s.program_id
     group by 1, 2, 3
  ),
  fb as (
    select c.id as client_id, c.scheme,
           (array_agg(p.id order by p.sort_order) filter (where p.active))[1] as program_id
      from public.car_clients c left join public.client_programs p on p.scheme = c.scheme
     where c.scheme is not null and not exists (select 1 from svc where svc.client_id = c.id and svc.scheme = c.scheme)
     group by 1, 2
  ),
  proposed as (
    select c.id as client_id, svc.program_id, svc.scheme, svc.first_start as starts_on,
           case when c.status = 'discharged' or svc.open_services = 0 then 'ended' else 'active' end as status,
           case when c.status = 'discharged' then greatest(svc.first_start, coalesce((c.archived_at at time zone 'Australia/Sydney')::date, svc.last_end))
                when svc.open_services = 0 then greatest(svc.first_start, svc.last_end) end as ends_on
      from svc join public.car_clients c on c.id = svc.client_id
    union all
    select c.id, fb.program_id, fb.scheme, (c.created_at at time zone 'Australia/Sydney')::date,
           case when c.status = 'discharged' then 'ended' else 'active' end,
           case when c.status = 'discharged' then greatest((c.created_at at time zone 'Australia/Sydney')::date, (c.archived_at at time zone 'Australia/Sydney')::date) end
      from fb join public.car_clients c on c.id = fb.client_id
     where fb.program_id is not null
  )
  select pr.*, row_number() over (partition by pr.client_id
                                  order by (pr.status = 'active') desc, (pr.scheme is not distinct from c.scheme) desc, pr.starts_on, pr.program_id) as pick
    from proposed pr join public.car_clients c on c.id = pr.client_id
   where not exists (select 1 from public.client_enrolments e where e.client_id = pr.client_id and e.program_id = pr.program_id);

  -- The main program first (only for clients without one yet), then the rest.
  insert into public.client_enrolments (client_id, program_id, status, starts_on, ends_on, end_reason, is_main)
  select b.client_id, b.program_id, b.status, b.starts_on, b.ends_on,
         case when b.status = 'ended' then 'Recorded when programs were added (update 158)' else '' end,
         true
    from backfill_158 b
   where b.pick = 1 and b.status = 'active'
     and not exists (select 1 from public.client_enrolments e where e.client_id = b.client_id and e.is_main);
  insert into public.client_enrolments (client_id, program_id, status, starts_on, ends_on, end_reason, is_main)
  select b.client_id, b.program_id, b.status, b.starts_on, b.ends_on,
         case when b.status = 'ended' then 'Recorded when programs were added (update 158)' else '' end,
         false
    from backfill_158 b
   where not exists (select 1 from public.client_enrolments e where e.client_id = b.client_id and e.program_id = b.program_id);
end
$backfill$;

$m176$;
  insert into public.install_log (name) values ('20270413000001_client_enrolments.sql');
end;
$part$;

-- ====================================================================
-- 20270414000001_assessments.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270414000001_assessments.sql') then
    return;
  end if;
  execute $m177$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 159): assessments (Phase 2 of the programs, assessments
-- and billing plan, approved 21 Nov 2026).
--   * Templates with versions. A published version, its sections, questions,
--     options, "show only when" rules and finding mappings can never change;
--     changes go into a new version (a copy). Every assessment keeps the exact
--     version it was answered against.
--   * Client assessments: draft -> completed (or cancelled with a reason).
--     A completed assessment never changes; a correction or reassessment is a
--     new assessment that replaces it, and the old one becomes "superseded".
--   * Structured findings (needs, goals, risks ...) made from mapped answers,
--     kept apart from the answers. Saving again never duplicates them; one
--     answer can make several; assessors add their own; a finding that no
--     longer applies is withdrawn (kept), an edited one is flagged instead.
--     Findings are fixed once the assessment is completed.
--   * Answers reused from an earlier assessment only where the question key and
--     type match; they must be confirmed before completing.
--   * Checks run in the database (as the person), so direct requests follow the
--     same rules. No new security definer function. Nothing is deleted except
--     unpublished draft template parts.
--   * Access: "Assessments" (clients.assessments) with the same defaults and
--     reach as care plans; templates by Manager Administrators and the care
--     settings area. No support worker or practitioner access.
--   * Viewing an assessment is recorded once an hour per person; printing is
--     recorded every time. Changes are in the client audit trail.
-- Safe to run again.

-- 1. Templates and versions.
create table if not exists public.assessment_templates (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  name text not null check (length(trim(name)) between 1 and 120),
  description text not null default '' check (length(description) <= 1000),
  schemes text[] not null default '{}', -- empty = common to all programs
  active boolean not null default true,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.assessment_versions (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  template_id uuid not null references public.assessment_templates (id),
  version integer not null check (version >= 1),
  status text not null default 'draft' check (status in ('draft', 'published', 'retired')),
  effective_from date,
  published_by uuid,
  published_at timestamptz,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  unique (template_id, version)
);
create unique index if not exists assessment_versions_one_draft on public.assessment_versions (template_id) where status = 'draft';
create table if not exists public.assessment_sections (
  id uuid primary key default gen_random_uuid(),
  version_id uuid not null references public.assessment_versions (id) on delete cascade,
  title text not null check (length(trim(title)) between 1 and 120),
  sort_order integer not null default 0,
  enabled boolean not null default true,
  rule jsonb
);
create table if not exists public.assessment_questions (
  id uuid primary key default gen_random_uuid(),
  version_id uuid not null references public.assessment_versions (id) on delete cascade,
  section_id uuid not null references public.assessment_sections (id) on delete cascade,
  key text not null check (key ~ '^[a-z][a-z0-9_]{0,59}$'),
  label text not null check (length(trim(label)) between 1 and 300),
  type text not null check (type in ('text', 'long', 'choice', 'multi', 'yesno', 'date', 'number')),
  required boolean not null default false,
  help text not null default '' check (length(help) <= 300),
  options jsonb not null default '[]' check (jsonb_typeof(options) = 'array'),
  validation jsonb not null default '{}' check (jsonb_typeof(validation) = 'object'),
  rule jsonb,
  mappings jsonb not null default '[]' check (jsonb_typeof(mappings) = 'array'),
  sort_order integer not null default 0,
  unique (version_id, key)
);
create index if not exists assessment_questions_version on public.assessment_questions (version_id, sort_order);

-- 2. Client assessments and findings.
create table if not exists public.client_assessments (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  client_id uuid not null references public.car_clients (id),
  enrolment_id uuid references public.client_enrolments (id),
  template_id uuid not null references public.assessment_templates (id),
  version_id uuid not null references public.assessment_versions (id),
  status text not null default 'draft' check (status in ('draft', 'completed', 'superseded', 'cancelled')),
  assessed_on date not null default ((now() at time zone 'Australia/Sydney')::date),
  answers jsonb not null default '{}' check (jsonb_typeof(answers) = 'object'),
  reused jsonb not null default '{}' check (jsonb_typeof(reused) = 'object'),
  replaces_id uuid references public.client_assessments (id),
  replaced_by uuid references public.client_assessments (id),
  started_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  completed_by uuid,
  completed_at timestamptz,
  cancelled_by uuid,
  cancelled_at timestamptz,
  cancel_reason text not null default '' check (length(cancel_reason) <= 300),
  updated_by uuid,
  updated_at timestamptz not null default now()
);
create index if not exists client_assessments_client on public.client_assessments (client_id, created_at desc);
create table if not exists public.assessment_findings (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  assessment_id uuid not null references public.client_assessments (id),
  client_id uuid not null references public.car_clients (id),
  kind text not null check (kind in ('need', 'goal', 'risk', 'limitation', 'support', 'intervention', 'frequency', 'equipment', 'preference')),
  text text not null check (length(trim(text)) between 1 and 1000),
  detail text not null default '' check (length(detail) <= 2000),
  origin text not null default 'manual' check (origin in ('manual', 'mapped')),
  source_key text,
  mapping_no integer,
  source_answer text,
  state text not null default 'active' check (state in ('active', 'withdrawn', 'answer_changed')),
  edited boolean not null default false,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now()
);
create unique index if not exists assessment_findings_one_per_mapping on public.assessment_findings (assessment_id, source_key, mapping_no) where origin = 'mapped';
create index if not exists assessment_findings_assessment on public.assessment_findings (assessment_id);

-- 3. Rules: "show only when". A rule is {"match": "all" | "any", "when": [condition, ...]};
-- a condition is {"q": key, "op": is | is_not | in | answered | not_answered | gt | lt, "value": ...}.
create or replace function public.assessment_condition_ok(p_cond jsonb, p_answer jsonb) returns boolean
language plpgsql immutable set search_path = '' as $$
declare
  v_op text := p_cond ->> 'op';
  v_val jsonb := p_cond -> 'value';
  v_answered boolean := p_answer is not null and p_answer <> 'null'::jsonb and p_answer <> '""'::jsonb and p_answer <> '[]'::jsonb;
  v_text text := case when jsonb_typeof(p_answer) = 'string' then p_answer #>> '{}' when jsonb_typeof(p_answer) = 'number' then p_answer::text end;
begin
  if v_op = 'answered' then return v_answered; end if;
  if v_op = 'not_answered' then return not v_answered; end if;
  if not v_answered then return false; end if;
  if v_op in ('is', 'is_not') then
    return (v_op = 'is') = (case when jsonb_typeof(p_answer) = 'array' then p_answer ? (v_val #>> '{}') else v_text = (v_val #>> '{}') end);
  elsif v_op = 'in' then
    if jsonb_typeof(v_val) <> 'array' then return false; end if;
    return case when jsonb_typeof(p_answer) = 'array' then p_answer ?| array(select jsonb_array_elements_text(v_val)) else v_val ? v_text end;
  elsif v_op in ('gt', 'lt') then
    if v_text !~ '^-?\d+(\.\d+)?$' or (v_val #>> '{}') !~ '^-?\d+(\.\d+)?$' then return false; end if;
    return case when v_op = 'gt' then v_text::numeric > (v_val #>> '{}')::numeric else v_text::numeric < (v_val #>> '{}')::numeric end;
  end if;
  return false;
end;
$$;

create or replace function public.assessment_rule_ok(p_rule jsonb, p_answers jsonb) returns boolean
language sql immutable set search_path = '' as $$
  select case
    when p_rule is null or p_rule = 'null'::jsonb or coalesce(jsonb_array_length(p_rule -> 'when'), 0) = 0 then true
    when coalesce(p_rule ->> 'match', 'all') = 'any' then
      exists (select 1 from jsonb_array_elements(p_rule -> 'when') c where public.assessment_condition_ok(c, p_answers -> (c ->> 'q')))
    else
      not exists (select 1 from jsonb_array_elements(p_rule -> 'when') c where not public.assessment_condition_ok(c, p_answers -> (c ->> 'q')))
  end
$$;

-- Is this question showing, given the answers?
create or replace function public.assessment_question_visible(p_question uuid, p_answers jsonb) returns boolean
language sql stable set search_path = '' as $$
  select s.enabled and public.assessment_rule_ok(s.rule, p_answers) and public.assessment_rule_ok(q.rule, p_answers)
    from public.assessment_questions q join public.assessment_sections s on s.id = q.section_id
   where q.id = p_question
$$;

-- What's wrong with one answer (null when it's fine).
create or replace function public.assessment_answer_problem(p_type text, p_options jsonb, p_validation jsonb, p_label text, p_value jsonb) returns text
language plpgsql immutable set search_path = '' as $$
declare
  v_text text;
begin
  if p_value is null or p_value = 'null'::jsonb or p_value = '""'::jsonb or p_value = '[]'::jsonb then
    return null;
  end if;
  if p_type = 'multi' then
    if jsonb_typeof(p_value) <> 'array' then return p_label || ': choose from the list.'; end if;
    if exists (select 1 from jsonb_array_elements_text(p_value) x where not p_options ? x) then return p_label || ': choose from the list.'; end if;
    return null;
  end if;
  if jsonb_typeof(p_value) not in ('string', 'number') then return p_label || ': that answer isn''t valid.'; end if;
  v_text := case when jsonb_typeof(p_value) = 'string' then p_value #>> '{}' else p_value::text end;
  if p_type = 'text' and length(v_text) > 300 then return p_label || ': keep it under 300 characters.'; end if;
  if p_type = 'long' and length(v_text) > 5000 then return p_label || ': keep it under 5,000 characters.'; end if;
  if p_type = 'yesno' and v_text not in ('Yes', 'No') then return p_label || ': answer Yes or No.'; end if;
  if p_type = 'choice' and not p_options ? v_text then return p_label || ': choose from the list.'; end if;
  if p_type = 'date' then
    if v_text !~ '^\d{4}-\d{2}-\d{2}$' then return p_label || ': enter a date.'; end if;
    begin
      perform v_text::date;
    exception when others then
      return p_label || ': enter a real date.';
    end;
  end if;
  if p_type = 'number' then
    if v_text !~ '^-?\d+(\.\d+)?$' then return p_label || ': enter a number.'; end if;
    if p_validation ? 'min' and v_text::numeric < (p_validation ->> 'min')::numeric then return p_label || ': the lowest is ' || (p_validation ->> 'min') || '.'; end if;
    if p_validation ? 'max' and v_text::numeric > (p_validation ->> 'max')::numeric then return p_label || ': the highest is ' || (p_validation ->> 'max') || '.'; end if;
  end if;
  if p_type in ('text', 'long') and p_validation ? 'pattern' and v_text !~ (p_validation ->> 'pattern') then
    return p_label || ': ' || coalesce(p_validation ->> 'pattern_hint', 'that answer isn''t in the expected format.');
  end if;
  return null;
end;
$$;

-- Everything that stops an assessment being completed (empty = ready).
create or replace function public.assessment_check(p_assessment uuid) returns text[]
language sql stable set search_path = '' as $$
  with a as (select * from public.client_assessments where id = p_assessment),
  q as (
    select q.*, s.sort_order as s_sort, public.assessment_question_visible(q.id, a.answers) as visible, a.answers -> q.key as answer, a.reused -> q.key as reuse
      from a join public.assessment_questions q on q.version_id = a.version_id join public.assessment_sections s on s.id = q.section_id
  )
  select coalesce(array_agg(msg order by s_sort, sort_order), '{}') from (
    select q.s_sort, q.sort_order, q.label || ' needs an answer.' as msg from q
     where q.visible and q.required and (q.answer is null or q.answer in ('null'::jsonb, '""'::jsonb, '[]'::jsonb))
    union all
    select q.s_sort, q.sort_order, 'Confirm the reused answer for ' || q.label || '.' from q
     where q.visible and q.reuse is not null and coalesce((q.reuse ->> 'confirmed')::boolean, false) = false
    union all
    select q.s_sort, q.sort_order, public.assessment_answer_problem(q.type, q.options, q.validation, q.label, q.answer) from q
     where q.visible and public.assessment_answer_problem(q.type, q.options, q.validation, q.label, q.answer) is not null
  ) m
$$;

-- 4. Template rules: only drafts change; publishing checks the version.
create or replace function public.guard_assessment_template() returns trigger
language plpgsql set search_path = '' as $$
begin
  if exists (select 1 from unnest(new.schemes) s where not exists (select 1 from public.client_schemes c where c.key = s)) then
    raise exception 'Choose schemes from the list.';
  end if;
  if tg_op = 'UPDATE' and new.created_by is distinct from old.created_by then
    raise exception 'Who made a template stays as it was.';
  end if;
  new.updated_at := now();
  return new;
end;
$$;

create or replace function public.guard_assessment_version() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_bad text;
begin
  if tg_op = 'DELETE' then
    raise exception 'A version is never deleted.';
  end if;
  if tg_op = 'INSERT' then
    if new.status <> 'draft' and public.from_portal() then
      raise exception 'A new version starts as a draft.';
    end if;
    new.version := coalesce((select max(v.version) from public.assessment_versions v where v.template_id = new.template_id), 0) + 1;
    return new;
  end if;
  if (new.template_id, new.version, new.created_by, new.created_at) is distinct from (old.template_id, old.version, old.created_by, old.created_at) then
    raise exception 'A version stays with its template.';
  end if;
  if old.status = 'retired' then
    raise exception 'A retired version stays retired.';
  end if;
  if old.status = 'published' then
    if new.status = 'retired' and (new.effective_from, new.published_by, new.published_at) is not distinct from (old.effective_from, old.published_by, old.published_at) then
      return new;
    end if;
    raise exception 'A published version can''t be changed. Make a new version instead.';
  end if;
  if new.status = 'retired' then
    raise exception 'Publish a version before retiring it.';
  end if;
  if new.status = 'published' then
    new.effective_from := coalesce(new.effective_from, (now() at time zone 'Australia/Sydney')::date);
    new.published_by := auth.uid();
    new.published_at := now();
    if not exists (select 1 from public.assessment_questions q where q.version_id = new.id) then
      raise exception 'Add at least one question before publishing.';
    end if;
    -- Choices need options; mappings and rules must be valid; rules look only at earlier questions.
    select string_agg(msg, ' ') into v_bad from (
      select q.label || ': add the options.' as msg from public.assessment_questions q
       where q.version_id = new.id and q.type in ('choice', 'multi') and jsonb_array_length(q.options) = 0
      union all
      select q.label || ': a finding has an unknown kind or wording missing.' from public.assessment_questions q, jsonb_array_elements(q.mappings) m
       where q.version_id = new.id and (not (m ->> 'kind') = any (array['need', 'goal', 'risk', 'limitation', 'support', 'intervention', 'frequency', 'equipment', 'preference'])
                                         or length(trim(coalesce(m ->> 'text', ''))) = 0)
      union all
      select q.label || ': "show only when" must look at an earlier question.' from public.assessment_questions q
        join public.assessment_sections s on s.id = q.section_id, jsonb_array_elements(coalesce(q.rule -> 'when', '[]')) c
       where q.version_id = new.id and not exists (
         select 1 from public.assessment_questions p join public.assessment_sections ps on ps.id = p.section_id
          where p.version_id = new.id and p.key = c ->> 'q' and (ps.sort_order, p.sort_order) < (s.sort_order, q.sort_order))
      union all
      select s.title || ': "show only when" must look at a question in an earlier section.' from public.assessment_sections s, jsonb_array_elements(coalesce(s.rule -> 'when', '[]')) c
       where s.version_id = new.id and not exists (
         select 1 from public.assessment_questions p join public.assessment_sections ps on ps.id = p.section_id
          where p.version_id = new.id and p.key = c ->> 'q' and ps.sort_order < s.sort_order)
    ) b;
    if v_bad is not null then
      raise exception 'Can''t publish yet: %', v_bad;
    end if;
    -- The earlier published version is retired.
    update public.assessment_versions set status = 'retired' where template_id = new.template_id and status = 'published' and id <> new.id;
  end if;
  return new;
end;
$$;

create or replace function public.guard_assessment_part() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_version uuid := case when tg_op = 'DELETE' then old.version_id else new.version_id end;
begin
  if (select status from public.assessment_versions where id = v_version) <> 'draft'
     or (tg_op = 'UPDATE' and old.version_id is distinct from new.version_id) then
    raise exception 'A published version can''t be changed. Make a new version instead.';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  if tg_table_name = 'assessment_questions' and (select version_id from public.assessment_sections where id = (to_jsonb(new) ->> 'section_id')::uuid) is distinct from new.version_id then
    raise exception 'That section belongs to another version.';
  end if;
  return new;
end;
$$;

-- A new draft version copied from the latest one (runs as the person).
create or replace function public.assessment_new_version(p_template uuid) returns uuid
language plpgsql set search_path = '' as $$
declare
  v_from uuid := (select id from public.assessment_versions where template_id = p_template order by version desc limit 1);
  v_new uuid;
  s record;
  v_sec uuid;
begin
  if exists (select 1 from public.assessment_versions where template_id = p_template and status = 'draft') then
    raise exception 'This template already has a draft. Edit that one.';
  end if;
  insert into public.assessment_versions (template_id) values (p_template) returning id into v_new;
  for s in select * from public.assessment_sections where version_id = v_from order by sort_order loop
    insert into public.assessment_sections (version_id, title, sort_order, enabled, rule) values (v_new, s.title, s.sort_order, s.enabled, s.rule) returning id into v_sec;
    insert into public.assessment_questions (version_id, section_id, key, label, type, required, help, options, validation, rule, mappings, sort_order)
    select v_new, v_sec, q.key, q.label, q.type, q.required, q.help, q.options, q.validation, q.rule, q.mappings, q.sort_order
      from public.assessment_questions q where q.section_id = s.id;
  end loop;
  return v_new;
end;
$$;
revoke execute on function public.assessment_new_version(uuid) from public, anon;
grant execute on function public.assessment_new_version(uuid) to authenticated;

-- 5. Assessment rules.
create or replace function public.guard_client_assessment() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_api boolean := public.from_portal();
  v_tpl public.assessment_templates;
  v_problems text[];
  v_key text;
  v_q public.assessment_questions;
  v_from public.client_assessments;
begin
  if tg_op = 'DELETE' then
    raise exception 'An assessment is never deleted. Cancel it instead.';
  end if;
  if tg_op = 'INSERT' then
    select * into v_tpl from public.assessment_templates where id = new.template_id;
    if (select v.template_id from public.assessment_versions v where v.id = new.version_id and v.status = 'published') is distinct from new.template_id then
      raise exception 'Choose a published assessment.';
    end if;
    if v_api and not v_tpl.active then
      raise exception 'That assessment isn''t in use any more.';
    end if;
    if new.enrolment_id is not null and not exists (select 1 from public.client_enrolments e where e.id = new.enrolment_id and e.client_id = new.client_id and e.status <> 'ended') then
      raise exception 'Choose one of the client''s open programs.';
    end if;
    if cardinality(v_tpl.schemes) > 0 and not exists (
         select 1 from public.client_enrolments e where e.id = new.enrolment_id and e.scheme = any (v_tpl.schemes)) then
      raise exception '% is for % clients. Choose the program it''s for.', v_tpl.name, array_to_string(v_tpl.schemes, ', ');
    end if;
    if new.replaces_id is not null and not exists (
         select 1 from public.client_assessments r where r.id = new.replaces_id and r.client_id = new.client_id and r.status = 'completed') then
      raise exception 'Only a completed assessment of this client can be replaced.';
    end if;
    if v_api then
      new.status := 'draft';
      new.started_by := auth.uid();
      new.created_at := now();
      new.replaced_by := null;
      new.completed_by := null; new.completed_at := null; new.cancelled_by := null; new.cancelled_at := null; new.cancel_reason := '';
    end if;
  else
    if (new.client_id, new.enrolment_id, new.template_id, new.version_id, new.replaces_id, new.started_by, new.created_at)
       is distinct from (old.client_id, old.enrolment_id, old.template_id, old.version_id, old.replaces_id, old.started_by, old.created_at) then
      raise exception 'An assessment stays with its client, program and version.';
    end if;
    if old.status = 'completed' then
      -- The only change: replaced by a newer completed assessment.
      if new.status = 'superseded' and new.replaced_by is not null and old.replaced_by is null
         and (new.answers, new.reused, new.assessed_on, new.completed_by, new.completed_at) is not distinct from (old.answers, old.reused, old.assessed_on, old.completed_by, old.completed_at)
         and exists (select 1 from public.client_assessments r where r.id = new.replaced_by and r.replaces_id = new.id and r.status = 'completed') then
        return new;
      end if;
      raise exception 'A completed assessment can''t be changed. Start a new assessment from it instead.';
    end if;
    if old.status in ('superseded', 'cancelled') then
      raise exception 'This assessment is %, so it can''t be changed.', old.status;
    end if;
    if new.replaced_by is distinct from old.replaced_by then
      raise exception 'Only a completed assessment can be replaced.';
    end if;
  end if;

  -- Answers: known questions, right type. Reused answers: same key and type as before.
  for v_key in select jsonb_object_keys(new.answers) loop
    select * into v_q from public.assessment_questions where version_id = new.version_id and key = v_key;
    if v_q.id is null then
      raise exception 'There''s no question "%" in this assessment.', v_key;
    end if;
    if public.assessment_answer_problem(v_q.type, v_q.options, v_q.validation, v_q.label, new.answers -> v_key) is not null then
      raise exception '%', public.assessment_answer_problem(v_q.type, v_q.options, v_q.validation, v_q.label, new.answers -> v_key);
    end if;
  end loop;
  if tg_op = 'INSERT' or new.reused is distinct from old.reused then
    for v_key in select jsonb_object_keys(new.reused) loop
      if tg_op = 'UPDATE' and old.reused ? v_key and (old.reused -> v_key -> 'from') = (new.reused -> v_key -> 'from') then
        continue; -- only the confirmation changed
      end if;
      if tg_op = 'UPDATE' then
        raise exception 'Answers can only be reused when the assessment is started.';
      end if;
      select * into v_from from public.client_assessments where id = (new.reused -> v_key ->> 'from')::uuid;
      if v_from.id is null or v_from.client_id <> new.client_id or v_from.status not in ('completed', 'superseded') then
        raise exception 'Answers can only be reused from this client''s completed assessments.';
      end if;
      if not exists (select 1 from public.assessment_questions a join public.assessment_questions b on b.key = a.key and b.type = a.type
                      where a.version_id = new.version_id and b.version_id = v_from.version_id and a.key = v_key) then
        raise exception 'The answer to "%" can''t be reused: the question isn''t the same kind.', v_key;
      end if;
    end loop;
  end if;
  if tg_op = 'UPDATE' then
    for v_key in select jsonb_object_keys(old.reused) loop
      if not new.reused ? v_key then
        raise exception 'A reused answer stays marked as reused.';
      end if;
    end loop;
  end if;

  if tg_op = 'UPDATE' and new.status <> old.status then
    if new.status = 'completed' then
      -- Checked against the new answers, not the saved ones.
      select coalesce(array_agg(msg), '{}') into v_problems from (
        select q.label || ' needs an answer.' as msg
          from public.assessment_questions q join public.assessment_sections s on s.id = q.section_id
         where q.version_id = new.version_id and q.required
           and s.enabled and public.assessment_rule_ok(s.rule, new.answers) and public.assessment_rule_ok(q.rule, new.answers)
           and (new.answers -> q.key is null or new.answers -> q.key in ('null'::jsonb, '""'::jsonb, '[]'::jsonb))
        union all
        select 'Confirm the reused answer for ' || q.label || '.'
          from public.assessment_questions q join public.assessment_sections s on s.id = q.section_id
         where q.version_id = new.version_id and new.reused ? q.key and coalesce((new.reused -> q.key ->> 'confirmed')::boolean, false) = false
           and s.enabled and public.assessment_rule_ok(s.rule, new.answers) and public.assessment_rule_ok(q.rule, new.answers)
        union all
        select 'Check the finding "' || left(f.text, 60) || '": its answer changed.'
          from public.assessment_findings f where f.assessment_id = new.id and f.state = 'answer_changed'
      ) m;
      if cardinality(v_problems) > 0 then
        raise exception 'Not ready to complete: %', array_to_string(v_problems, ' ');
      end if;
      new.completed_by := auth.uid();
      new.completed_at := now();
    elsif new.status = 'cancelled' then
      if length(trim(new.cancel_reason)) = 0 then
        raise exception 'Say why this assessment is cancelled.';
      end if;
      new.cancelled_by := auth.uid();
      new.cancelled_at := now();
    else
      raise exception 'A draft can only be completed or cancelled.';
    end if;
  end if;
  return new;
end;
$$;

-- After a change: keep mapped findings in step with the answers; mark the replaced one superseded.
create or replace function public.sync_assessment() returns trigger
language plpgsql set search_path = '' as $$
declare
  q record;
  m jsonb;
  n integer;
  v_applies boolean;
  v_answer text;
  f public.assessment_findings;
begin
  if tg_op = 'UPDATE' and new.status = 'completed' and old.status = 'draft' and new.replaces_id is not null then
    update public.client_assessments set status = 'superseded', replaced_by = new.id where id = new.replaces_id and status = 'completed';
  end if;
  if new.status <> 'draft' or (tg_op = 'UPDATE' and new.answers is not distinct from old.answers) then
    return null;
  end if;
  perform set_config('portal.findings_sync', 'on', true);
  for q in select aq.*, public.assessment_question_visible(aq.id, new.answers) as visible
             from public.assessment_questions aq where aq.version_id = new.version_id and jsonb_array_length(aq.mappings) > 0 loop
    v_answer := case when jsonb_typeof(new.answers -> q.key) = 'array' then (select string_agg(x, ', ') from jsonb_array_elements_text(new.answers -> q.key) x)
                     else new.answers ->> q.key end;
    n := 0;
    for m in select * from jsonb_array_elements(q.mappings) loop
      n := n + 1;
      v_applies := q.visible and public.assessment_condition_ok(coalesce(m -> 'when', '{"op": "answered"}'::jsonb), new.answers -> q.key);
      select * into f from public.assessment_findings where assessment_id = new.id and origin = 'mapped' and source_key = q.key and mapping_no = n;
      if v_applies then
        if f.id is null then
          insert into public.assessment_findings (assessment_id, client_id, kind, text, origin, source_key, mapping_no, source_answer)
          values (new.id, new.client_id, m ->> 'kind', replace(m ->> 'text', '{answer}', coalesce(v_answer, '')), 'mapped', q.key, n, v_answer);
        elsif not f.edited then
          update public.assessment_findings set kind = m ->> 'kind', text = replace(m ->> 'text', '{answer}', coalesce(v_answer, '')), source_answer = v_answer, state = 'active'
           where id = f.id and (kind, text, source_answer, state) is distinct from (m ->> 'kind', replace(m ->> 'text', '{answer}', coalesce(v_answer, '')), v_answer, 'active');
        elsif f.source_answer is distinct from v_answer then
          update public.assessment_findings set state = 'answer_changed', source_answer = v_answer where id = f.id;
        end if;
      elsif f.id is not null and f.state <> 'withdrawn' then
        update public.assessment_findings set state = case when f.edited then 'answer_changed' else 'withdrawn' end where id = f.id;
      end if;
    end loop;
  end loop;
  perform set_config('portal.findings_sync', '', true);
  return null;
end;
$$;

create or replace function public.guard_assessment_finding() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_sync boolean := coalesce(current_setting('portal.findings_sync', true), '') = 'on';
  v_a public.client_assessments;
begin
  if tg_op = 'DELETE' then
    raise exception 'A finding is never deleted. Withdraw it instead.';
  end if;
  select * into v_a from public.client_assessments where id = new.assessment_id;
  if v_a.status is distinct from 'draft' then
    raise exception 'Findings are fixed once the assessment is completed.';
  end if;
  new.client_id := v_a.client_id;
  if tg_op = 'INSERT' then
    if not v_sync then
      new.origin := 'manual';
      new.source_key := null;
      new.mapping_no := null;
      new.source_answer := null;
      new.state := 'active';
      new.edited := false;
      new.created_by := auth.uid();
    end if;
    return new;
  end if;
  if (new.assessment_id, new.origin, new.source_key, new.mapping_no, new.created_by, new.created_at)
     is distinct from (old.assessment_id, old.origin, old.source_key, old.mapping_no, old.created_by, old.created_at) then
    raise exception 'A finding stays with its assessment and source.';
  end if;
  if not v_sync then
    if new.source_answer is distinct from old.source_answer then
      raise exception 'The answer a finding came from stays as it was.';
    end if;
    if new.origin = 'mapped' and (new.text, new.detail, new.kind) is distinct from (old.text, old.detail, old.kind) then
      new.edited := true;
      if new.state = 'answer_changed' then
        new.state := 'active'; -- checked by the assessor
      end if;
    end if;
    if new.state not in ('active', 'withdrawn') and new.state is distinct from old.state then
      raise exception 'A finding can be active or withdrawn.';
    end if;
  end if;
  return new;
end;
$$;

do $$
declare t text;
begin
  foreach t in array array['assessment_templates', 'assessment_versions', 'assessment_sections', 'assessment_questions'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists "staff read assessment templates" on public.%I', t);
    execute format('create policy "staff read assessment templates" on public.%I for select to authenticated using ((select public.is_member()))', t);
    execute format('drop policy if exists "template managers change templates" on public.%I', t);
    execute format('create policy "template managers change templates" on public.%I for all to authenticated using ((select public.can_admin_area(''care'')) or (select public.is_manager_admin())) with check ((select public.can_admin_area(''care'')) or (select public.is_manager_admin()))', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('revoke all on public.%I from anon', t);
  end loop;
  foreach t in array array['client_assessments', 'assessment_findings'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists "see assessments" on public.%I', t);
    execute format('create policy "see assessments" on public.%I for select to authenticated using (public.can(''clients.assessments'', ''view'', client_id))', t);
    execute format('drop policy if exists "add assessments" on public.%I', t);
    execute format('create policy "add assessments" on public.%I for insert to authenticated with check (public.can(''clients.assessments'', ''edit'', client_id))', t);
    execute format('drop policy if exists "change assessments" on public.%I', t);
    execute format('create policy "change assessments" on public.%I for update to authenticated using (public.can(''clients.assessments'', ''edit'', client_id)) with check (public.can(''clients.assessments'', ''edit'', client_id))', t);
    execute format('grant select, insert, update on public.%I to authenticated', t);
    execute format('revoke all on public.%I from anon', t);
  end loop;
end $$;

