-- 20270421000001_financial_reporting.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270421000001_financial_reporting.sql') then
    return;
  end if;
  execute $m184$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 166): Phase 5D. Consolidated financial reporting (D-066; built under D-068).
-- Read-only views and checks over what Phases 4 and 5 recorded; nothing here changes a record.
--   * billing_revenue: every approved billing line and client charge in one place (date, client,
--     scheme, funding stream, value, client share, government share), for reports.
--   * billing_integrity_checks(): consistency checks a finance person runs (recoveries above the
--     service value, issued documents without their PDF, totals that don't add up, money allocated
--     beyond what's owed, claims approved but not submitted, unmatched bank lines, old drafts).
--   * Monthly Support at Home statements carry the detail of a full statement (owner's sample,
--     23 Nov 2026): funds carried in, the quarter month by month (subsidy against expenditure and
--     what's left), this month's income and expenditure (services, other charges, care
--     management), and each service and charge with its category, contribution rate and share.
--     Added to new statements only; issued statements never change.
-- All follow each person's Billing reach (security invoker). No new security definer function.
-- Safe to run again.

create or replace view public.billing_revenue with (security_invoker = true) as
  select 'line'::text as source, l.id, l.client_id, l.service_date, l.scheme, l.funding_stream, l.kind as detail, l.amount, l.client_share, l.government_share,
         l.quarter_budget_id, null::uuid as pathway_budget_id, l.funding_id, l.approved_at
    from public.billing_lines l where l.status = 'approved'
  union all
  select 'charge', c.id, c.client_id, c.service_date, c.scheme, c.funding_stream, c.description, c.amount, c.client_share, c.government_share,
         c.quarter_budget_id, c.pathway_budget_id, c.funding_id, c.approved_at
    from public.client_charges c where c.status = 'approved';

create or replace function public.billing_integrity_checks()
returns table (check_name text, severity text, problem_count bigint, detail text)
language sql stable set search_path = '' as $$
  select 'Recoveries above the service value', 'error',
         (select count(*) from (select coalesce(r.line_id, r.charge_id) as k, max(r.service_value) as v, sum(r.amount) as s from public.line_recoveries r group by 1) x where x.s > x.v),
         'A billing line or charge recovered (claimed plus invoiced) for more than its value.'
  union all
  select 'Issued invoices without their PDF', 'error',
         (select count(*) from public.invoices where status in ('issued', 'sent') and pdf_checksum is null), 'Issued invoices should have their stored PDF.'
  union all
  select 'Issued credit notes without their PDF', 'error',
         (select count(*) from public.credit_notes where status = 'issued' and pdf_checksum is null), 'Issued credit notes should have their stored PDF.'
  union all
  select 'Invoice totals that don''t match their lines', 'error',
         (select count(*) from public.invoices v where v.status in ('issued', 'sent')
             and v.subtotal <> (select coalesce(sum(i.amount), 0) from public.invoice_items i where i.invoice_id = v.id and i.status = 'live')),
         'An issued invoice''s subtotal differs from the sum of its lines.'
  union all
  select 'Claim totals that don''t match their lines', 'error',
         (select count(*) from public.claims c where c.status <> 'cancelled'
             and c.total_claimed <> (select coalesce(sum(i.claimed_value), 0) from public.claim_items i where i.claim_id = c.id and i.status = 'live')),
         'A claim''s total differs from the sum of its live lines.'
  union all
  select 'Money allocated beyond what''s owed', 'error',
         (select count(*) from public.invoice_balances where balance < -0.004 and refunded = 0 and credited = 0)
         + (select count(*) from public.claim_item_balances where paid + written_off > accepted + 0.004),
         'An invoice paid beyond its total (without a credit), or a claim line paid beyond what was accepted.'
  union all
  select 'Approved claims not yet submitted', 'warning',
         (select count(*) from public.claims where status = 'approved'), 'Upload the file in the government portal, then record the submission.'
  union all
  select 'Submitted claims without results after 30 days', 'warning',
         (select count(*) from public.claims c join public.claim_submissions s on s.claim_id = c.id
           where c.status in ('submitted', 'acknowledged') and s.submitted_at < now() - interval '30 days'
             and exists (select 1 from public.claim_items i where i.claim_id = c.id and i.status = 'live' and not exists (select 1 from public.claim_item_results r where r.claim_item_id = i.id))),
         'Record the government''s results (Claims).'
  union all
  select 'Payments not fully allocated', 'warning',
         (select count(*) from public.payment_balances where status = 'recorded' and unallocated > 0), 'Allocate them, or refund the credit.'
  union all
  select 'Unmatched bank lines', 'warning',
         (select count(*) from public.bank_statement_lines where status = 'unmatched'), 'Match or exclude them (Reconciliation).'
  union all
  select 'Drafts older than 14 days', 'info',
         (select count(*) from public.claims where status = 'draft' and prepared_at < now() - interval '14 days')
         + (select count(*) from public.invoices where status = 'draft' and prepared_at < now() - interval '14 days')
         + (select count(*) from public.client_charges where status = 'draft' and created_at < now() - interval '14 days')
         + (select count(*) from public.billing_lines where status = 'draft' and generated_at < now() - interval '14 days'),
         'Draft claims, invoices, charges or billing lines waiting more than two weeks.'
$$;

-- Statement detail (runs after the 163 snapshot and the 165 charges are added).
create or replace function public.statement_add_detail() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_end date := (new.month + interval '1 month' - interval '1 day')::date;
  b public.client_quarter_budgets;
  v_days integer;
  v_m date;
  v_months jsonb := '[]';
  v_from date;
  v_to date;
  v_sub numeric;
  v_exp numeric;
  v_cm numeric;
  v_svc numeric;
  v_chg numeric;
  v_month_sub numeric := 0;
  v_month_cm numeric := 0;
begin
  select * into b from public.client_quarter_budgets q where q.enrolment_id = new.enrolment_id and q.quarter_start <= new.month and q.quarter_end >= new.month and q.status <> 'draft';
  if b.id is not null then
    v_days := b.quarter_end - b.start_date + 1;
    v_m := date_trunc('month', b.quarter_start)::date;
    while v_m <= new.month loop
      v_from := greatest(v_m, b.start_date);
      v_to := least((v_m + interval '1 month' - interval '1 day')::date, b.quarter_end);
      -- The quarter's amount and care management spread by day (the budget's own days).
      v_sub := case when v_to < v_from then 0 else round(b.prorated_amount * (v_to - v_from + 1) / v_days, 2) end;
      v_cm := case when v_to < v_from then 0 else round(b.care_management * (v_to - v_from + 1) / v_days, 2) end;
      select coalesce(sum(amount), 0) into v_svc from public.billing_lines where quarter_budget_id = b.id and status = 'approved' and service_date between v_m and v_to;
      select coalesce(sum(amount), 0) into v_chg from public.client_charges where quarter_budget_id = b.id and status = 'approved' and service_date between v_m and v_to;
      v_months := v_months || jsonb_build_object('month', v_m, 'days', greatest(v_to - v_from + 1, 0), 'subsidy', v_sub, 'services', v_svc, 'charges', v_chg, 'care_management', v_cm, 'expenditure', v_svc + v_chg + v_cm);
      if v_m = new.month then v_month_sub := v_sub; v_month_cm := v_cm; end if;
      v_m := (v_m + interval '1 month')::date;
    end loop;
  end if;
  new.snapshot := new.snapshot || jsonb_build_object(
    'period_days', v_end - new.month + 1,
    'carried_in', jsonb_build_object(
      'rollover', coalesce(b.carryover_in, 0),
      'unspent_hcp', (select coalesce(sum(p.amount), 0) from public.client_pathway_budgets p where p.enrolment_id = new.enrolment_id and p.stream = 'hcp_unspent' and p.status <> 'draft' and p.starts_on <= v_end and p.ends_on >= new.month)),
    'quarter_months', v_months,
    'month_income', jsonb_build_object('subsidy', v_month_sub),
    'month_expenditure', jsonb_build_object(
      'services', (select coalesce(sum(amount), 0) from public.billing_lines where enrolment_id = new.enrolment_id and status = 'approved' and service_date between new.month and v_end),
      'other_charges', (select coalesce(sum(amount), 0) from public.client_charges where enrolment_id = new.enrolment_id and status = 'approved' and service_date between new.month and v_end),
      'care_management', v_month_cm),
    'service_lines', (select coalesce(jsonb_agg(jsonb_build_object('date', l.service_date, 'service', coalesce(sv.label, 'Service'), 'category', l.sah_category, 'pct', l.contribution_pct,
                        'quantity', l.quantity, 'unit', l.unit, 'rate', l.unit_price, 'band', l.band_label, 'kind', l.kind, 'amount', l.amount, 'client_share', l.client_share) order by l.service_date, l.starts_at), '[]')
                        from public.billing_lines l left join public.client_services sv on sv.id = l.service_id
                       where l.enrolment_id = new.enrolment_id and l.status = 'approved' and l.service_date between new.month and v_end),
    'charge_lines', (select coalesce(jsonb_agg(jsonb_build_object('date', c.service_date, 'description', c.description, 'stream', c.funding_stream, 'category', c.sah_category, 'pct', c.contribution_pct,
                        'amount', c.amount, 'client_share', c.client_share) order by c.service_date), '[]')
                       from public.client_charges c where c.enrolment_id = new.enrolment_id and c.status = 'approved' and c.service_date between new.month and v_end));
  return new;
end;
$$;
drop trigger if exists guard_statement_detail on public.client_statements;
create trigger guard_statement_detail before insert on public.client_statements for each row execute function public.statement_add_detail();
revoke execute on function public.statement_add_detail() from public, anon, authenticated;

grant select on public.billing_revenue to authenticated;
revoke all on public.billing_revenue from anon;
revoke execute on function public.billing_integrity_checks() from public, anon;
grant execute on function public.billing_integrity_checks() to authenticated;

$m184$;
  insert into public.install_log (name) values ('20270421000001_financial_reporting.sql');
end;
$part$;

-- ====================================================================
-- 20270422000001_service_codes.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270422000001_service_codes.sql') then
    return;
  end if;
  execute $m185$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 167): service codes and pricing from the catalogue (owner, 23 Nov 2026; D-072).
--   * One service catalogue for every scheme. Each service gets a code: the company prefix (setting
--     billing.service_code_prefix, "SERV" to start) and the next number, for example SERV-0001.
--     Existing services are coded now, in their catalogue order. A code can be changed until the
--     service has been billed; then it's locked. New services get the next code automatically.
--   * Support at Home service type: each service can be mapped to the government's service list
--     (for claims; the owner's nominee verifies it).
--   * Prices are chosen from the catalogue on screen. Prices for client services that aren't in the
--     catalogue yet (most existing client services) still match by name, so nothing stops billing;
--     pricing becomes catalogue-only with the later change that links every client service (and the
--     roster) to the catalogue. A list shows what isn't priced yet, either way.
--   * Monthly statements show each service's code.
-- No new security definer function. Safe to run again.

-- 1. The code prefix setting.
insert into public.app_settings (key, value, label, description, is_public)
values ('billing.service_code_prefix', '"SERV"', 'Service code prefix', 'Letters at the start of every service code, for example SERV-0001.', false)
on conflict (key) do nothing;

-- 2. Codes and the Support at Home service type on the catalogue.
alter table public.service_catalogue add column if not exists code text;
alter table public.service_catalogue add column if not exists sah_service_type text not null default '';
alter table public.service_catalogue drop constraint if exists service_catalogue_code_format;
alter table public.service_catalogue add constraint service_catalogue_code_format check (code is null or code ~ '^[A-Z0-9]{1,10}-[A-Z0-9]{1,10}$');
alter table public.service_catalogue drop constraint if exists service_catalogue_sah_type_length;
alter table public.service_catalogue add constraint service_catalogue_sah_type_length check (length(sah_service_type) <= 200);
create unique index if not exists service_catalogue_code_unique on public.service_catalogue (code) where code is not null;

-- The next code for the company prefix (numbers are never reused for that prefix).
create or replace function public.service_code_next() returns text
language sql volatile set search_path = '' as $$
  with p as (select coalesce(nullif(upper(regexp_replace(coalesce((select value #>> '{}' from public.app_settings where key = 'billing.service_code_prefix'), 'SERV'), '[^A-Za-z0-9]', '', 'g')), ''), 'SERV') as prefix)
  select p.prefix || '-' || lpad((coalesce((select max(substring(c.code from '-(\d+)$')::int) from public.service_catalogue c where c.code like p.prefix || '-%' and c.code ~ '-\d+$'), 0) + 1)::text, 4, '0')
    from p
$$;

-- Has the service been billed (its code is then locked)?
create or replace function public.service_billed(p_service uuid) returns boolean
language sql stable set search_path = '' as $$
  select exists (select 1 from public.billing_lines bl join public.price_items pi on pi.id = bl.price_item_id where pi.catalogue_id = p_service)
$$;

create or replace function public.guard_service_code() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.code := nullif(upper(trim(coalesce(new.code, ''))), '');
  new.sah_service_type := trim(coalesce(new.sah_service_type, ''));
  if tg_op = 'INSERT' then
    if new.code is null then new.code := public.service_code_next(); end if;
    return new;
  end if;
  if new.code is null then new.code := old.code; end if;
  if new.code is distinct from old.code and old.code is not null and public.service_billed(old.id) then
    raise exception 'This service has been billed, so its code % stays as it is.', old.code;
  end if;
  return new;
end;
$$;
drop trigger if exists guard_service_code on public.service_catalogue;
create trigger guard_service_code before insert or update on public.service_catalogue for each row execute function public.guard_service_code();
revoke execute on function public.guard_service_code() from public, anon, authenticated;

-- Code the services that have none yet, in catalogue order.
do $$
declare
  r record;
begin
  for r in select id from public.service_catalogue where code is null order by sort_order, name, id loop
    update public.service_catalogue set code = public.service_code_next() where id = r.id;
  end loop;
end $$;

-- 3. What isn't priced yet.
-- Catalogue services offered under a price list's scheme that have no price in its latest version.
create or replace view public.services_not_priced with (security_invoker = true) as
  -- Catalogue services offered under the list's scheme with no price in its latest version.
  select l.id as price_list_id, l.name as price_list, l.scheme, v.id as version_id, v.version, v.status, 'catalogue'::text as kind, c.id as service_id, c.code, c.name as service, null::uuid as client_id
    from public.price_lists l
    join lateral (select * from public.price_list_versions x where x.price_list_id = l.id and x.status in ('draft', 'published') order by x.version desc limit 1) v on true
    join public.service_catalogue c on c.active and (cardinality(c.schemes) = 0 or l.scheme = any (c.schemes))
   where l.active and not exists (select 1 from public.price_items i where i.version_id = v.id and (i.catalogue_id = c.id or (i.catalogue_id is null and lower(i.label) = lower(c.name))))
  union all
  -- Open client services not in the catalogue, priced by name, with no price of that name.
  select l.id, l.name, l.scheme, v.id, v.version, v.status, 'client_service', s.id, null, s.label, s.client_id
    from public.client_services s
    join public.client_programs p on p.id = s.program_id
    join public.price_lists l on l.active and l.scheme = p.scheme
    join lateral (select * from public.price_list_versions x where x.price_list_id = l.id and x.status in ('draft', 'published') order by x.version desc limit 1) v on true
   where s.catalogue_id is null and s.status <> 'ended'
     and not exists (select 1 from public.price_items i where i.version_id = v.id and i.catalogue_id is null and lower(i.label) = lower(s.label));
grant select on public.services_not_priced to authenticated;
revoke all on public.services_not_priced from anon;

-- 4. Statements show each service's code (adds to the update 166 statement detail).
create or replace function public.statement_add_codes() returns trigger
language plpgsql set search_path = '' as $$
begin
  if jsonb_typeof(new.snapshot -> 'service_lines') = 'array' then
    new.snapshot := jsonb_set(new.snapshot, '{service_lines}', (
      select coalesce(jsonb_agg(x.e || jsonb_build_object('code', coalesce(x.code, '')) order by x.n), '[]')
        from (select e, n, (select c.code from public.billing_lines bl join public.price_items pi on pi.id = bl.price_item_id join public.service_catalogue c on c.id = pi.catalogue_id where bl.id = (e ->> 'id')::uuid) as code
                from jsonb_array_elements(new.snapshot -> 'service_lines') with ordinality as t(e, n)) x));
  end if;
  return new;
end;
$$;
-- The detail lines need their billing line id for the code (added to update 166's function).
create or replace function public.statement_add_detail_ids() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_end date := (new.month + interval '1 month' - interval '1 day')::date;
begin
  if jsonb_typeof(new.snapshot -> 'service_lines') = 'array' then
    new.snapshot := jsonb_set(new.snapshot, '{service_lines}', (
      select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'date', l.service_date, 'service', coalesce(sv.label, 'Service'), 'category', l.sah_category, 'pct', l.contribution_pct,
               'quantity', l.quantity, 'unit', l.unit, 'rate', l.unit_price, 'band', l.band_label, 'kind', l.kind, 'amount', l.amount, 'client_share', l.client_share) order by l.service_date, l.starts_at), '[]')
        from public.billing_lines l left join public.client_services sv on sv.id = l.service_id
       where l.enrolment_id = new.enrolment_id and l.status = 'approved' and l.service_date between new.month and v_end));
  end if;
  return new;
end;
$$;
drop trigger if exists guard_statement_ids on public.client_statements;
create trigger guard_statement_ids before insert on public.client_statements for each row execute function public.statement_add_detail_ids();
drop trigger if exists guard_statement_zcodes on public.client_statements;
create trigger guard_statement_zcodes before insert on public.client_statements for each row execute function public.statement_add_codes();
revoke execute on function public.statement_add_codes() from public, anon, authenticated;
revoke execute on function public.statement_add_detail_ids() from public, anon, authenticated;
revoke execute on function public.service_code_next() from public, anon;
grant execute on function public.service_code_next() to authenticated;

-- 5. Who sets the code prefix: Manager Administrators and the Billing prices right (letters and digits, up to 10).
drop policy if exists "billing sets the service code prefix" on public.app_settings;
create policy "billing sets the service code prefix" on public.app_settings for update to authenticated
  using (key = 'billing.service_code_prefix' and ((select public.is_manager_admin(auth.uid())) or (select public.billing_can('prices'))))
  with check (key = 'billing.service_code_prefix' and ((select public.is_manager_admin(auth.uid())) or (select public.billing_can('prices'))) and (value #>> '{}') ~ '^[A-Za-z0-9]{1,10}$');

$m185$;
  insert into public.install_log (name) values ('20270422000001_service_codes.sql');
end;
$part$;

-- ====================================================================
-- 20270423000001_document_templates.sql
-- ====================================================================
do $part$
begin
  if exists (select 1 from public.install_log where name = '20270423000001_document_templates.sql') then
    return;
  end if;
  execute $m186$
-- Staff Portal · © cmeproject. All rights reserved.
--
-- cmeprojects (update 168): document templates for invoices, statements, receipts and credit notes
-- (owner, 23 Nov 2026; D-072). Documents use the current logo, theme colours and business details;
-- each kind has template settings (layout, which sections show, logo position, colours, header and
-- footer text). Templates are saved as versions (never changed); each issued document records the
-- version it used, so it can always be explained. The business name, ABN and address always print;
-- "Tax invoice" wording and GST print only when they apply (GST-registered business and a taxable
-- line, decided when the invoice is issued). No template setting changes either (review C5).
-- No new security definer function. Safe to run again.

create table if not exists public.document_templates (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  kind text not null check (kind in ('invoice', 'statement', 'receipt', 'credit_note')),
  version integer not null default 1,
  settings jsonb not null default '{}' check (jsonb_typeof(settings) = 'object'),
  note text not null default '' check (length(note) <= 300),
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (kind, version)
);

-- Which template version each issued document used (added when the document's PDF is made).
create table if not exists public.document_issues (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id(),
  kind text not null check (kind in ('invoice', 'statement', 'receipt', 'credit_note')),
  document_id uuid not null,
  template_id uuid references public.document_templates (id),
  template_version integer,
  checksum text not null default '',
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (kind, document_id)
);

create or replace function public.guard_document_template() returns trigger
language plpgsql set search_path = '' as $$
declare
  v_layout text;
begin
  if tg_op <> 'INSERT' then raise exception 'A template version never changes. Save a new version.'; end if;
  if public.from_portal() and not (public.billing_can('prices') or public.billing_can('approve') or public.is_system_admin()) then
    raise exception 'Only someone with the Billing prices or approve right changes document templates.';
  end if;
  v_layout := coalesce(new.settings ->> 'layout', 'full');
  if v_layout not in ('full', 'compact') then raise exception 'Choose the full or compact layout.'; end if;
  if coalesce(new.settings ->> 'logo_position', 'left') not in ('left', 'centre', 'right', 'none') then raise exception 'Choose where the logo goes.'; end if;
  if coalesce(new.settings ->> 'colour_source', 'theme') not in ('theme', 'custom') then raise exception 'Choose theme or custom colours.'; end if;
  if (new.settings ? 'primary' and coalesce(new.settings ->> 'primary', '') !~ '^#[0-9A-Fa-f]{6}$') or (new.settings ? 'accent' and coalesce(new.settings ->> 'accent', '') !~ '^#[0-9A-Fa-f]{6}$') then
    raise exception 'Colours are written like #134F8E.';
  end if;
  if length(coalesce(new.settings ->> 'header_note', '')) > 300 or length(coalesce(new.settings ->> 'footer_text', '')) > 300 or length(coalesce(new.settings ->> 'payment_note', '')) > 500 then
    raise exception 'Keep header and footer text short (300 characters; payment note 500).';
  end if;
  new.version := coalesce((select max(version) from public.document_templates where kind = new.kind), 0) + 1;
  new.created_by := auth.uid(); new.created_at := now();
  return new;
end;
$$;
create or replace function public.guard_document_issue() returns trigger
language plpgsql set search_path = '' as $$
begin
  if tg_op <> 'INSERT' then raise exception 'A document''s template record never changes.'; end if;
  new.created_by := auth.uid(); new.created_at := now();
  if new.template_id is not null then new.template_version := (select version from public.document_templates where id = new.template_id); end if;
  return new;
end;
$$;
drop trigger if exists guard_document_template on public.document_templates;
create trigger guard_document_template before insert or update or delete on public.document_templates for each row execute function public.guard_document_template();
drop trigger if exists guard_document_issue on public.document_issues;
create trigger guard_document_issue before insert or update or delete on public.document_issues for each row execute function public.guard_document_issue();
drop trigger if exists log_billing_setup on public.document_templates;
create trigger log_billing_setup after insert on public.document_templates for each row execute function public.log_car_setup('document_template');
drop trigger if exists stamp_billing_setup on public.document_templates;
create trigger stamp_billing_setup before insert on public.document_templates for each row execute function public.stamp_billing_updated();

alter table public.document_templates enable row level security;
drop policy if exists "billing see document_templates" on public.document_templates;
create policy "billing see document_templates" on public.document_templates for select to authenticated using (public.billing_can('view') or public.is_system_admin());
drop policy if exists "billing add document_templates" on public.document_templates;
create policy "billing add document_templates" on public.document_templates for insert to authenticated with check (public.billing_can('prices') or public.billing_can('approve') or public.is_system_admin());
grant select, insert on public.document_templates to authenticated;
revoke all on public.document_templates from anon;
alter table public.document_issues enable row level security;
drop policy if exists "billing see document_issues" on public.document_issues;
create policy "billing see document_issues" on public.document_issues for select to authenticated using (public.billing_can('view'));
drop policy if exists "billing add document_issues" on public.document_issues;
create policy "billing add document_issues" on public.document_issues for insert to authenticated
  with check (public.billing_can('invoice_issue') or public.billing_can('payment_record') or public.billing_can('invoice_prepare'));
grant select, insert on public.document_issues to authenticated;
revoke all on public.document_issues from anon;
revoke execute on function public.guard_document_template() from public, anon, authenticated;
revoke execute on function public.guard_document_issue() from public, anon, authenticated;

-- A first template of each kind: the full layout in the portal's theme.
insert into public.document_templates (kind, settings, note)
select k, jsonb_build_object('layout', 'full', 'logo_position', 'left', 'colour_source', 'theme', 'sections', '{}'::jsonb, 'header_note', '', 'footer_text', '', 'payment_note', ''), 'Starting template'
  from unnest(array['invoice', 'statement', 'receipt', 'credit_note']) k
 where not exists (select 1 from public.document_templates t where t.kind = k);

$m186$;
  insert into public.install_log (name) values ('20270423000001_document_templates.sql');
end;
$part$;

